window.__D("text/likkutei-sichot/c165",{"p":[[1300251311,"האמור בנוגע צו ששה בחשון (אַז דעמולט האָט זיך פאַרענדיקט די תקופה פון עלי' לרגל, און אנגעהויבן די עבודה כל אחד במקומו) איז קיים אויך איצטער בזמן הגלות ובחוץ לארץ.\nובמכ\"ש וק\"ו: מה־דאַך אַז „ונשלמה12 פרים שפתינו\"13 אפילו בנוגע צו הקרבת הקרבנות וואָס זיינען אסור בזמן הזה, עאכו\"כ אַז דער ענין פון ששה ושבעה בחשון איז קיים אויך איצטער — וואָרום אויך בזמן הזה איז די הלכה והנהגה במעשה בפועל אַז מ'איז שואל גשמים בארץ ישראל14 אָנהויבנדיק פון שבעה בחשון15 (צוליב דעם טעם „כדי שיגיע אחרון שבישראל לנהר פרת\"), און אויך „לאחר החורבן היו מתאספים ג\"כ מכל הסביבות בירושלים לרגל, כמו שעושין גם היום\"16.\nביז אַז דאָס איז אויך נוגע בזמן הזה אין חוץ לארץ — ווי דער דין איז17, אַז אויב מ'האָט געשריבן אין אַ שטר „אחר הרגל\", איז די כוונה בזה — „ט\"ו יום אחר הרגל\", ווייל ביז דאַן איז נאָך „כאילו . . עסוקים בעניני הרגל\".\nדאָס הייסט, אַז אויך בזמן הזה ובחוץ לארץ איז ששה בחשון דער סיום התקופה פון די עבודה בחודש תשרי (ובמיוחד בחג הסוכות) און התחלת התקופה פון די עבודה בעולם.\nג. עפ\"ז איז פאַרשטאַנדיק, אַז דער תכלית השלימות פון „ויעקב הלך לדרכו\"18 — ווען אַ איד גייט אַרויס פון חודש תשרי בכדי מקיים זיין שליחותו בעולם — הויבט זיך אָן (בעיקר) נאָך ששה בחשון, ווען יעדער איד (אפילו דער „אחרון שבישראל\") איז שוין אָנ־געקומען לביתו און הויבט אָן טאָן עבודתו בקיום שליחותו בעולם.\nדערפון איז אויך מובן, אַז וויבאַלד דער עיקר ענין פון „ויעקב הלך לדרכו\" הויבט זיך אָן נאָך ששה בחשון (ווייל ביז דעמולט איז „כאילו . . עסוקים בעניני הרגל\"), דאַרף דעמולט זיין מעין דער באַוואָרעניש פון שולל זיין דעם „קשה עלי פרידתכם\"19 וואָס איז געווען לאחרי שמע\"צ דורך „עכבו עוד יום אחד\"19.\nד. דער ענין (וואָס איז גילטיק פאַר אַלע אידן בכל מקום ומקום) — דריקט זיך אויס נאָכמער בגלוי דאָרט וואו מ'זעט בגלוי ווי „עושים גם היום\" מעין ודוגמת הענין פון עלי' לרגל:\nבנוגע דעם תוכן הענין פון עלי' לרגל בעבודה הרוחנית בנפש האדם — איז מבואר בכ\"מ20, אַז „משחרב ביהמ\"ק,",[["12","12","מלשון תשלומין, וגם מלשון שלימות (ראה לקו\"ת ראה ל, רע\"ג. ובכ\"מ)."],["13","13","הושע יד, ג. וזהו זכר להקרבת הקרבנות — נוסף על זה שתפלות במקום קרבנות תקנום (ראה ברכות כו, א־ב. רע\"מ בזח\"ג כח, ב). ועפ\"ז יומתק אמירת פסוקי הקרבנות, „ונשלמה פרים שפתינו\" (ראה שו\"ע או\"ח ס\"א ס\"ט. סו\"ס תפ\"ח וסתקצ\"א)."],["14","14","שמתמציתה שותה כל העולם כולו (ראה תענית י, רע\"א)."],["15","15","ונפק\"מ לדינא גם בחו\"ל — „טעה היחיד ושאל מטר מז' מרחשון ואילך אינו מחוייב לחזור\" (שו\"ע אדה\"ז או\"ח סקי\"ז סוס\"א. וש\"נ)."],["16","16","שו\"ע אדה\"ז שם."],["17","17","ש\"ך חו\"מ שם."],["18","18","לשון הכתוב — ויצא לב, ב. וראה אגרות קודש אדמו\"ר מהוריי\"צ ח\"א ע' קצד. לקו\"ש חט\"ו ע' 259 ואילך. וש\"נ. מכתב ל' תשרי ר\"ח מרחשון תשמ\"ז (בסה\"ש תשמ\"ז ח\"ב בהוספות) וש\"נ."],["19","19","פרש\"י פינחס כט, לו. אמור כג, לו. בחיי פינחס שם, לה."],["20","20","לקו\"ת ברכה צח, ב. וראה סידור עם דא\"ח רעו, א. ס' הליקוטים־דא\"ח צ\"צ ערך בית הכנסת. וש\"נ."]]],[1300251312,"הגם שאין אנו יכולין להשתחוות („עיקר הראי' היא ההשתחוואה שהי' משתחווה ויוצא\"), עכ\"פ נתפשטה קדושת הארה זו אפס קצהו במקדש מעט21, בהכ\"נ ובהמ\"ד\", ועאכו\"כ — בהכנ\"ס ובהמ\"ד מיוחדים, וע\"ד — דער ביהכנ\"ס וביהמ\"ד פון כ\"ק מו\"ח אדמו\"ר נשיא דורנו22.\nאון אַזוי „עושים גם היום\" — אַז כמה וכמה עשיריות ומאות מישראל זיינען זיך מטלטל („טלטולי דגברא\" און „טלטולי דאיתתא\"<sup data-n=\"23\">23</sup> מביתם ומקומם בכדי פּראַווען די מועדים פון חודש תשרי אין די ד' אמות (גשמיים) פון נשיא דורנו, מעין ודוגמא וזכר צו דער עלי' לרגל בזמן שביהמ\"ק הי' קיים.\nאיז דערפון מובן, אַז דער ענין הנ\"ל (בנוגע לששה ושבעה בחשון) איז נאָכ־מער בגלוי באַ די אורחים וואָס זיינען געקומען אַהערצו צו פאָרן פאַר חודש תשרי:\nאַ חלק פון די אורחים זיינען צוריק־געפאָרן למקומם לאחרי שמע\"צ ושמח\"ת. אָבער אעפ\"כ, איז דער סיום וגמר הרגל אויך פאַר זיי — דוקא בששה ושבעה בחשון, וואָרום ביז דעמולט איז נאָך „כאילו . . עסוקים בעניני הרגל\", ווייל אפילו אויב זיי זיינען בדרך (אָדער אפילו שוין אָנגע־קומען למקומם) איז במקום שמחשבתו של אדם שם הוא נמצא. וכמשל כ\"ק מו\"ח אדמו\"ר24, אַז אַוועקגייענדיק פון די סעודה25 ושמחה גדולה פון חודש תשרי, נעמט מען מיט די „שיריים\"26 וואָס זיינען געבליבן פון דער סעודה (זייענדיק אַ סעודה בשלימותה, באופן פון די והותר), און מ'איז נהנה פון די שיריים אויך בדרך, ובפרט בתחנה הראשונה (ששה ושבעה בחשון);\nאון לאחרי ששה בחשון, פאַנגט זיך אָן דער (עיקר) עבודה פון „ויעקב הלך לדרכו\".\nנאָכמער בהדגשה ובגלוי שטייט עס באַ די אורחים וועלכע האָבן זיך ניט גע־איילט אַוועקפאָרן פון די ד' אמות און זיינען געבליבן ביז ששה בחשון, און וועלן דערנאָך פאָרן למקומם (ניט אום שבת גערעדט) נאָך ששה בחשון — זעט מען באַ זיי בגלוי, אַז ביז ששה בחשון איז נאָך אַ המשך וסיום פון דעם רגל, „דומה להם כאילו הם עדיין . . עסוקים בעניני הרגל\", און ערשט דערנאָך הויבט זיך באַ זיי אָן „ויעקב הלך לדרכו\", יעדערער לביתו ולמקומו וואו ער געפינט זיך ע\"פ ההשגחה העליונה צו דאָרט מקיים זיין תפקידו ושליחותו, „לשכן שמו שם\"27.",[["21","21","יחזקאל יא, טז. מגילה כט, א."],["22","22","להעיר מ„התמים\" חוברת ב ע' קכו [קי, ב] דברי אחד מזקני חסידי האמיל בימי הצ\"צ: מיום שחרב ביהמ\"ק וקד\"ק עד אשר ירחם הש\"ית וישלח לנו גואל צדק . . ויבנה לנו את ירושלים וביהמ\"ק עם הקד\"ק, הנה ליובאוויטש הוא ירושלים שלנו, והבית הכנסת אשר כ\"ק אדמו\"ר מתפלל בו הוא ביהמ\"ק שלנו וכו'."],["23","23","ראה כתובות כח, א. סנהדרין כו, רע\"א."],["24","24","ראה גם שיחת שמע\"צ תש\"ז (הועתק בהקדמה לקונט' פה — סה\"מ תשי\"א ע' 78 ואילך) בענין שמע\"צ ושמח\"ת, אַז אף אַ יריד קויפט מען איין די סחורה, און קומענדיק אַהיים — במשך ימות השנה — פּאַקט מען עס פאַנאַנדער און מען הייבט אָן טאָן דערמיט וואָס מ'דאַרף טאָן."],["25","25","ראה במדב\"ר פכ\"א, ד. תנחומא פינחס טז (באבער — טו). רד\"ה ביום השמע\"צ תרס\"ז, תרפ\"ה, תש\"ח (הא')."],["26","26","ראה גם לקו\"ש ח\"ב ע' 449."],["27","27","ל' הכתוב — תבוא כו, ב. וראה תורת הבעש\"ט עה\"פ („היום יום\" ח\"י אלול. כש\"ט (הוצאת קה\"ת) הוספות ס\"ג. וש\"נ)."]]],[1300251313,"ה. דערפון איז מובן, אַז אויך די באַוואָרעניש פון שלילת „(קשה עלי) פרידתכם\" איז נוגע עוד יותר בנוגע צו די וואָס זייער „פרידתכם\" (נסיעה) בפועל וועט זיין ערשט נאָך ששה בחשון (אע\"פ וואָס ששה בחשון הויבט זיך אָן דער (עיקר) „פרידתכם\" פון אַלע אידן, אויך פון די וואָס זיינען אַוועקגעפאָרן פאַר ששה בחשון).\nועוד ועיקר: אע\"פ וואָס מ'האָט שוין לכאורה באַוואָרנט דעם „קשה עלי פרידתכם\" בשמע\"צ (דורך „עכבו עוד יום אחד\") — איז אָבער וויבאַלד אַז בששה בחשון הויבט זיך אָן דער אמת'ער „פרידתכם\" (ווייל ביז דעמולט איז „כאילו . . עסוקים בעניני הרגל\" — אין דער זעלבער זאַך), ובפרט אַז עס זיינען דאָ אַזוינע אידן וואָס באַ זיי הויבט עס דעמולט אָן בפועל — דאַרף מען עס דעמולט נאָכאַמאָל (און נאָך שטאַרקער) באַוואָרענען, וואָרום דער „פרידתכם\" נאָך ששה בחשון קען אויך „מעורר\" זיין דעם „פרידתכם\" נאָך שמע\"צ. ע\"ד הכלל בהלכה28 פון חוזר וניעור (בפרט באַ מין במינו).\nאון נאָכמער — מ'דאַרף עס באַ־וואָרענען אויך באַ די וואָס בלייבן במקומם הם, וואו זיי זיינען געווען במשך הרגל, וואָרום אויך באַ זיי הויבט זיך אָן נאָך ששה בחשון דער (עיקר) ענין פון „ויעקב הלך לדרכו\" און „פרידתכם\" — זיי „גייען אַוועק\" פון דעם מצב נעלה ורוחני בשעת הרגל ובמשך גאַנץ חודש תשרי, „מרובה במועדות\"29, און „גייען אַריין\" אין די עבודה פון עובדין דחול, „לדרכו\", יעדערער צו זיינע וואָכעדיקע ענינים, אין מאַכן אַ דירה לו ית' בתחתונים.\nו. ווי באַוואָרנט מען דעם „קשה עלי פרידתכם\"? איז דאָס פאַרשטאַנדיק פון דעם דיוק הלשון עצמו: א) לכאורה האָט געדאַרפט שטיין „קשה עלי פרידתנו\", ניט „פרידתכם\"? ב) וואָס הייסט „קשה עלי\" לגבי דעם אויבערשטן?!\nאיז דער ביאור בזה30: מצד דעם אויבערשטן איז קיינמאָל ניטאָ קיין פירוד ח\"ו צווישן אים מיט אידן. נאָר דער פירוד איז ח\"ו צווישן אידן („פרידתכם\") — מצד דעם וואָס זיי פאָרן זיך פאַנאַנדער (נאָך שמע\"צ און נאָך ששה בחשון) כל אחד למקומו, וואָס דאָס לאָזט אַן אָרט אויף פירוד צווישן אידן, וואָס דאָס ברענגט אויך אַ פירוד ח\"ו צווישן אידן מיטן אויבערשטן.\nאון אויף דעם זאָגט דער אויבער־שטער „קשה עלי\" — וואָרום „הכל בידי שמים חוץ מיראת שמים\"31, יראת שמים איז כביכול ניט אין די „הענט\" פון דעם אויבערשטן, נאָר אָפגעגעבן לבחירת האדם („פרידתכם\"), ס'איז תלוי אין אים אַליין צו האָבן יראת שמים, און אַז די יראת שמים זאָל מבטל זיין דעם „פרידתכם\".\nאון אויף דעם גיט דער אויבערשטער די עצה „עכבו עוד יום אחד\", וואָס אין דעם „יום אחד\" (שמע\"צ) ווערן אידן נתאחד בתכלית השלימות32, און עס",[["28","28","ראה אנציקלופדי' תלמודית (כרך יג) בערכו. וש\"נ."],["29","29","שו\"ע אדה\"ז או\"ח סתצ\"ב ס\"ב. ועוד."],["30","30","ראה גם לקו\"ש ח\"ב ע' 433 ואילך. שיחת כ\"ה תשרי תשמ\"ז ביחידות הכללית להאורחים שיחיו."],["31","31","ברכות לג, ב."],["32","32","נוסף על האחדות שנפעלה ע\"י עלי' לרגל — כדאיתא בירושלמי (חגיגה פ\"ג ה\"ו) „עיר שחוברה לה יחדיו עיר שהיא עושה כל ישראל לחברים . . בשעה ששם עלו שבטים (בשעת הרגל)\". ולהעיר גם מהנס ד„עומדים צפופים ומשתחוים"]]],[1300251314,"ווערט נתגלה ווי זיי זיינען אַן „אומה יחידה\"33 (ווי דאָס דריקט זיך אויס אין הקרבת „פר אחד\"34 בשמע\"צ), ביז אַז די התאחדות גיט כח צו שולל זיין דעם „(קשה עלי) פרידתכם\" אויך לאחרי שמע\"צ ושמח\"ת וששה בחשון, ווען עס ווערט דער „ויעקב הלך לדרכו\", כל אחד לדרכו, וואָרום באַ יעדער איד הערט זיך אָן, אויך אין זיין עבודה פרטית ב„דרכו\", ווי ער איז איין זאַך מיט אַלע אַנדערע אידן (פון דער „אומה יחידה\"), און זיין עבודה פרטית איז נוגע צו שלימות העבודה פון אַלע אַנדערע אידן, און אויך לאידך גיסא — אַז לשלימות עבודתו דאַרף ער אָנקומען צו די עבודה פון אַלע אַנדערע אידן. און דורך די התאחדות צווישן אידן — ווערן אידן אויך נתאחד (בגלוי) מיטן אויבערשטן — היפך פון „קשה עלי פרידתכם\".\nובפשטות: אַז אויך במשך כל השנה כולה ווען יעדער איד איז מקיים שליחותו הפרטית בעולם — איז ער זיך מתאחד מיט אַנדערע אידן, הן ברוחניות, והן ובעיקר — בגשמיות,\nובכללות — אין זיין עבודה בהשלשה עמודים שעליהם העולם עומד — תורה, עבודה (תפלה) וגמילות חסדים35 (וואָס זיי זיינען כולל כל התומ\"צ) — אַז ער טוט די אַלע ענינים בצבור ובאחדות מיט אַנדערע אידן: תפלה בצבור, שיעורי תורה ברבים, ועאכו\"כ גמ\"ח וצדקה (כללות כל המצוות<sup data-n=\"36\">36</sup> — וואָס איז מאחד אידן37. וואָס דאָס (עבודה בציבור) גיט צו אין שלימות העבודה (אויך עבודתו הפרטית)38.\nאון פון התאחדות ישראל בעניני תומ\"צ, ווערט עס נמשך אין אַלע אַנדערע ענינים, אויך עניני רשות, „כל מעשיך יהיו לשם שמים\"39, און „בכל דרכיך דעהו\"40.\nז. ובפרטיות יותר:\nבכדי שולל זיין בשלימות ובתכלית דעם „(קשה עלי) פרידתכם\" צווישן כללות בני ישראל — דאַרף יעדער איד לכל לראש אויפטאָן העדר הפירוד („פרידתכם\") צווישן זיינע עשר כחות הנפש (עולם קטן זה האדם41)42:",[["","","רווחים\" (אבות פ\"ה מ\"ה), שיל\"פ שע\"י הביטול (משתחוים) — נעשה „רווחים\", ועד שכתוצאה מזה נעשה בירושלים כולה, ש„לא אמר אדם לחבירו צר לי המקום שאלין בירושלים\" (אבות שם)."],["33","33","סוכה נה, ב."],["34","34","פינחס ל, לו. סוכה שם. וראה מדרשים שבהערה 25."],["35","35","אבות פ\"א מ\"ב."],["36","36","ראה ב\"ב ט, א. תניא פל\"ז. ובכ\"מ."],["37","37","ראה ברכות ח, א: פדה בשלום נפשי . . כל העוסק בתורה ובגמ\"ח ומתפלל עם הצבור — שכולם שלום ואחדות — ראה פרש\"י שם. אוה\"ת לתהלים (יהל אור) עה\"פ."],["38","38","בנוגע לתפלה בצבור — כמ\"ש „הן א־ל כביר ולא ימאס\" (איוב לו, ה. ברכות שם. רמב\"ם הל' תפלה רפ\"ח. שו\"ע אדה\"ז או\"ח ר\"ס נב. סק\"א ס\"ה). וראה גם ר\"ה יח, א. בנוגע לתורה ברבים — ראה אבות פ\"ג מ\"ו. ברכות ו, א. אגה\"ק סכ\"ג. בנוגע לצדקה וגמ\"ח (כללות כל המצוות) ברבים — ראה אגה\"ק שם. וראה לקו\"ש ח\"ה ע' 423 הערה 11. ע' 428 הערה 14."],["39","39","אבות פ\"ב מי\"ב."],["40","40","משלי ג, ו."],["41","41","תנחומא פקודי ג. תקו\"ז תס\"ט (ק, ב. קא, א). ועוד."],["42","42","כי נוסף לזה שבכחו של כל א' להכריע (נוסף לעצמו) את כל העולם כולו כו' (רמב\"ם הל' תשובה פ\"ג ה\"ד) — הרי „פרידתכם\" בכחות נפשו יכול לפעול „חוזר וניעור\" ד„פרידתכם\" של כל בני ישראל, כנ\"ל ס\"ה."]]],[1300251315,"אַמאָל קען ווערן אַ מציאות פון „פרידתכם\" בכחות הנפש של האדם — אַ פירוד בין שכל ומדות שלו (חב\"ד און חג\"ת), אַז ער האָט אַ פאַרשטאַנד אין אלקות און אין דעם הכרח אויף עבודת ה', אָבער דאָס קומט ניט אַראָפּ אין מדות שבלב (דער ענין פון קליפת עמלק)43, אָדער אַ פירוד בין שכל ומדות און מעשה בפועל (נה\"י ומלכות, רוח וגוף)44, ווי יעדערער פילט עס במוחש באַ זיך.\nובפרט בשעת מ'האַלט באַ דער התחלה פון „ויעקב הלך לדרכו\" (נאָך ששה בחשון), ווען יעדער איד גייט אַוועק פון דעם מצב נעלה בחודש תשרי און גייט אַריין אין זיין עבודה אין וואָכעדיקע זאַכן. גיט דאָס אַן אפשריות אויף ברענגען אַ מצב פון „פרידתכם\" בין כחות הנפש שלו — ווייל די גלייך־גילטיקייט און קאַלטקייט פון וועלט (עמלק<sup data-n=\"45\">45</sup> האָבן אויף אים אַ השפעה אַז עס זאָל ווערן אַ פירוד בין מוחין למדות, ובין מעשה בפועל.\nאון בכדי באַוואָרענען דעם „(קשה עלי) פרידתכם\" בין עשר כחות נפשו — איז די עצה „עכבו עוד יום אחד\", צוזאַמענקלייבן און מאַכן „אחד\" אין „ציבור\" פון זיינע עשר כחות הנפש46. וואָס דאָס איז דורך דעם ענין והקדמה פון קבלת עול ויראת שמים, ביז אַז דאָס נעמט דורך כל כחות נפשו, אַזוי אַז יעדער כח ווערט נמשך וכלול אין די אַנדערע כחות — פון מוחין אין מדות ביז אין מחשבה דיבור ומעשה, בלימוד התורה וקיום המצוות, תורה עבודה (תפלה) וגמ\"ח.\nאון דורך די אחדות וציבור פון עשר כחות נפשו — ברענגט דאָס47 (אָדער דאָס איז מוסיף אין) אחדות כללות בני ישראל. און דורך דעם — אחדות בגלוי צווישן דעם אויבערשטן מיט אידן.\nח. בכדי נאָכמער פאַרשטאַרקן אחדות ישראל (שלילת „פרידתכם\") און די פעולות אין תומ\"צ בכלל (בפרט בציבור) — הן בכללות עם ישראל, והן בכחות הנפש (עולם קטן זה האדם) — האָט מען מציע געווען צוויי ענינים [ווי גערעדט בארוכה במשך חודש תשרי, ובפרט בשמח\"ת], וואָס זיינען כדאי איצטער נאָכאַמאָל דערמאָנען שטייענ־דיק איצטער בששה בחשון, ווען אַלע אידן האַלטן ביי אַריבערגיין פון דעם מצב הרגל צו די עבודה פון „ויעקב הלך לדרכו\", כאו\"א במקומו ובעבודתו הפרטית, און דאָרט ממשיך זיין די",[["43","43","ראה תו\"א תצוה פה, א ואילך. ד\"ה זכור במאמרי אדה\"ז תקס\"ה (כרך א) וביאורו. סידור עם דא\"ח שער הפורים. סהמ\"צ להצ\"צ מצות זכירת עמלק. מאמרים שבהערה 45. לקו\"ש חכ\"א ע' 195 ואילך. וראה גם ס' השיחות תש\"ד ע' 75. סה\"מ תש\"ט ע' 34 (השני) ואילך."],["44","44","שלכן צריך הבאַוואָרעניש „גדול לימוד שמביא לידי מעשה\" (ראה קידושין מ, ב. ב\"ק יז, א), כי לימוד סתם אולי לא יבוא לידי מעשה, ודוקא „גדול לימוד\", גדלות בלימוד (ראה לקו\"ש ח\"ז ע' 327. חי\"ח ע' 154), מביא לידי מעשה."],["45","45","ראה תנחומא תצא ט. פרש\"י תצא כה, יח. סה\"מ עטר\"ת ע' רצד. תרפ\"א ע' קעב. תרפ\"ה ע' רח. תש\"ט ע' 65 (השני). ובכ\"מ."],["46","46","כידוע הסיפור עם הרה\"ק ר' יוסף יצחק בנו של אדמו\"ר הצ\"צ (זקנו של כ\"ק מו\"ח אדמו\"ר) שפעם אמר שענין תפלה בצבור הוא „לצבור\" את עשר כחות הנפש (לקו\"ש ח\"ב ע' 477 ואילך. וב„התמים\" חוברת ב ס\"ע מה [עה, א] ואילך: תפלה בצבור הוא לצבור כל הבירורים ולהעלותם בתפלה). וראה פירוש מהרי\"ץ לב\"ר פפ\"ד, א: התפלה עיקרה ההכנעה אסיפת האברים והכחות אל הלב."],["47","47","ברוב הפעמים. אף שלפעמים האחדות דכללות בני ישראל מסייע ומביא לאחדות עשר כחות הנפש."]]],[1300251316,"אחדות פון חודש תשרי בכלל און שמע\"צ במיוחד:\nא) הקמת בתי חב\"ד48, בתי תורה, בתי תפלה ובתי גמ\"ח וצדקה — בכל מקום ומקום וואו עס געפינען זיך אידן, ב) „עשה לך רב\"49:\nדי אַלע פעולות פון תומ\"צ בציבור (וואָס זיינען כלול אין די דריי עמודים פון תורה, עבודה וגמ\"ח) און פעולת האחדות שעי\"ז וואָס מ'איז ממשיך במשך כל השנה מקדושת „ביהמ\"ק\" בעת „עלי' לרגל\" — זיינען שלא בערך שטאַרקער בשעת מ'איז מקיים אין אַ בית קבוע („מקדש מעט\") וואָס איז ספּעציעל געווידמעט צו תפלה50 (אַ בית הכנסת51, „מקום52 שמגדלין בו תפלה\"), אָדער תורה (אַ בית המדרש53, „מקום52 שמגדלין בו תורה\"), אָדער צדקה, אַזוי אַז יעדער איד וואָס געפינט זיך אין דער שכונה קען דאָרט אַריינגיין לערנען תורה, מתפלל זיין, אָדער געבן צדקה, אָדער באַקומען צדקה [צדקה גשמית (דאָרט נעכטיקן וכיו\"ב) אָדער צדקה רוחנית (אַן עצה טובה וכיו\"ב)]; ועאכו\"כ אַ „בית משולש\" וואָס איז כולל אַלע דריי זאַכן צוזאַמען, וואָס דעמולט איז יעדערער פון די דריי קוים מוסיף אין די אַנדערע54.\nווי מ'זעט עס בפשטות55: אַ בית בכלל (מקיף הרחוק) איז מאחד די וואָס גע־פינען זיך בתוכו בלי שום חילוק ביניהם56, און אַן אחדות באופן של קביעות והתיישבות — כידוע אַז אַ בית, איז אַ דירת קבע און בהתיישבות. דערפון איז מובן, אַז בשעת אידן האָבן אַ בית קבוע בשכונתם ובעירם וואו מ'קען זיך צוזאַמענקלייבן צו לערנען תורה, מתפלל זיין, געבן צדקה וגמ\"ח — איז דאָס זיי מאחד מיט אַן אחדות קבועה אין אַ בית קבוע, וואָס איז זיי מאחד שלא בערך שטאַרקער ווי בשעת מ'וואָלט עס געטאָן במקום ובאופן עראי. נוסף להפשוט, אַז בשעת די אידן ווייסן אַז זיי האָבן אַ בית קבוע וואו מ'קען אַלעמאָל אַריינגיין לערנען תורה, מתפלל זיין אָדער געבן צדקה (אָדער",[["48","48","ראה שיחת יום שמח\"ת — סה\"ש תשמ\"ז ח\"א ע' 35 ואילך. וש\"נ."],["49","49","ראה לקו\"ש חכ\"ט ע' 247 ואילך."],["50","50","שאין תפלתו של אדם נשמעת אלא בבית הכנסת (ברכות ו, א. רמב\"ם הל' תפלה רפ\"ח), והקב\"ה מצוי בבית הכנסת (ברכות שם. ירושלמי שם פ\"ה ה\"א (וראה אוה\"ת שבת שובה ע' א'תעה)). ומטעם זה „לעולם ישתדל אדם להתפלל בבהכ\"נ עם הצבור, ואע\"פ שיכול להתפלל בביתו בעשרה מ\"מ ברב עם הדרת מלך וגם אין תפלתו של אדם נשמעת אלא בבהכ\"נ\" (שו\"ע אדה\"ז או\"ח ס\"צ ס\"י. עיי\"ש). וגם תפלת יחיד עדיף בביהכנ\"ס — „מפני שהוא מקום קבוע ומיוחד לתפלת צבור ותפלתו של אדם נשמעת שם כו', וגם מפני שהקב\"ה מצוי בבהכ\"נ כו'\" (שו\"ע אדה\"ז שם. וראה ר\"י בשם הגאונים — ב\"י לטור או\"ח שם ד\"ה לא יתפלל. שו\"ע שם ס\"ט)."],["51","51","פרטי דיני ביהכנ\"ס — ראה רמב\"ם הל' תפלה פ\"ז ואילך. טושו\"ע ושו\"ע אדה\"ז או\"ח סר\"צ. טושו\"ע שם הל' בית הכנסת (סי' קנ ואילך). וראה אנציקלופדי' תלמודית בערכו. וש\"נ."],["52","52","מגילה כז, רע\"א."],["53","53","פרטי דיני ביהמ\"ד (ויחס שלו לביהכנ\"ס) — ראה רמב\"ם שם פ\"ח ה\"ג. פי\"א. ועוד. טושו\"ע או\"ח שם. וראה אנציקלופדי' תלמודית בערכו. וש\"נ."],["54","54","ולהעיר מרמב\"ם שם ה\"ג: וחכמים גדולים אע\"פ שהיו להם בעירם בתי כנסיות הרבה לא היו מתפללין אלא במקום שהיו עוסקין שם בתורה."],["55","55","נוסף על זה שעצם הקמת בית חב\"ד תלוי (לא ביחיד, כ\"א) בהשתתפות ואחדות של כמה וכמה."],["56","56","וזהו גם ענין שמע\"צ (ה„יום אחד\" ששולל „פרידתכם\"), שנכנסים אז מסוכה, דירת עראי, ל„בית\", דירת קבע — שזהו\"ע המשכת מקיפים בפנימיות ובאופן של קביעות (ראה בארוכה לקו\"ש ח\"ט ע' 229)."]]],[1300251317,"כולם יחד) — פועל'ט דאָס אַליין אַן אחדות קבועה צווישן די אידן.\nוואָס דאָס איז דער תוכן כללי פון אַ „בית חב\"ד\": די ג' מוחין חב\"ד (חכמה בינה דעת) זיינען די שלשה קוים, קו הימין, קו השמאל וקו האמצעי — כנגד תורה (קו האמצעי), תפלה (קו השמאל) וגמ\"ח (קו הימין). און אַ „בית חב\"ד\" מיינט אַז די שלשה קוים זיינען אין אַ בית קבוע באופן של התיישבות57. ובפשטות: אַ בית קבוע, אַ „בית משולש\" (בית תורה, בית תפלה ובית צדקה וגמ\"ח) וואָס מ'שטעלט אויף בכל מקום ומקום וואו עס געפינען זיך אידן — בכדי באַלייכטן („נרות להאיר\") און משפיע זיין אויף דעם גאַנצן אַרום אין תורה ומצוות און אידישקייט בכלל58.\nובאופן אַז די עבודה אין די שלשה קוים איז דורכגענומען מיט דעם אור פון פנימיות התורה (נשמתא דאורייתא<sup data-n=\"59\">59</sup>, הפצת המעינות חוצה, כפי שנתגלתה בתורת חסידות חב\"ד, באופן פון „יתפרנסון\"60 מיני' — וואָס דאָס גיט אַריין אַ פנימיות אין די עבודה ואחדות בג' קוים אלו61.\nט. בכדי מצליח זיין כדבעי62 אין אחדות כללות עם ישראל ע\"י הקמת בתי חב\"ד, דאַרף יעדער איד אַליין ווערן אַ (דוגמא חי' לזה — אַ) „בית חב\"ד\" (בעיר קטנה63 זה הגוף<sup data-n=\"64\">64</sup>. ד.ה. אַז חב\"ד שבנפשו (וכל עשר כחות שלו) ווערט נתאחד אין אַן אופן פון אַ „בית\"65, דירת קבע:\nכשם ווי אַ בית (קבוע) כפשוטו טוט אויף אַן אחדות קבועה, אַזוי דאַרף אויך זיין אין דער „עיר קטנה\" פון דעם מענטשן — אַז די אחדות פון אַלע זיינע כחות הנפש (כנ\"ל ס\"ז) דאַרף זיין (ניט באופן עראי, נאָר) באופן קבוע, אַזוי אַז ער בויט אויף אַ „בית\"66 פון אַלע זיינע עשר כחות הנפש ביחד — אָנהויבנדיק פון חב\"ד שבנפשו67, און פון חב\"ד",[["57","57","ראה משלי כד, ג־ד: „בחכמה יבנה בית ובתבונה יתכונן ובדעת חדרים ימלאו\". וראה שמו\"ר פמ\"ח, ד, שבג' דברים אלו (חכמה בינה ודעת) נברא העולם, שנאמר (משלי ג, יט־כ) ה' בחכמה יסד ארץ כונן שמים בתבונה בדעתו תהומות נבקעו, ובג' דברים הללו נעשה המשכן כו' ובג' דברים הללו נבנה בית המקדש, וכן כשיעמוד הקב\"ה לבנותו לע\"ל כו'. וראה אוה\"ת נ\"ך ע' תרכא ואילך. (כרך ג') ע' א'שסט־ע. נמצא, שהמשכן והמקדש (וכל העולם כולו) הם „בתי חב\"ד\". ועפ\"ז יש לומר שכן הוא בנוגע ל„מקדש מעט\", בתי כנסיות ובתי מדרשות (מגילה כט, א)."],["58","58","כמשל הידוע שנתבאר בשיחות כ\"ק מו\"ח אדמו\"ר — „אַ חסיד איז אַ לאַמטערנשציק\" (סה\"ש תש\"א ע' 136. וראה בארוכה שיחת י\"ב תמוז תשכ\"ב. סה\"ש תשמ\"ז שם — ע' 34־5)."],["59","59","ראה זח\"ג קנב, א."],["60","60","לשון התקוז תיקון ו בסופו. וראה מקדש מלך בהקדמה לספרו. כסא מלך לתקו\"ז שם. ועוד."],["61","61","ראה לקו\"ש חכ\"ח ע' 253, שפנימיות התורה (נשמתא דאורייתא) מביא לאחדות ישראל ע\"י גילוי הנשמה דישראל. וראה גם לקו\"ש ח\"כ ע' 180."],["62","62","כתובות סז, א."],["63","63","קהלת ד, יד."],["64","64","נדרים לב, ב. תניא פ\"ט (יד, א). ועוד."],["65","65","ראה לקו\"ת ברכה צט, א שבחי' בית (ולבוש ומזון) יש בבחי' עולם שנה נפש. ולהעיר מפי' הראב\"ד לס' יצירה פ\"ד מ\"ב: כל הבריות הם כעין בתים כו'. ע\"ש. וראה סה\"מ תרפ\"ח ע' נג: בית הוא הגוף."],["66","66","כמש\"נ (תרומה כה, ח) „ועשו לי מקדש ושכנתי בתוכם\" [ולהעיר שבתי כנסיות ובתי מדרשות נק' „מקדש מעט\", כנ\"ל הערה 57] — וארז\"ל בתוכו לא נאמר אלא בתוכם, בתוך כאו\"א מישראל (ראה ר\"ח שער האהבה פ\"ו. של\"ה תרומה שכה, ב ואילך. אלשיך תרומה עה\"פ)."],["67","67","ראה שמו\"ר שבהערה 57."]]],[1300251318,"(אמות ומקור המדות68, וכל העשר כחות) ווערט עס נמשך אין חג\"ת (מדות) און נה\"י, מחשבה דיבור ומעשה, אַזוי אַז ער ווערט אַליין אַ „נר להאיר\", ובדרך ממילא קען ער משפיע זיין און באַלייכטן און אָנצינדן אַנדערע „נרות\".\nיוד. און דער „בית חב\"ד\" בכחות הנפש דאַרף זיך אויסדריקן אין זיין עבודה בפועל, בתורה, עבודה וגמילות חסדים. אין פשוט'ע אותיות:\nתורה [קו האמצעי]: אפילו בשעת אַ איד במשך השנה איז זיך עוסק רוב היום (בהיתר התורה — זייענדיק פון „זבולון\" און ניט „ישכר\") אין עובדין דחול ועניני העולם — דאַרף ער קובע זיין עתים לתורה, „כדת הניתנה לכל אחד ואחד בהלכות תלמוד תורה\"69, אַזוי אַז ער ווערט דעמולט „משכן ומכון לשבתו הוא יחודו ית'\"69, ע\"ד ובדוגמת השראת השכינה במשכן ומקדש („בית חב\"ד\" הכללי ובשלימותו<sup data-n=\"70\">70</sup>.\nד.ה. אַז אין דעם זמן ווען ער לערנט תורה (אע\"פ וואָס ברוב היום פאַרנעמט ער זיך מיט אַנדערע זאַכן) ווערט ער אַ „בית חב\"ד\": תורה (חב\"ד — „חכמתכם ובינתכם\"<sup data-n=\"71\">71</sup> שטייט ביי אים ווי אַ „בית\" קבוע ובהתיישבות, אַזוי אַז בשעת הלימוד האָט ער ניט אַ שייכות מיט קיין אַנדער זאַך בעולם חוץ פון זיין לימוד התורה, ע\"ד „תורתו72 אומנתו\"73 (בזמן זה).\nובלשון חז\"ל74 „עשה תורתך קבע ומלאכתך עראי\", ד.ה. אַז אפילו ווען במשך כמה שעות ביום איז ער עסוק במלאכתו, און נאָר אַ טייל פון טאָג לערנט ער תורה, איז אָבער „תורתך קבע ומלאכתך עראי\", וויסנדיק אַז עיקר ענינו איז — תורה, „תורתו אומנתו\", כולל — אַז די תורה איז אויך זיין אומנות וואָס ברענגט אים פרנסה גשמית, וואָרום „ברכת ה' היא תעשיר\"75, און „מלאכתך\" איז נאָר אַ „כלי ולבוש\" בלבד76, במילא פאַרשטייט זיך אַז בשעת ער לערנט תורה איז ער ניט מפסיק צוליב ותועלת דעניני מסחר וכיו\"ב: עס מעג זיך „איבערקערן\" די גאַנצע וועלט, און עס מעג קלינגען דער טעלעפאָן וכיו\"ב — איז ער ניט מפסיק מלימוד התורה, און בלאה\"כ — ברכתו של הקב\"ה בעניני הפרנסה ווערט נמשך (ניט דורך זיין התעסקות במסחר, נאָר) דורך לימוד התורה דוקא!\nועד\"ז אין עבודת התפלה [קו השמאל] — אַז בזמן התפלה איז דע לפני מי אתה עומד77, לפני מלך מלכי המלכים הקב\"ה, ער שטייט אין אַ מעמד ומצב וואו זיינע גאַנצע מציאות איז דורכגע־נומען מיט ענין התפלה (באופן של",[["68","68","תניא רפ\"ג."],["69","69","תניא פל\"ד."],["70","70","ראה לעיל הערה 57."],["71","71","ואתחנן ד, ו."],["72","72","ראה שבת יא, א. ועוד."],["73","73","והדגשה יתירה בשנה זו — (א) שנת השמיטה, „שנת שבתון יהי' לארץ שבת לה'\" (ר\"פ בהר), „שגם עובדי האדמה כאשר ישבתו בשנה ההיא יתעוררו לדרוש את ה'\" (ספורנו עה\"פ), היינו, שיכולים וצריכים להקדיש את השנה כולה ללימוד התורה, (ב) הכנה למצות הקהל (בסיום שנת השמיטה) „מקץ שבע שנים במועד שנת השמיטה בחג הסוכות . . הקהל את העם האנשים והנשים והטף . . למען ישמעו ולמען ילמדו גו'\" (וילך לא, י ואילך. וראה בארוכה — מכתב שבהערה 18 ובהנסמן שם)."],["74","74","רמב\"ם הל' ת\"ת פ\"ג ה\"ז. טושו\"ע או\"ח סקנ\"ז. שו\"ע אדה\"ז שם ס\"א. וראה לקו\"ת אמור לה, ג."],["75","75","משלי י, כב."],["76","76","ראה לקו\"ת תצא לו, ריש ע\"ג. מאמרי אדה\"ז תקס\"ה (כרך ב) ע' תרמה. הקדמת אדהאמ\"צ לספרו דרך חיים. סהמ\"צ להצ\"צ מצות תגלחת המצורע פ\"ב ואילך. ובכ\"מ."],["77","77","ראה ברכות כח, ב."]]],[1300251319,"„בית\" קבוע), מעין ודוגמת הקרבת הקרבנות בבית המקדש, „תפלות כנגד קרבנות תקנום\".\nאון אויך אין גמ\"ח וצדקה [קו הימין]: „גם שאר היום כולו שעוסק במשא ומתן — יהי' מכון לשבתו ית' [„בית\"] בנתינת הצדקה שיתן מיגיעו כו'\"69.\nיא. און פון דעם „בית חב\"ד\" בכחות נפשו (און ווי דאָס קומט אַרויס בעבודתו בפועל אין תורה עבודה וגמ\"ח) — ווערט עס נתפשט (במובן יותר רחב) אין ביתו כפשוטו78, אַז זיין הויז ווערט אַ „בית חב\"ד\". ובפשטות: אַ בית וואָס איז מיוסד און דורכגענומען מיט תומ\"צ און אידישקייט (דורכגענומען אויך מיט דעם אור פון פנימיות התורה), וואו מ'זעט בגלוי דעם „ועשו לי מקדש ושכנתי בתוכם — בתוך כאו\"א\", אַזוי אַז „ביתך\" ווערט אַ „בית ועד לחכמים\"79, ובית תפלה ובית צדקה וגמ\"ח — אַז פון דעם בית קומט אַרויס אַ התעוררות צו אַלע מענטשן און בתים אַרום אין די שלשה קוים פון תורה תפלה וגמ\"ח.\nאון דורך דעם (וואָס מ'איז אַליין אַ „בית חב\"ד\", און די אייגענע שטוב איז אַ „בית חב\"ד\") — ווערט אַ סך לייכטער צו אויפשטעלן אין דער שכונה און שטאָט אַ „בית חב\"ד\" הכללי. ועד\"ז לאידך גיסא: דער „בית חב\"ד\" כללי גיט כח צו די עבודה פון מאַכן אַ „בית חב\"ד\" פון דער אייגענער שטוב און די אייגענע עשר כחות.\nביז אַז דאָס גיט נאָכמער כח אַז דער גאַנצער אַרום (אויך מחוץ העולם קטן זה האדם, ומחוץ לבית הפרטי ומחוץ לבית חב\"ד הכללי) ווערט אַ „בית חב\"ד\" — אַ דירה (דירת קבע<sup data-n=\"80\">80</sup> לו ית' בתחתונים81, אַ דירה לעצמותו ית'82, דורך די עבודה פון כאו\"א בחלקו בעולם, „ויעקב הלך לדרכו\" (וואָס הויבט זיך אָן בעיקר נאָך ששה בחשון).\nיב. דערביי קען נאָך אָבער בלייבן אַ שוועריקייט:\nעס קומט ניט אַלעמאָל אָן אַזוי גרינג צו פועל'ן אחדות (שלילת „פרידתכם\") בעשר כחות הנפש, ועד\"ז בביתו ובסביבתו (ע\"י הקמת „בית חב\"ד\"), וואָרום ער האָט דאָך אַ נפש הבהמית ויצה\"ר (בחי' עמלק שבו) וואָס שטערט דערצו. ובפרט ווען מ'האַלט באַ יורד זיין פון דעם מצב נעלה במשך חודש תשרי אין די עובדין דחול פון „ויעקב הלך לדרכו\", ווען ס'איז מעגלעך אַז די ירידה זאָל אויף אים פועל'ן אַ פירוד בכחות נפשו, בין מוחין ומדות כו', ביז אַז אפילו דער אויבערשטער זאָגט „קשה עלי פרידתכם\".\nאון אמת טאַקע — דורך די הקדמה פון קבלת עול ויראת שמים קען ער באַ־וואָרענען דעם „פרידתכם\" (כנ\"ל ס\"ז), אָבער קב\"ע ויר\"ש גופא איז ניט אַ לייכטע עבודה!\nאויף דעם האָט מען די עצה פון אַ דבר משנה83 — „עשה לך רב\", נעם צו",[["78","78","וגם זה נוגע לשלימות האדם — כמרז\"ל (יבמות סג, רע\"א) „כל אדם שאין לו קרקע אינו אדם\" (וראה סה\"מ תרס\"ה ע' ג. תש\"ג ע' 9). וראה לקו\"ת ברכה צט, רע\"א. לקו\"ש ח\"ט ע' 139 הערה 31."],["79","79","אבות פ\"א מ\"ד. וראה פיה\"מ להרמב\"ם שם (בהוצאת קאפח): כמו בתי כנסיות ובתי מדרשות."],["80","80","ראה מאמרי אדה\"ז: תקס\"ה (כרך א) ע' תלד: פרשיות (כרך ב) ע' תקלו. תקמב."],["81","81","ולהעיר שהכוונה דדירה בתחתונים (שמושרשת בעצמותו ית') היא הסיבה (וע\"ד) מה שכל אדם יש לו רצון מוחלט בעצמותו לבנות בית (ראה לעיל הערה 78)."],["82","82","המשך תרס\"ו ע' ג. ובכ\"מ."],["83","83","אבות פ\"א מ\"ו. שם מט\"ז."]]],[1300251320,"זיך אַ צווייטן אידן, אַלס אַ רב: נוסף אויף דעם עצם ענין אַז בשעת צוויי אידן טרעפן זיך איז דאָס צוויי נפש האלקית אויף איין נפש הבהמית84 (כפתגם אדמו\"ר האמצעי<sup data-n=\"85\">85</sup>, במילא העלפט דאָס יענעם איינקערן זיך מיט זיין נה\"ב86 — קומט אין דעם צו, אַז דער צווייטער איז אַ „רב\", אַזאַ וואָס איז גדול ממנו (בחכמת התורה ונסיון בפועל וכיו\"ב)87, און קען אים אַרויסהעלפן מיט אים געבן אַן עצה טובה ועידוד כו' בעבודתו ויראת שמים שלו, והמשכת מוחין במדות ובמחשבה דיבור ומעשה וכו'.\nובדיוק לשון המשנה — „עשה לך רב\":\n„עשה\": דער עצם ענין פון מקבל זיין אַ רב אויף זיך דאַרף זיין באופן פון „עשה\", „לשון עשי' יאמר על דבר שצריך לטרוח ולעשות על ידו\"88, ביז עשי' מלשון כפי'89. ד.ה. אַז דאָס איז ניט באופן פון „בחר\" (וכיו\"ב), אַז דער נה\"ב האָט אין דעם אויך אַ דיעה און איז צופרידן מיט דעם רב, ווייל דאָס באַ־ווייזט וואָס פאַר אַ רב מ'האָט זיך אויס־געקליבן — אַזאַ מיט וועמען דער נה\"ב איז צופרידן, וואָרום יענער וועט אים ניט מגביל זיין פון טאָן כפי רצונו כפי שמתאים ונוח (לבהמיות ש)לה... נאָר דאָס דאַרף זיין באופן פון „עשה\", אַז ער איז דערמיט כופה דעם נה\"ב.\n„לך\": א) דאָס קומט טאַקע באופן של „עשה\" (כפי'), אָבער „לך\", לרצונך. ב) ער ווערט דיין רב. ניט „עשה רב\" פאַר אַ צווייטן, אָבער דו אַליין דרייסט זיך דערפון אַרויס, נאָר „עשה לך רב\", ביז אין אַן אופן פון „לך — לפנימיותך\"90.\n„רב\": „תקבלוהו עליך לרב\", לסמוך על דבריו91 און מקיים זיין וואָס ער הייסט דיר, אַזוי ווי יעדער הוראה ופס\"ד פון אַ רב.\nואין לומר אַז ער קען זיך ניט גע־פינען אַ „רב\" המתאים לו — ווייל היות אַז דאָס איז אַ ציווי אין אַ משנה92 בתורת ה', תורת אמת, איז דאָ דער כלל אַז „איני מבקש כו' אלא לפי כחן\"93, און זיכער איז דאָס אַ „רב\" המתאים לו, און ניט ערגעץ־וואו בעולם (וואָס דעמולט איז דאָס ווייטער אינו לפי כחו), נאָר „קרוב אליך הדבר מאד בפיך ובלבבך לעשותו\"94.",[["84","84","כי הנה\"ב של השני לא „חוטא ולא לו\" (ב\"מ ה, ריש ע\"ב. הובא ברמב\"ם בכ\"מ — ראה לדוגמא: הל' מעשר פי\"ב הי\"ז)."],["85","85","לקו\"ד ח\"ב שן, ב. אגרות קודש אדמו\"ר מהוריי\"צ ח\"ב ע' עג. „היום יום\" כ' טבת."],["86","86","וכמבואר בקונטרס החלצו פ\"י (סה\"מ תרנ\"ט ע' סא. ולהעיר, שזמן אמירתו הי' בשמח\"ת ובש\"פ נח — סה\"מ שם ע' רכא), ש„כשמדברים יחד ממציא כל א' עצות לזה איך לתקן ועושים הסכם בקבלה על להבא לתקן מעשיהם שיהי' כך וכך כו'. וההסכם אשר עושים שנים כו' יש לזה חיזוק הרבה יותר מההסכם שעושה בפ\"ע כו'\"."],["87","87","ואפילו אם „לא ימצא חכם גדול כמוהו, יעשה מי שלמטה הימנו, כי אין אדם רואה בעניני עצמו העצה הצריכה לו כמו שיראה זולתו\" (מאירי — הובא במדרש שמואל אבות שם מז), כי אדם קרוב אצל עצמו (יבמות כה, ב. וש\"נ). וראה לקו\"ש שבהערה 49."],["88","88","מאירי — הובא במדרש שמואל שם."],["89","89","מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשסא. סה\"מ תרל\"ז ח\"ב ע' רפט. תרע\"ח ע' קכא. תרצ\"ט ע' 191. ועוד."],["90","90","ראה סד\"ה לך: תרס\"ו: תרס\"ז (בהמשך תרס\"ו): עדר\"ת (בהמשך תער\"ב ח\"א): תש\"ה. ועוד."],["91","91","לב אבות — הובא במדרש שמואל שם."],["92","92","ובפרט ש„טעה בדבר משנה חוזר\" (כתובות פד, ב)."],["93","93","במדב\"ר פי\"ב, ג."],["94","94","נצבים ל, יד."]]],[1300251321,"און דורך קיום הדבר משנה, מיט די תנאים הנ\"ל — וועט עס זיכער אַרויס־העלפן יעדער אידן אין איינקערן זיך מיט זיין נה\"ב און עבודתו בכלל, ובמיוחד — די עבודה פון אחדות עשר כחות נפשו, ואחדות בביתו ובשכונתו ובכל העולם כולו — דורך אויפמאַכן אַ „בית חב\"ד\" אין די אַלע ענינים, כנ\"ל95.\nיג. און דורך דעם וואָס עס וועט זיין „תמים תהי' עם ה' אלקיך\"96, תמים בכל עשר כחות שלו ובכל רמ\"ח אברים וכו'97, דורכגענומען מיט „תורה תמימה\", נגלה דתורה ופנימיות התורה (חב\"ד), און מ'פועל'ט אויך אַז אין דעם אייגענעם בית ושכונה ועיר וכו' זאָל זיין באופן של תמימות, דורך הקמת „בתי חב\"ד\", וואָס וועט משפיע זיין אַז אויך אַנדערע אידן זאָלן שטיין באופן פון „תמים תהי'\" —\nוועט דאָס נאָכמער צואיילן די גאולה תמימה, גאולה שאין אחרי' גלות98, וביהמ\"ק תמים, בית שלישי, דער „בית חב\"ד\" העיקרי99, שיבנה במהרה בימינו ממש.",[["95","95","להעיר גם משיעור היומי ברמב\"ם (הל' נזקי ממון פי\"ב הי\"ד־טו) בדיני בור, שישנם ב' אופנים, „החופר בור עמוק עשרה טפחים\", או „עשה תל גבוה ברשות הרבים . . גבוה עשרה טפחים\", דיש לומר בביאור ענינם (למעליותא) ב„תקון הדעות\" (רמב\"ם סוף הל' תמורה) — שהם ע\"ד ובדוגמת ב' הענינים ד„עשה לך רב\" והקמת „בתי חב\"ד\": „בור עמוק\" — מורה על תנועת הביטול והקבלה, „עשה לך רב\", ו„תל גבוה ברשות הרבים\" — מורה על תנועת ההשפעה להאיר גם ברה\"ר, ע\"י הקמת „בתי חב\"ד\" באמצע רשות הרבים, ובשניהם צ\"ל „עשרה טפחים\" — לעשות בזה כדבעי, בכל עשר כחות נפשו (כנ\"ל ס\"ז)."],["96","96","שופטים יח, יג."],["97","97","לקו\"ת נצבים מה, ג."],["98","98","ראה מכילתא בשלח טו, א. תוד\"ה ה\"ג ונאמר — פסחים קטז, ב. ועוד."],["99","99","ראה לעיל הערה 57."]]],[1300251322,"<h3>משיחת אור לכ\"ף מרחשון ה'תשד\"ם</h3>\nא. כאן המקום להזכיר אַ זאַך וואָס מ'האָט געהערט פון רבותינו נשיאינו, און אויך מובא בספרים:\nובהקדים — כמה חוברות ועתונים וכיו\"ב זיינען באַגלייט מיט ציורים אָדער תמונות (מצד דעם וואָס מ'וויל צוציען נאָך מענטשן אָדער נאָך קינדער), און צווישן די ציורים זיינען אויך דאָ, מצד כו\"כ טעמים, ציורים פון בהמות וחיות ועופות וכו' —\nאיז אַ דבר נכון ביותר אַז מ'זאָל נוצן נאָר ציורים ותמונות פון בהמות וחיות טהורות1, עופות ודגים טהורים2. אַ איד, ובפרט אַ אידיש קינד דאַרף זיין איינגעוואוינט נאָר בדברים טהורים3.\nואע\"פ אַז ע\"פ מנהג המדינה זיינען פאַראַן געוויסע ענינים וועלכע מ'פאַרבינדט דוקא מיט.. אַ מויז (!), און אַן אַנדער ענין וואָס מ'פאַרבינדט מיט אַן אַנדער חי' שאינה טהורה וכו' (ואין כאן המקום להאריך בזה), און ס'איז געוואָרן אַ רגילות צו נוצן אַזוינע ציורים, און ליידער — אויך אַ רגילות אין חוברות ועתונים וואָס זיינען בשאר הפרטים — על טהרת הקודש, אָבער אויף דעם, מאיזה סיבה שונה ומשונה וואָס איז אינגאַנצן ניט פאַרשטאַנדיק, האָט מען ניט משים לב געוועזן (עכ\"פ —",[["1","1","ומה שמצינו בכו\"כ בתי כנסיות ציורי פני ארי' ופני נשר על הפרוכת דארון קודש ועל המעיל וכתר דס\"ת — הרי הכוונה בזה, כפשוט, להזכיר ע\"ד הכרח התפלה ועבודת האדם לה' באופן דגבור כארי כו' — כהתחלת וריש טושו\"ע ודאדה\"ז (מהדו\"ב) או\"ח (ממשנה ספ\"ה דאבות). ואולי י\"ל — ע\"ד המרכבה שבה פני ארי' ופני נשר*. ולהעיר מהקושיא והביאור בחסידות (תו\"א מג\"א צג, סע\"ג. ובכ\"מ) מדוע הארי' והנשר שבמרכבה — להבדיל כו' חיות טמאות הן למטה בעוה\"ז כו'. ובנוגע הציורים דחיות טמאות על כמה מהדגלים דהשבטים (במדב\"ר פ\"ב, ז) — מבואר שם, שכל ציור הי' קשור עם תכונות השבט, ומוכרח לשבט זה דוקא ציור דחי' מסויים (נחש וכיו\"ב)."],["2","2","ראה ס' קב הישר פ\"ב. ושם, שאף שיש לאדם רשות לראות בריות משונות הבאים ממדינות מרחקים וע\"ז תקנו חז\"ל וקבעו ברכה ברוך משנה הבריות, מ\"מ לא יראה בהם כי אם דרך עראי כו'. — ועפ\"ז מובן ההליכה לגן חיות וכיו\"ב, ואין לזה סתירה מהמדובר בפנים."],["3","3","בנוגע לכללות הפעולה והתועלת הבאה ע\"י ראי' בענינים וצורות קדושות וטהורות — ראה מדבר קדמות (להחיד\"א) ערך ציור. בהנסמן בריש ס' תולדות אדם (לר' ראובן מרגליות — לעמבערג, תער\"ב. דפוס צילום אה\"ק, תש\"מ). וראה קונטרס העבודה פ\"ב. *) וראה ב\"י לטור יו\"ד סקמ\"א ד\"ה כתב. ודחה שם דעת האוסרים לצייר צורת ארי' כו' בביהכנ\"ס. ומסיים שם שכל הפוסקים מתירים לעשות כן „אפילו לכתחילה\". וראה שו\"ת אבקת רוכל (להב\"י) סי' סו. וכיון שיש חילוק דיעות בזה — לכן כתיב בפנים רק „אולי י\"ל ע\"ד המרכבה כו'\" — כי לסברא הא' שבפנים ההערה (להזכיר ע\"ד הכרח התפלה כו') כל העושים ושיעשו כן מטעם זה, ה\"ז מותר לכולי עלמא, כי: הצורה מצ\"ע — אינה שלימה וכו' והכוונה ה\"ה למשנה אבות — רצוי' ונכונה שה\"ז הוראה בעבודת השם (תפלה ותורה) שצריך להשתדל בזה וכו'. ויתרה מזה מצינו — שהרמב\"ם צייר מנורה בת ז' קנים וכפתורי' וגביעי' (ולא שהורה לקטן איך לציירה — מדלא הזכיר זה). ואכ\"מ. ולהעיר שכו\"כ אישים הי' בחותם (וכיו\"ב) שלהם צורת ארי'."]]],[1300251323,"ביז איצטער), אַז מ'דאַרף זיך משתדל זיין אַז אַ איד, בפרט אַ קינד, זאָל זיך אים מזדמן זיין, ער זאָל קוקן נאָר אויף דברים טהורים —\nואע\"פ וואָס ס'איז אַ רגילות ומנהג העולם, דאַרף מען אָבער ניט האָבן קיין מס\"נ אויף מבטל זיין די רגילות, און מ'קען עס דורכפירן בנקל ובנקל דנקל,\n[ולהזהר ניט מאַכן דערפון קיין ענין של נצחון: בשעת מ'קומט צוגיין זאָגן אַז מען האָט עם „געחאַפּט\" און „מ'הייסט\" ער זאָל משנה זיין רגילותו, איז נוסף על השאלה וואָס איז מען עם פאַר אַ זאָגער — איז מען יענעם „מכריח\" כביכול, יענער „דאַרף\" באַווייזן אַז ער איז אַן אדם גדול און טאָן פאַרקערט... מ'דאַרף רעדן אין אַן אופן וה\"ז אמתתו של הענין, אַז ניט מ'זאָגט אים אַ דבר חדש, נאָר אַז אַזוי שטייט אין ספרים, און ער קען אַליין אַ קוק טאָן אין די ספרים וואו ס'רעדט זיך וועגן דעם, וועט דאָס ווערן „תורתו\", וועט עס ווערן זיין אייגענע הוראה.\nועד\"ז אין כמה אַנדערע עניני הוכחה].\nב. אַזוי אויך, און מיט נאָכמער הדגשה, דאַרף זיין בנוגע צו חינוך פון אידישע קינדער:\nלויט מנהג ישראל, בשעת אַ אידיש קינד ווערט געבאָרן הענגט מען אויף אויפן וואַנט בחדרו, אָדער מ'רינגלט אים אַרום מיט ענינים פון קדושה, שיר המעלות וכו'. ועד\"ז דאַרף מען מאַכן זיכער אַז עס זאָלן ניט זיין קיינע ציורים פון דברים בלתי טהורים4.\nווען מ'דאַרף אים געבן אַ צאַצקע דבעל חי, מאיזה טעם שיהי', וויבאַלד אַז ער איז אַ קינד — דאַרף מען אויסקלייבן אַ צאַצקע בצורת אַ בהמה טהורה, אַן עוף טהור אָדער דג טהור וכיו\"ב.\nאַזוי אויך ווען דער קינד ווערט עלטער און מ'דאַרף אים מחנך זיין בצורת האותיות, איז היות אַז ער איז אַ קינד אין אַזוינע יאָרן וואָס בשעת מ'דאַרף אים דערציילן וואָס איז אַן אל\"ף, באַווייזט מען אים אַ ציור פון איינעם וואָס טראָגט צוויי דליים (עמער — איינער למעלה און איינער למטה)*4 — ווי ס'פלעגט אַמאָל זיין דער ציור אין ספרי ילדים — פון אַ טייך אין וועלכע עס שווימען פיש, אָדער עס שטייט דערביי (אין ציור) אַ קאַץ וכיו\"ב — זאָל מען „אַרויסוואַרפן\" די קאַץ פון דעם ציור, און מ'זאָל דאָרטן אַרייננעמען אַ בהמה טהורה, אַן עוף אָדער אַ דג טהור5.\nוכיו\"ב אין שאר עניני ציורים, ובפרט ציורים וועלכע זיינען פאַרבונדן מיט חינוך און גיל החינוך — ווייל „כי יזקין",[["4","4","ראה רוקח הל' שבועות סרצ\"ו: מכסין הנער שלא יראה כלב ביום שמחנכין אותו לאותיות הקודש. *4) ראה לקו\"ד ח\"ד תרמא, א."],["5","5","ההוראה בפנים היא לא בנוגע לציורים דבהמות וחיות טמאות המדוברות בתנ\"ך ומדרז\"ל שמלמדי תינוקות וכיו\"ב מציירים עבור התינוקות בכדי להקל לימודם כו', או כשמעתיקים סיפור מתנ\"ך ומדרז\"ל, שאז ה\"ז לימוד ופי' התורה, כפשוט. [יתרה מזו — להזכיר התחלת טושו\"ע (ומשנה דאבות) מציירים ארי' וכיו\"ב, ואין מסתפקים בציור צבי (כנ\"ל הערה 1)]. וכפי שכבר כתב מלמד תינוקות הכי מפורסם — רש\"י (שמיני יא, ב): „זאת החי' אשר תאכלו גו' לא תאכלו\" — „מראה\" החי' שלא תאכלו. ובהדגשה (דלכאורה מיותר להראות החיות שלא תאכלו כיון שהראה כל הנאכלות)."]]],[1300251324,"לא יסור ממנה\" איז פאַרבונדן מיט „חנוך לנער על פי דרכו\"6; עס איז שטאַרק נוגע וואָס עס ווערט איינגעקריצט אין דער מחשבה פון אַ קינד זייענדיק גאָר יונג: בשעת ער זעט פאַר די אויגן ענינים טהורים, איז „גם כי יזקין לא יסור ממנה\".\nג. אַ מקור אין נגלה אויף די זהירות אַז אַ איד זאָל ניט קוקען7 (איינקוקען זיך) בבהמות לא טהורות, נאָר דוקא טהורות [נוסף לזה וואָס אַזוי שטייט אין ספרים, כנ\"ל]:\nס'איז אַ דין אין שו\"ע8 אַז „יש לנשים ליזהר כשיוצאות מן הטבילה . . שלא יפגע בה תחילה דבר טמא . . ואם פגעו בה דברים אלו (כגון כלב או חמור כו'<sup data-n=\"9\">9</sup> אם היא יראת שמים תחזור ותטבול\"10. ועד כדי כך אַז עס זיינען געוועזן נשים צדקניות וואָס אפילו אַרויסגייענדיק מבנין מקום הטבילה גייענדיק אין גאַס און מ'האָט געטראָפן אַ דבר לא טהור — האָט מען זיך נאָכאַמאָל טובל געוועזן.\nד. וי\"ל אַז די הדגשה אויף זען נאָר דברים טהורים וקדושים איז נאָכמער בזמן דעקבתא דמשיחא און מ'גרייט זיך צו לע\"ל — עס איז דאָך „טועמי'11 חיים זכו\"12 פון אַלע ענינים דלע\"ל, כולל אויך פון דעם וואָס לע\"ל וועט זיין „ואת רוח הטומאה אעביר מן הארץ\"13, מיט אַלע ענינים וואָס זיינען פאַרבונדן מיט היפך הטהרה, במילא איז כדאי זיך משתדל זיין בעקבתא דמשיחא אַז ס'זאָל זיין אַ הנהגה מעין זה, אַז וואו מ'קען נאָר אויספירן זאָלן זיין ציורים (אָדער ענינים) וואָס זיינען טהורים, און נאָכמער — על טהרת הקודש.\nויה\"ר אַז בקרוב זאָל מען זוכה זיין צום קיום היעוד אַז ס'זאָל נתרבה ווערן „מי הדעת הטהור\", ווי דער רמב\"ם פסק'נט בסיום הל' מקוואות, אַז דאָס איז דער ענין פון מים וטבילה במים — זאָל גלייך זיין יתרבה „מי הדעת הטהור\", תתרבה הטהרה, במילא וועט אויך זיין „תרבה הדעה והחכמה כו'\"14, תרבה החכמה, הבינה והדעת, ביז „מלאה15 הארץ דיעה את ה' כמים לים מכסים\"16, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, במהרה בימינו ממש.",[["6","6","משלי כב, ו."],["7","7","משא\"כ — כדי לברך משנה הבריות — וכיו\"ב (טושו\"ע או\"ח סרכ\"ה ס\"ח ואילך. וש\"נ) — ראה לעיל הערה 2. ולכאורה עד\"ז — להתבוננות במה רבו מעשיך גו' — ועיין תהלים קד ובמדרשים ומפרשים שם. בספרי גדולי ישראל הדנים בזה (חוה\"ל שער היחוד פ\"ו ואילך. שער הבחינה פ\"א ואילך. ועוד). וראה ס' החקירה להצ\"צ כג, ב ואילך (ובקיצור — שם ה, א). יהל אור עה\"פ מה רבו וגו'."],["8","8","רמ\"א יו\"ד סו\"ס קצח. משערי דורא סוף הל' נדה (סכ\"ג). רוקח וכל בו הל' נדה. וראה ש\"ך יו\"ד שם. ובמדרש אלה אזכרה (אוצר מדרשים — אייזנשטיין ח\"ב ע' 441) (ובשערי דורא שם) הובא מעשה רב בזה באמו של ר' ישמעאל בן אלישע כהן גדול שחזרה וטבלה „פ' פעמים\"."],["9","9","ש\"ך שם."],["10","10","ובמדרש ושערי דורא שם שראי' בדבר קדוש וטהור (כשאשה יוצאת מן הטבילה) פעל שכן הי' צורת הולד (ר' ישמעאל בן אלישע כהן גדול). וראה ברכות כ, א (הובא בשערי דורא שם)."],["11","11","ראה מג\"א או\"ח סר\"נ סוסק\"א. שו\"ע אדה\"ז שם ס\"ח (מפע\"ח שער יח רפ\"ג. שעה\"כ ענין טבילת ערב שבת)."],["12","12","ראה לקו\"ש חט\"ז ע' 282. ועוד."],["13","13","זכרי' יג, ב."],["14","14","רמב\"ם הל' תשובה פ\"ט ה\"ב."],["15","15","ישעי' יא, ט."],["16","16","רמב\"ם שם. סוף הל' מלכים."]]],[1300251325,"משיחת ש\"פ וירא, כ\"ף מרחשון ה'תשמ\"ז\nא. היינט, כ\"ף חשון, איז דער יום הולדת פון דעם רבי'ן (מהורש\"ב) נ\"ע, ובלשון פון צמח צדק (דער נשיא בדורו) בעת קריאת שם בעל יום ההולדת1 „נולד כ' חשון תרכ\"א2, שיש בזה שני כפי\"ן, שהוא רומז לכתרא עילאה\"3.\nויש לומר דעם ביאור השייכות ביניהם (פון דעם בעל יום ההולדת מיט זמן הולדתו):\nכללות התורה איז פאַרבונדן מיטן קו האמצעי, המבריח מן הקצה אל הקצה, וואָס איז עולה עד (פנימיות) הכתר3* און נמשך אין ספירת המלכות, ביז למטה מטה4. ובאותיות פשוטות: תורה איז „חכמתו ורצונו של הקב\"ה\"5 (וואָס „רצון העליון ב\"ה מכונה ונקרא בפי חכמי האמת בשם כתר עליון\"<sup data-n=\"6\">6</sup>. און פון די הויכע דרגא איז „תורה ירדה ממקום כבודה שהיא רצונו וחכמתו יתברך ואו־ רייתא וקוב\"ה כולא חד7 כו', ומשם נסעה וירדה בסתר המדרגות ממדרגה למדרגה בהשתלשלות העולמות עד שנתלבשה בדברים גשמיים ועניני עולם הזה כו'\"5, און ווי די תורה איז למטה שטייט זי מיט דעם גאַנצן תוקף ווי זי איז למעלה (מבריח מן הקצה אל הקצה) און ווייזט אָן אידן ווי זיי זאָלן זיך פירן אין זייערע ענינים (אויך הגשמיים) בהתאם לרצון הקב\"ה. און דערפאַר איז תורה (אורייתא) דער „ממוצע המחבר\" וואָס איז מאחד ישראל וקוב\"ה8 (בדוגמא ווי כתר (רצון) איז דער ממוצע9 צווישען איין דרגא מיט די צווייטע דרגא)10.\nאון אין תורה עצמה איז די המשכה פון (פנימיות ה)כתר שבתורה11 — אין פנימיות התורה, „בעסק סתים ופנימיות התורה מאיר בזה העצמות בגילוי יותר כו'\"12. ועאכו\"כ ווי פנימיות התורה נתגלתה בתורת החסידות13, אָנהויבנ־",[["1","1","ראשי פרקים מתולדות כ\"ק אדמו\"ר מהורש\"ב נ\"ע בהקדמה לחנוך לנער ע' 8."],["2","2","שנת כתר\"א — „היום יום\" כ' חשון."],["3","3","כמבואר בכ\"מ שאות כ' ר\"ת כתר ועשרים בגימטריא כתר — ראה לקו\"ת שה\"ש לה, ג. ס' הערכים־חב\"ד מערכת אותיות אות כ\"ף ע' סט ואילך. וש\"נ. 3*) וראה אבות פ\"ד מי\"ג. רמב\"ם הל' ת\"ת רפ\"ג: „בשלשה כתרים נכתרו ישראל כתר תורה . . מונח ועומד ומוכן לכל ישראל . . כל מי שירצה יבא ויטול\". וראה לקו\"ש חכ\"ז הדרן על הרמב\"ם תשמ\"ה ע' 242 ואילך."],["4","4","המשך תער\"ב ח\"ב פשס\"ב. וראה שם ח\"א פקי\"ד."],["5","5","תניא פ\"ד."],["6","6","אגה\"ק סכ\"ט (קמט, סע\"ב) — שיעור תניא דכ\"ף מ\"ח (בשנה מעוברת)."],["7","7","ראה זהר ח\"א כד, א. ח\"ב ס, א. תקו\"ז ת\"ז בתחלתו. לקו\"ת נצבים מו, א. ועוד."],["8","8","ראה זח\"ג עג, א. וראה לקו\"ת נצבים שם. המשך תער\"ב ח\"ב שם. סה\"מ תרנ\"ז ע' כז ואילך. ה'ש\"ת ע' 61. 67 ואילך. ובכ\"מ."],["9","9","ע\"ח שער דרושי אבי\"ע פ\"א. וראה לקו\"ת בחוקותי מו, ג. במדבר יב, א ואילך. ראה כא, א. ובכ\"מ."],["10","10","ראה אוה\"ת לתהלים (יהל אור) ע' שצח. יתרו ע' תתסו ואילך. נ\"ך (כרך ג) ס\"ע א'שמט ואילך. ועוד."],["11","11","ראה מקומות שבהערה הקודמת."],["12","12","המשך הנ\"ל ח\"ב שם."],["13","13","ראה המשך הנ\"ל שם פשע\"ג ואילך, שענינה דחסידות בכלל היא המשכת אור חדש מבחי' פנימיות הכתר, ולמעלה יותר — המשכת בחי' פנימיות עתיק ממש, בחי' א\"ס שנמצא ברדל\"א. וראה בארוכה קונט' ענינה של תורת החסידות."]]],[1300251326,"דיק דורך דעם בעש\"ט — באופן פון „יפוצו מעינותיך חוצה\"14,\nאון נאָכמער — דורך תורת חסידות חב\"ד שנתייסדה ע\"י אדמו\"ר הזקן, ובפרט „נאָך פּעטערבורג\", וואָס דעמולט האָט זיך אָנגעהויבן „דער עיקר פון יפוצו14 מעינותיך חוצה\"15 — ווייל חסידות חב\"ד גיט אַרויס די מעינות (הבעש\"ט<sup data-n=\"16\">16</sup> פון פנימיות התורה בהבנה והשגה פון חכמה בינה דעת17, באופן פון „יתפרנסון18 מיני'\", ביז אַז דאָס זאָל קענען דורכנעמען די שכל און מציאות פון נה\"ב, און פון חלקו שבעולם, און זיי מהפך זיין לקדושה. וואָס דאָס ערמעג־ לעכט אַז די מעינות הבעש\"ט זאָלן אָנ־ קומען אין „חוצה\" כפשוטו.\nאון דעריבער איז דוקא דורך דעם (התלבשות פנימיות התורה בהשגה ע\"י אדה\"ז) ווערט „נמשך עצם פנימיות התורה\"19, וואָרום די „ירידה והשפלה\" פון מלביש זיין חסידות אין שכל איז נמשך מכח עליון יותר20, און נאָכמער: סוף מעשה במחשבה תחלה, די כוונה למעלה בעצמותו ית' איז אַז תורה און אלקות זאָל אַראָפּקומען דוקא למטה מטה, ביז אין „חוצה\" — הפיכת טבע הנה\"ב21 („חוצה\" שבאדם<sup data-n=\"22\">22</sup> וחלקו שב־ עולם („חוצה\" שבעולם) און מאַכן דאָרט אַ דירה לו ית' בתחתונים, אַזוי אַז דער תחתון וטבע העולם זאָל ווערן אַ כלי צו אלקות, וואָס די מעגלעכקייט דערצו איז דורך גילוי החסידות בהבנה והשגה23, דעריבער איז דאָס ממשיך „עצם פנימיות התורה\", און וואָס אַלץ וויי־ טער (מער „חוצה\") חסידות ווערט נמשך, אַלץ מער דריקט דאָס אויס עצם מהותה24.\nאין דעם גופא זיינען אָבער אויך גע־ ווען דרגות — וואָס מדור לדור האָט יעדער נשיא מפיץ געווען די מעינות הבעש\"ט צו נאָך אַ ווייטערדיקן „חוצה\".\nב. ויש לומר אַז אין דעם איז צוגע־ קומען אַ חידוש ושלב עיקרי דורך דעם בעל יום ההולדת, דער רבי נ\"ע — הן אין תורת החסידות שלו, והן אין זיינע פעולות פון הפצת המעינות חוצה:",[["14","14","ראה אגה\"ק הידועה דהבעש\"ט — נדפסה בכש\"ט (הוצאת קה\"ת) בתחלתה. ובכ\"מ."],["15","15","ס' השיחות תורת שלום ס\"ע 112 ואילך."],["16","16","ראה מכתב כ\"ק אדמו\"ר מהורש\"ב נ\"ע (נדפס באגרות־קודש שלו ח\"א ע' רנט. „היום יום\" בתחלתו): והיא היא תורת הבעש\"ט."],["17","17","ראה תורת שלום שם. מקומות שבהערה 19. ובכ\"מ."],["18","18","לשון התקו\"ז ת\"ו בסופו. וראה הקדמת המקדש מלך לספרו. כסא מלך לתקו\"ז שם. ועוד."],["19","19","ד\"ה פדה בשלום תרפ\"ה (סה\"מ תרפ\"ה ע' עט) בשם אביו כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע י\"ט כסלו עטר\"ת (ס' השיחות תורת שלום (הוצאת קה\"ת, תשמ\"ג) ע' 260)."],["20","20","תורת שלום ע' 115."],["21","21","להעיר מהפתגם שכל ענין החסידות הוא לשנות טבע מדותיו — לקו\"ד ח\"א נו, א. מכתב כ\"ק מו\"ח אדמו\"ר מיום כ' מרחשון תרצ\"ו („התמים\" חוברת ג' ע' סו [קמט, ב]. אגרות־קודש שלו ח\"ג ע' תנח). ועוד."],["22","22","ראה אוה\"ת לתהלים (יהל אור) ע' תנה."],["23","23","ויש להתאים זה עם הידוע שעבודת אדה\"ז היתה בעשיית בעלי תשובה (לקו\"ד ח\"ד תשנה, א ואילך. תורת שלום ע' 86) — כי זהו בירור ניצוצות הכי תחתונים שנפלו למטה בזדונות כו', וע\"י התשובה מעלים הניצוצות, וזדונות נעשות כזכיות. וגם בענין זה (עשיית בע\"ת) — נראה ההתעסקות המיוחדת של בעל יום ההולדת (שיחה דלקמן הערה 31 — ס' השיחות תש\"ב ע' 144. ועוד)."],["24","24","ראה סד\"ה פדה בשלום שם (ע' פח). קונט' ענינה של תורת החסידות סי\"ח. ס\"כ. לקו\"ש חט\"ז ע' 38 הערה 39. ולהעיר, שבחי' יחידה — תורת החסידות (יחידה שבתורה) — חודרת בעיקר כח העשי' כו' — ראה בארוכה ברכת ערב יוהכ\"פ (סה\"ש תשמ\"ז ח\"א ע' 2 ואילך) וש\"נ."]]],[1300251327,"בתורת החסידות: במאמרי בעל יום ההולדת זעט מען אַז די עניני חסידות זיינען בביאור יותר רחב ובהבנה והשגה שכלית יותר, ווי זיי זיינען (בגלוי) במאמרי רבותינו נשיאינו שקדמו25. וכידוע דער פתגם פון חסידים הרא־ שונים26 אַז דער רבי נ\"ע איז „דער רמב\"ם פון חסידות\", ווייל די ענינים במאמרי חסידות שלו זיינען „אַ הלכה קבועה ומסודרה מיט דעם גאַנצן הסבר פון דעם ענין, דבר דבר על אופנו . . אַ מעין פון ים החכמה, אַ מסכת שלימה\". והיות אַז דער רבי נ\"ע האָט אַראָפּ־ געבראַכט תורת החסידות נאָכמער אין הבנה והשגה, גיט דאָס די מעגלעכקייט אויף דערגרייכן נאָך ווייטער אין „חוצה\", ובמילא באַווייזט עס אַז דאָס נעמט זיך פון נאָך אַ העכערע דרגא אין „עצם פנימיות התורה\".\nועוד ועיקר: דער רבי נ\"ע האָט מייסד געווען ישיבת תומכי תמימים. וואָס דורך דעם האָט ער דורכגעפירט די כוונה פון „יפוצו מעינותיך חוצה\" ע\"י הבעש\"ט ואדה\"ז ורבותינו נשיאינו שלאחריהם — אַז דאָס זאָל אַרויס־ קומען אין לימוד התורה בפועל, און דורכנעמען עולם התורה (לומדי תורה ואנשי תורה), ובאופן של קביעות והת־ יישבות — וואָס דאָס האָט זיך דורכ־ געפירט בעיקר (אָנהויבנדיק) דורך התייסדות ישיבת תומכי תמימים, אַ ישיבה פאַר תלמידים, מיט דער כוונה צוצוציען תלמידים מכל קצוי תבל, וואו מ'לערנט תורה, נגלה דתורה און תורת החסידות, באופן של „ישיבה\", בקביעות ובהתיישבות27, און ווי אַ תורה אחת, תורה תמימה28 — דער לימוד הנגלה איז דורכגענומען מיט לימוד החסידות, און דער לימוד החסידות איז דורכ־ גענומען מיט לימוד הנגלה, ביז אַז די השגה בחסידות איז „כלימוד הסוגיות בגליא שבתורה\"29.\nדאָס הייסט: אע\"פ וואָס „דער עיקר פון יפוצו מעינותיך חוצה\" האָט זיך אָנגעהויבן באַ דעם אַלטן רבי'ן, איז אָבער דער ענין בפועל בעולם התורה האָט זיך אָנגעהויבן (בעיקר) דורך התייסדות ישיבת תומכי תמימים. ווי מ'זעט עס בפועל, אַז ניט קוקנדיק אויף די הפצה ע\"י רבותינו נשיאינו שלפני זה, איז אין דעם צוגעקומען שלא בערך מער דורך התייסדות הישיבה און די תלמידי הישיבה. און דאָס האָט געגעבן דער כח צו באַלייכטן דעם חושך כפול ומכופל פון „חוצה\" (שבעולם) פון עקבתא דמשיחא (אַ טיפערער חושך ווי ס'איז געווען בדורות שלפנ\"ז).\nאון ווי דער רבי נ\"ע האָט געזאָגט בכמה משיחותיו בקשר עם התייסדות הישיבה30. ובמיוחד אין די שיחה הידועה",[["25","25","ראה גם לקו\"ש חכ\"ז ע' 27."],["26","26","לקו\"ד ח\"ב רצו, א."],["27","27","ראה לקו\"ש חכ\"ט ע' 283־4."],["28","28","ראה שיחת כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע שמח\"ת תרנ\"ט (בשעת הקפות) — בקשר לקריאת שם הישיבה „תומכי תמימים\" — נעתקה במכתבי כ\"ק מו\"ח אדמו\"ר („התמים\" חוברת א ע' כד [יג, ב] ואילך. אגרות־קודש שלו ח\"י ע' ד. שם ע' שסח)."],["29","29","ל' כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע ב„מאמר הפתיחה\" שלו בעת התייסדות הישיבה ט\"ו אלול תרנ\"ז — נעתק במכתב כ\"ק מו\"ח אדמו\"ר („התמים\" שם ע' כג [יג, א] ואילך. אגרות־קודש שם ע' שסו ואילך). וראה גם קונטרס עץ החיים פכ\"ה."],["30","30","ראה שיחת ח\"י אלול תרנ\"ז (נדפסה בס' השיחות תש\"ב ע' 133. לקו\"ד ח\"ד תשפב, א): מיט דער התחלה אין דער ישיבה . . צינד איך אָן דעם נר תמיד פון די מאורות, וואָס דער בעש\"ט און די רביים האָבען אונז מנחיל געווען, אַז עס זאָל מקויים ווערן די הבטחה פון יפוצו מעינותיך חוצה און ביאת משיח צדקנו."]]],[1300251328,"שלו צו די תלמידי הישיבה31 בענין „כל32 היוצא למלחמת בית דוד\" — אַז די תלמידי הישיבה זיינען „חיילי בית דוד\" וועלכע וועלן „ראַטעווען דעם מצב פון כלל ישראל\" פון די „אשר חרפו עקבות משיחך\"33 (ראַטעווען ביז אין אַן אופן פון „אמן ואמן\" (כסיום המזמור תהלים<sup data-n=\"34\">34</sup>, וואָס ווייזט אויף גמר הנצחון<sup data-n=\"35\">35</sup>, און דורך יפוצו מעינותיך חוצה ברענגען „אתי מר\" דא מלכא משיחא (קיום ההבטחה פון משיח'ן צום בעש\"ט<sup data-n=\"36\">36</sup>.\nאון נאָכמער בגלוי און נאָך ווייטער אין „חוצה\" איז דאָס (הפצת המעינות) אַרויסגעקומען דורך בנו יחידו, ממלא מקומו — כ\"ק מו\"ח אדמו\"ר, וועלכער האָט אָנגעהויבן מגלה און מפיץ זיין פנימיות התורה בכל מקום ומקום ממש, ביז אין חוצה שאין חוצה ממנו, און אויך — דורך הייסן מתרגם זיין חסידות אין אַנדערע שפּראַכן37, „באר היטב — בשבעים לשון\"38, אַזוי אַז דאָס זאָל קענען דערגרייכן אידן וואָס פאַר־ שטייען נאָך ניט לע\"ע לשון הקודש אָדער אידיש, און אויך — אומות העולם39 (להבדיל).\nג. עפ\"ז איז (נאָכמער) פאַרשטאַנ־ דיק דער ביאור אין דברי הצ\"צ בנוגע להולדת אדמו\"ר נ\"ע — „נולד כ' חשון תרכ\"א, שיש בזה שני כפי\"ן, שהוא רומז לכתרא עילאה\" — ווייל די שליחות פון דעם רבי'ן נ\"ע במיוחד איז באַשטאַנען אין ממשיך ומגלה זיין בחי' כתר שב־ תורה (תורת החסידות) למטה מטה40, באופן גלוי לכל41.\nויש לומר אַז דאָס איז מרומז אין דעם וואָס „יש בזה שני כפי\"ן\" — ע\"פ המבואר בלקו\"ת42 אַז די שני כפי\"ן זיינען מרמז לב' הבחינות שבכתר אריך ועתיק43. ווייל גילוי תורת החסידות עד",[["31","31","שמח\"ת תרס\"א — נדפסה בס' השיחות שם ע' 141 ואילך. לקו\"ד שם תשפז, ב ואילך."],["32","32","שבת נו, א."],["33","33","תהלים פט, נב."],["34","34","שם, נג. וראה פסיקתא רבתי פט\"ז, טו: אם ראית דור אחר דור מחרף צפה לרגליו של מלך המשיח, ומה טעמי', אשר חרפו אויביך ה' אשר חרפו עקבות משיחך ומה כתב בתרי' ברוך ה' לעולם אמן ואמן."],["35","35","דגדול העונה אמן כו' (נזיר בסיומה)."],["36","36","אגה\"ק דהבעש\"ט שבהערה 14."],["37","37","ראה גם לקו\"ש ח\"ג ע' 863. חכ\"ד ע' 10. ובכ\"מ."],["38","38","תבוא כז, ח ובפרש\"י."],["39","39","בענינים המותרים להם."],["40","40","וענין זה מרומז גם בשמו „שלום דובער\" — המשכת שלום (קו האמצעי, העולה עד הכתר) למטה מטה, בבחי' „דוב\" — „המסורבל בבשר\" (קידושין עב, א ובפרש\"י), ו„בער\" — תרגום בלע\"ז (ע\"ד „כתרא\" תרגום דכתר כדלקמן). ראה בארוכה שיחות: ש\"פ ויקרא תשמ\"ב. ליל הושע\"ר תשד\"מ. ש\"פ תצא תשמ\"ה. כ\"ף מ\"ח תשמ\"ו. ועפ\"ז יש לומר קשר הדברים במה שאמר הצ\"צ בעת קריאת שם בעל יום ההולדת „רש\"ב, בשר שבר — צריכים לשבור בשר הגוף\" (ובהמשך לזה אמר כנ\"ל) „ונולד כ' חשון תרכ\"א, שיש בזה שני כפי\"ן, שהוא רומז לכתרא עילאה\" — דהקשר בין „בשר שבר\" עם „כתרא עילאה\" מובן ע\"פ הנ\"ל — שענינו של אדמו\"ר מהורש\"ב הוא המשכת כתרא עילאה — שלום — למטה מטה ב„בשר שבר\"."],["41","41","ולהעיר גם, שכ\"ף חשון הוא לעולם חמשים יום מראש השנה (ובאותו יום בשבוע דר\"ה) — שענינו של ר\"ה הוא שתמליכוני (ר\"ה טז, א. וש\"נ), המשכת בחי' כתר (רצון ותענוג) למטה מטה (ראה ברכת עיו\"כ ס\"ה (סה\"ש תשמ\"ז שם ע' 7־6). וש\"נ). וענין זה נתגלה בעבודה בעולם (שהתחיל בעיקר בחודש חשון — ראה לקו\"ש ח\"כ ע' 358. ובכ\"מ) במיוחד חמשים יום לאחרי זה (כ\"ף חשון) המרמז על גילוי שער הנו\"ן, בחי' כתר (ראה לקו\"ת במדבר יב, א ואילך. ובכ\"מ)."],["42","42","שה\"ש לה, ג. וראה ס' הערכים שבהערה 3. וש\"נ."],["43","43","וי\"ל שהב' כפי\"ן שבנדו\"ד (כ' מ\"ח תרכ\"א) הם כנגד מנין השנים (תרכ\"א) — חיצוניות הכתר, ומנין החדשים (כ' מ\"ח) — פנימיות הכתר (ראה"]]],[1300251329,"למטה מטה („חוצה\" ממש) דורך דעם רבי'ן נ\"ע איז דער חיבור פון עתיק און אריך: דאָס ווערט נמשך (ניט בלויז מבחי' אריך, חיצוניות הכתר, ששייך לסדר השתלשלות, נאָר) מבחי' עתיק, פנימיות הכתר44, שלמעלה מסדר השתלשלות לגמרי, אָבער דאָס ווערט נמשך בבחי' אריך, מקור לסדר השתל־ שלות, ועי\"ז — בכל סדר השתלשלות.\nאון דער יום כ' (כתר) בשנת כתר\"א איז בחודש מרחשון — וואָס ווערט אָנגערופן „ירח בול\"45 על שם ירידת הגשמים שבחודש זה46, וואָס ירידת גשמים איז פאַרבונדן מיט עבודת התשובה47 — ענינה פון תורת החסי־ דות48, צו מהפך זיין אויך דעם תחתון שבתחתון דורך עבודת התשובה.\nד. ויש להוסיף, אַז דער יום הולדת איז געווען בשנת תרכ\"א, „כתר\"א\" בלשון תרגום (ניט בשנת תר\"כ, אותיות כתר בלשון הקודש), וכלשון הצ\"צ „כתרא עילאה\" (ניט „כתר עליון\") — ווייל תוכן עבודת בעל יום ההולדת איז געווען המשכת בחי' כתר (תורת החסידות) בלשון תרגום (כתרא), פון די שבעים לשון דאוה\"ע, בכדי מברר זיין די שבעים לשון פון דעם פירוד בעולמות בי\"ע, וואָס איז „חוצה\" לגבי עולם האצילות, עולם הקודש (לשון הקודש)49. ווי דאָס איז אַרויס בגלוי ממש דורך בנו ממלא מקומו כ\"ק מו\"ח אדמו\"ר50 — ע\"י תרגום תורת החסידות „בשבעים לשון\".\nה. דערפון האָט מען אויך אַ לימוד בכ\"ף חשון בכל שנה ושנה:\nביום הולדת פון יעדער מענטש איז „מזלו גובר\"51. עאכו\"כ פון אַ נשיא הדור, וואָס „הנשיא הוא הכל\"52, און ער איז („נשיא\" מלשון) מנשא (הויבט אויף) הכל, כל אנשי הדור — איז דאָך מובן אַז ביום הולדת פון אַ נשיא, ווען „מזלו גובר\" (ניט נאָר הבנתו והשגתו — דמאי קמ\"ל, נאָר אויך „מזלו\", בחי' כתר שבו53, און פון כתר ווערט עס נמשך אין אַלע כחות), טוט עס אויף אַ התגברות במזלו ובכל הכחות פון כל אחד ואחת מאנשי דורו, און דורך בנו ממלא מקומו כ\"ק מו\"ח אדמו\"ר נשיא דורנו — ווערט נמשך אין כל אנשי דורנו אַ התגברות במזלם, בחי' כתר, און אין אַלע כחות.\nד.ה. אַז בכ\"ף חשון מדי שנה בשנה האָט כאו\"א אַ התגברות מיוחדת אין די כחות צו טאָן אין דער עבודה פון דעם בעל יום ההולדת, וועלכע ער האָט איבערגעגעבן לכל אנשי דורו, וע\"י בנו",[["","","אוה\"ת בראשית יט, א ואילך. ד\"ה החודש תרנ\"ד. שיחת כ\"ף מ\"ח תשמ\"ו)."],["44","44","ראה לעיל סעיף א', שחסידות היא מפנימיות הכתר."],["45","45","מלכים א ו, לח."],["46","46","ראה ירושלמי ר\"ה פ\"א ה\"ב. פסיקתא רבתי פ\"ו, ה. יל\"ש מלכים רמז רפד."],["47","47","ראה תענית ח, ב ואילך."],["48","48","כנ\"ל הערה 23."],["49","49","ראה תו\"א משפטים עז, ד. עח, ג. וראה לקו\"ש ח\"ג ע' 862. חכ\"ד שם. ובכ\"מ."],["50","50","שעבודתו מתחילה (בכח) בעבודת אביו אדמו\"ר נ\"ע. וע\"ד המבואר (ראה ביאוה\"ז לאדהאמ\"צ ויחי כט, ד ואילך. ולהצ\"צ שם ע' קסח ואילך. אוה\"ת ויחי שפה, ב ואילך. ועוד. וראה לקו\"ש ח\"ג ע' 832 ואילך) בנוגע ליעקב ויוסף (שמו הראשון של כ\"ק מו\"ח אדמו\"ר), שיוסף (יסוד) ענינו להמשיך כל עניני יעקב (אצילות) בעולמות בי\"ע."],["51","51","ראה ירושלמי ר\"ה פ\"ג ה\"ח ובקה\"ע שם. וראה שיחת כ\"ף מ\"ח תשד\"מ."],["52","52","פרש\"י חוקת כא, כא."],["53","53","פרדס שער ערה\"כ ערך מזל. וראה תקו\"ז ת\"י (כה, ב)."]]],[1300251330,"ממלא מקומו — לכל אנשי דורנו — דער כללות הענין פון הפצת המעינות חוצה, המשכת כתר (פנימיות התורה) למטה מטה, אין „חוצה\" ממש, ביז אין תרגום („כתר\"א\") „בשבעים לשון\".\nואדרבה: בכל שנה ושנה ווערט, קומט אין דעם צו אַן עלי' והתגברות נוספת, וואָרום „מעלין בקודש\"54, ובפרט אַז בכל שנה ושנה ווערט נמשך אַן „אור55 חדש שלא הי' מאיר עדיין מימי עולם אור עליון כזה\"56. ועאכו\"כ מדור לדור (דור גם מלשון שורה57, וכולל כו\"כ שנים), וואָס איז שלא בערך מער פאַר די עלי' משנה לשנה.\nו. ועאכו\"כ בכ\"ף חשון שנה זו, וואָס איז: א) אַ שנת השמיטה, ב) ביום השבת58 — וואָס אויך אין דעם איז אונטערשטראָכן די נקודה הנ\"ל — התגלות תורת החסידות (כתר שב־ תורה) למטה מטה.\nוביאור הענין:\nדער תוכן פון שנת השמיטה איז בדומה צו דער תוכן פון יום השבת59: כשם ווי „ויברך אלקים את יום השביעי (של היקף השבועי) ויקדש אותו\"60, אַזוי אויך בהיקף של שבעת השנים, האָט דער אויבערשטער מברך ומקדש גע־ ווען די שנה השביעית. און דערפאַר דאַרף דעמולט זיין „ושבתה הארץ שבת לה'\"61, אַז מ'איז דעמולט שובת ממלאכת האדמה, חרישה וזריעה וכו', בדומה צו תוכן יום השבת, ווען מ'איז שובת מכל מלאכה.\nובלשון הקבלה והחסידות62 — בשנת השמיטה („שבת לה'\") ווערט עליית המלכות ועליית העולמות בי\"ע לעולם האצילות, און דעריבער איז דעמולט אסור מלאכת האדמה (מלכות), ע\"ד ווי עליית המלכות והעולמות ביום השבת, מעולם המעשה לעולם הדיבור ועולם המחשבה63.\nד.ה. אַז בשנת השמיטה (ע\"ד ווי ביום השבת) שטייט אַ איד העכער פאַר וועלט — ער פאַרנעמט זיך ניט מיט די פעולות גשמיות הרגילות בחיי יום יום (בשאר השנים), וואָס דאָס שטרייכט אונטער זיין פאַרבונד מיט דעם אויבערשטן — סיי מצד דעם וואָס ער האָט דעמולט ניט די בילבולים פון טרדות הפרנסה בעוה\"ז הגשמי, און ער פאַרלאָזט זיך אויפן אויבערשטן64, און סיי מצד דעם וואָס ער נוצט אויס די ליידיקע צייט און כחות אויף הוספה בעבודת ה', לימוד",[["54","54","ברכות כח, א. וש\"נ."],["55","55","אגה\"ק סי\"ד."],["56","56","כידוע שגם לאחרי צאת הנשמה מן הגוף יש (הוספה ב)ענין הזמן (בהמשך להשנים שהיתה נשמה בגוף למטה) — ראה רשימת כ\"ק מו\"ח אדמו\"ר בנוגע לאביו בעל יום ההולדת (נדפסה בהוספות לסה\"מ פר\"ת ע' שנז. וש\"נ). וראה לקו\"ש ח\"ה ע' 103 ואילך. וע\"ד הנגלה והלכה — ראה צפע\"נ על הרמב\"ם הל' תשובה פ\"ח ה\"ד. כללי התומ\"צ אות ב, י."],["57","57","מאמרי אדה\"ז תקס\"ה (כרך א) ע' תיט. אוה\"ת לתהלים (יהל אור) ע' תקמט ואילך."],["58","58","נוסף על זה שכל השנה התחלתה ביום השבת, יו\"ט של ר\"ה שחל להיות בשבת. וראה לעיל הערה 41."],["59","59","ראה חינוך מצוה של. סהמ\"צ להצ\"צ מצות קדושת שנת השביעית. וש\"נ. וראה ויק\"ר פכ\"ט, יא. רמב\"ן בהר כה, ב. ועוד."],["60","60","בראשית ב, ג."],["61","61","כשם שנאמר בשבת בראשית (פרש\"י בהר שם)."],["62","62","סהמ\"צ להצ\"צ שם. וש\"נ."],["63","63","ראה לקו\"ת שבת שובה סו, ג. סה\"מ תרס\"ה ע' י. תש\"ג ע' 38."],["64","64","שזהו אחד מהענינים בשנת השמיטה — ומורה על חידוש העולם ועל בורא העולם ומנהיגו (ראה חינוך מצוה פד. רמב\"ן בהר שם)."]]],[1300251331,"התורה ועבודת התפלה. ווי עס שטייט אין מפרשים65 בנוגע לשנת השמיטה „שתהי' כל השנה הבטלה מעבודת האדמה מוכנת לעבודתו . . שגם עובדי האדמה כאשר ישבתו בשנה ההיא יתעוררו לדרוש את ה'\". און — אין אַן אופן פון יגיעה בלימוד התורה כו': כשם ווי אין די שש שנים איז געווען „יגיע כפיך\"66, „בזיעת אפיך תאכל לחם\"67, נוצט ער אויס (בשנת השמיטה) דעם כח היגיעה אין לימוד התורה ועבודת ה'.\nכולל ובמיוחד אין לימוד פנימיות התורה — בחי' שבת שבתורה (וואָס איז נשמתא68 פון נגלה דתורה וואָס פאַר־ נעמט זיך מיט בירורי טוב ורע כו'<sup data-n=\"69\">69</sup>.\nצוזאַמען דערמיט איז ניט דער פשט אַז דעמולט פעלט אין פרנסה והשפעות בעוה\"ז הגשמי (וואָס מ'באַקומט בהשש שנים דורך מלאכת האדמה), נאָר כמקרא מלא70 „וצויתי את ברכתי לכם בשנה הששית ועשת את התבואה לשלש השנים\"71.\nד.ה. אַז אין די שש שנים באַקומט ער די ברכה בפרנסה דורך יגיעה במלאכת האדמה, און בשנת השמיטה באַקומט ער די ברכה בפרנסה דורך יגיעה בלימוד התורה ועבודת התפלה כו'.\nעפ\"ז איז מובן, אַז דער תוכן הנ\"ל פון יום הולדת אדמו\"ר נ\"ע בכ' חשון שנת כתר\"א (המשכת בחי' כתר, גילוי תורת החסידות, למטה מטה) קומט נאָך שטאַרקער אַרויס אין אַ שנת השמיטה — ווייל דאָס איז אויך מתוכן שנת השמיטה: עליית (כתר) מלכות72 למעלה מעלמא דפרודא (בי\"ע), און ווי בחי' (כתר) מלכות שטייט למעלה, ווערט פון דאָרט נמשך למטה מטה בעוה\"ז הגשמי73, „וצויתי את ברכתי לכם בשנה הששית ועשת את התבואה לשלש השנים\". ובעבודה — אַ שנה געוויד־ מעט צו לימוד התורה, כולל ובמיוחד פנימיות התורה (שבת שבתורה), און אין אַן אופן אַז דאָס ווערט נמשך למטה מטה אין „חוצה\" ממש (כתר\"א לשון תרגום).\nז. בסגנון אחר:\nיום השבת האָט אין זיך צוויי ענינים: א) יום השביעי, דער המשך וסיום ושלימות פון די שבעת ימי בראשית74. ב) עליית כל השבעה ימים למעלה מן",[["65","65","ספורנו בהר שם. וראה מכתב ל' תשרי ר\"ח מרחשון תשמ\"ז (נדפס בסה\"ש תשמ\"ז ח\"ב בהוספות). וש\"נ."],["66","66","תהלים קכח, ב."],["67","67","בראשית ג, יט."],["68","68","זח\"ג קנב, א."],["69","69","ראה אגה\"ק סכ\"ו."],["70","70","בהר כה, כא."],["71","71","וגם השש שנים מקבלים השפעתם משנת השמיטה — ראה אוה\"ת בהר (כרך ב') ע' תקצד ואילך. ועוד."],["72","72","ראה תקו\"ז בהקדמה (פתח אליהו): כתר עליון איהו כתר מלכות. וראה אגה\"ק ס\"כ (קל, ב). לקו\"ת ר\"ה נו, ג. ועוד."],["73","73","ליתר ביאור: גם עבודת האדמה בשש שנים (עובדין דחול) היא עבודה ע\"פ תורה (ולהעיר שחרישה וזריעה היו עבודות במשכן), לקיים „לשבת יצרה\" (ישעי' מה, יח). ועאכו\"כ עבודת האדמה ע\"י ישראל, שהוא „מאמין בחי העולמים וזורע\" (תוד\"ה אמונת — שבת לא, א), כלומר שהוא מכיר בטבע עצמו בחי' אלקות שלמעלה מהטבע (ראה לקו\"ש חט\"ז ע' 370. וש\"נ): אבל מ\"מ ה\"ז התלבשות (תפיסא עכ\"פ) בדרך הטבע, עבודת החרישה וזריעה כו', וי\"ל שהוא בדוגמת בחי' אריך, שהוא למעלה מעולם (טבע) וסדר השתלשלות, אבל בערכו (שרש הנאצלים). משא\"כ בשנת השמיטה ההמשכה היא ע\"י עבודה רוחנית (לימוד התורה כו'), וי\"ל בדוגמת עתיק שנעתק לגמרי מעולם וסדר השתלשלות, ומשם נמשך בעוה\"ז הגשמי („וצויתי את ברכתי\")."],["74","74","ראה אוה\"ת בראשית ד\"ה ויכולו (כרך א מב, ב ואילך. כרך ג תקח, א ואילך). ועוד."]]],[1300251332,"הזמן. דעריבער הויבט מען דערנאָך אָן ציילן זמן מחדש „היום יום ראשון\"75. ובספירות: א) ספירת המלכות (סיום וגמר פון די שבע מדות). ב) ספירת הכתר (למעלה מזמן וסדר זמנים). ובספירת הכתר עצמו — בחי' עתיק, שנעתק ומובדל לגמרי פון זמן (משא\"כ אריך האָט נאָך עפּעס אַ שייכות מיט סדר זמנים).\nוי\"ל אַז עד\"ז האָט אין זיך שנת השמיטה („שבת לה'\", שבת בשנים) ביידע ענינים: א) שנה השביעית, אַ המשך וסיום ושלימות פון די שש שנים — בחי' מלכות. ב) עליית השבע שנים למעלה מן הזמן (דעריבער הויבט מען דערנאָך אָן אַ מספר חדש פון שבע שנים) — בחי' כתר.\nקומט אויס אַז אין שנת השמיטה איז דאָ דער חיבור פון ביידע ענינים הנ\"ל בעבודת בעל יום ההולדת — המשכת שלימות הכתר (שלמעלה מעולם) אין מלכות, און אין די שבע שנים פון סדר בראשית (עולם). כידוע76 אַז שרש המלכות איז פון כתר, און כתר ווערט נמשך דוקא אין מלכות (נעוץ סופן בתחלתן ותחלתן בסופן<sup data-n=\"77\">77</sup>, סוף מעשה במחשבה תחלה.\nויש להוסיף, אַז דער יום ההולדת איז קרוב לתחלת שנת השמיטה (כ\"ף חשון) — ע\"ד פירוש החסידות78 אין „סוף מעשה במחשבה תחלה\"79, אַז „סוף מעשה\" נעמט זיך אין מחשבה גופא — פון תחלת המחשבה. ובנדו\"ד: כ\"ף חשון איז בתחלת שנת „שבת לה'\", „במחשבה תחלה\" (כנ\"ל אַז שבת איז בחי' המחשבה), און פון דאָרט ווערט נמשך אין „סוף מעשה\", אין מלכות, ביז אין עולמות בי\"ע, ביז אין „חוצה\" ממש.\nח. דערפון איז פאַרשטאַנדיק, אַז אין אַלע מועדים, כולל בכ\"ף חשון בשנה זו — אַ שנת השמיטה (און אויך ביום השבת) — קומט צו אַן עלי' והתגברות ביתר שאת וביתר עוז אין דעם „מזלו גובר\" פון בעל יום ההולדת — המשכת והפצת פנימיות התורה (כתר) למטה מטה, אין „חוצה\" ממש.\nט. והמעשה הוא העיקר80 (סוף מעשה במחשבה תחלה):\nשטייענדיק בכ\"ף חשון, יום הולדת אדמו\"ר נ\"ע, וביום השבת ובשנת השמיטה — האָט כאו\"א אַ התגברות מיוחדת אין די כחות צו טאָן אין דער עבודה פון דעם בעל יום ההולדת, וועל־ כע ער האָט איבערגעגעבן לכל אנשי דורו, וע\"י בנו ממלא מקומו — לכל אנשי דורנו — דער כללות הענין פון הפצת המעינות חוצה, המשכת כתר (פנימיות התורה) למטה מטה, אין „חוצה\" ממש, ביז אין תרגום („כתר\"א\") „בשבעים לשון\".\nובפשטות: הוספה בלימוד התורה מתוך יגיעה, כולל ובמיוחד יגיעה בלימוד תורת החסידות, כולל — די מאמרי חסידות פון דעם בעל יום ההולדת, כמאמר הידוע שלו81 „די כתבים לאָז איך אייך\",",[["75","75","לקו\"ת שה\"ש כה, א. רד\"ה ביום השמיני תרע\"ח. ובכ\"מ."],["76","76","ראה לעיל הערה 72."],["77","77","ספר יצירה פ\"א מ\"ז."],["78","78","ראה תו\"ח ר\"פ ויגש. המשך תרס\"ו ע' יט ואילך. המשך תער\"ב ח\"ב ע' א'קיז ואילך."],["79","79","פיוט לכה דודי."],["80","80","אבות פ\"א מי\"ז."],["81","81","הועתק במכתב זקני אנ\"ש — נדפס באגרות־ קודש אדמו\"ר מהוריי\"צ ח\"א ע' קיג. נת' בלקו\"ש חכ\"ז ע' 24 ואילך."]]],[1300251333,"און דערפון זאָל עס נמשך ווערן אין יגיעה בלימוד הנגלה, און — בלימוד שניהם יחד (נגלה און חסידות). און אין אַן אופן אַז דאָס פאַרשטייט אויך דער שכל פון נה\"ב („תרגום\" פאַר „חוצה\" שבאדם עצמו).\nוגדול לימוד שמביא לידי מעשה82 — פון לימוד התורה („די כתבים\"), „דע את אלקי אביך\"83, זאָל עס נמשך ווערן אין מעשה, „חוצה\" שבאדם, „ועבדהו בלב שלם\"83, אהבה ויראה, פון וועלכע עס ווערט נמשך בכל המצוות כולם — הוספה בקיום המצוות בהידור.\nכולל ובמיוחד אין די מעשה ועבודה אין „חוצה\" פון עוה\"ז הגשמי — צו „פאַרשרייבן זיך\" אין „כל היוצא למלחמת בית דוד\", צו טאָן אין הפצת היהדות והתורה, און הפצת המעינות — חוצה, ביז אין חוצה שאין חוצה ממנו, כולל דורך איבערזעצן חסידות צו יע־ דערן באותיות (ולשונות) המתאימות לפי הבנתו והשגתו.\nאון ספּעציעל דורך די הוספה באופן הפצת המעינות חוצה וואָס איז צוגעקו־ מען בדורנו זה, ובמיוחד בזמן האחרון84 — דורך א) אויפשטעלן (אָדער מרחיב זיין) אַ „בית חב\"ד\" בכל מקום ומקום, בית תורה תפלה וגמ\"ח, און ב) „עשה85 לך רב\":\nענינו פון אַ „בית חב\"ד\" איז — הפצת המעינות חוצה באופן של קביעות והתיישבות (בית). און דער „בית חב\"ד\" בכל מקום באַלייכט — ממנו יוצא אורה — די גאַנצע שכונה און שטאָט („חוצה\") מיט אור התורה דורכגענומען אויך מיט אור פון תורת חסידות חב\"ד, ובאופן אַז דאָס ווירקט אין די הנהגה במעשה בפועל86. ע\"ד ובדוגמת התייסדות ישיבת תומכי תמימים — לימוד תורת החסידות והפצת המעינות חוצה באופן של קביעות והתיישבות, וממנו יוצא אורה לכל הסביבה.\nדער תוכן פון „עשה לך רב\" איז — באַשטימען פאַר זיך אַ רב מיט וועמען ער קען זיך מיישב זיין און בעטן אַן עצה וכיו\"ב (און טוט אַזוי בפועל — וזהו העיקר) בנוגע צו זיין לימוד התורה, כולל לימוד פנימיות התורה, און עבודת ה', כולל — הפצת המעינות חוצה. וואָס דאָס פאַרשטאַרקט נאָכמער די עבודה ופעולה ויגיעה אין לימוד החסידות והנגלה, און אין הפצת המעינות חוצה.\nיוד. ויש להוסיף רמז צו די צוויי ענינים בפרשתנו:\nא) „ויטע87 אשל — פונדק לאכסניא88 — בבאר שבע ויקרא שם בשם ה' א־ל עולם\", „על ידי אותו אשל נקרא שמו של הקב\"ה אלוקה לכל העולם, לאחר שאוכלים ושותים אמר להם ברכו למי שאכלתם משלו\"88. וואָס דאָס איז דער ענין פון אַ „בית חב\"ד\": אַ פונדק לאכסניא, וואו יעדער איד קען אַריינ־ גיין און איבערנעכטיקן און באַקומען וואָס צו עסן און טרינקען89 (ועאכו\"כ) —",[["82","82","ב\"ק יז, א. וש\"נ."],["83","83","דה\"א כח, ט. וראה קו\"א ד\"ה להבין מ\"ש בפע\"ח (קנו, ב)."],["84","84","ראה לעיל ע' 302 ואילך. וש\"נ."],["85","85","אבות פ\"א מ\"ו. שם מט\"ז."],["86","86","ולהעיר שבית הוא בחי' כתר, ובכתר עצמו — פנימיות הכתר, מקיף הרחוק (לקו\"ת ס\"פ ברכה), וממנו נמשך ויוצא אורה לכל סביבתו, „חוצה\"."],["87","87","פרשתנו כא, לג."],["88","88","פרש\"י עה\"פ שם. מסוטה י, סע\"א."],["89","89","אש\"ל ר\"ת אכילה שתי' לינה (יש גורסים במדרש תהלים לז). ולכאורה משמע כן בפרש\"י"]]],[1300251334,"לערנען תורה, מתפלל זיין און געבן צדקה וכיו\"ב. און דורך דעם „אשל\" ווערט90 „ויקרא87 שם בשם ה' א־ל עולם\"91.\nב) „ולוט ישב בשער סדום\"92, ופרש\"י: „ישב כתיב, אותו היום מינוהו שופט עליהם\". ד.ה. אַז אפילו אנשי סדום, וועלכע זיינען געווען „רעים וחטאים לה' מאד\"93, האָבן געפונען נויטיק צו ממנה זיין אויף זיך אַ שופט — „עשה לך רב\", און האָבן פאַרשטאַנען מעצמם אַז דער שופט דאַרף זיין ניט בדומה להם נאָר אברהם'ס אַ קרוב, עאכו\"כ ווען עס רעדט זיך וועגן (להבדיל) אידן און נאָך מתן תורה!\nיא. דער לימוד הנ\"ל (פון דעם בעל יום ההולדת) במובן רחב יותר:\nידוע ומפורסם דער גודל ההשתדלות בענין החינוך פון בעל יום ההולדת94, ועד\"ז פון בנו ממלא מקומו כ\"ק מו\"ח אדמו\"ר. אַז ניט קוקנדיק אויף די ענינים הכי עיקריים והכי חיונים וואָס זיי האָבן געטאָן, איז באַ זיי געווען אַ ספּעציעלע השתדלות בענין החינוך.\nויש לומר אַז בכללות (במובן הרחב) איז דאָס פאַרבונדן מיט די התרחבות אין הפצת היהדות והפצת המעינות חוצה וואָס איז צוגעקומען ע\"י דעם בעל יום ההולדת ובנו ממלא מקומו (המשכת כתר למטה מטה) — אַ התרחבות בענין החינוך, סיי חינוך עצמו, דורך הפצת התורה והיהדות והמעינות אין דעם „חוצה\" שבאדם, ע\"י הוספה בלימוד התורה, חסידות ונגלה, בהבנה והשגה, אויך פאַרן נה\"ב כו', און סיי חינוך הזולת — הפצת התורה והיהדות והמעינות אין דעם „חוצה\" כפשוטו, כנ\"ל.\nהאָט מען דערויף די הוראה — שטייענדיק בכ\"ף חשון, ווען „מזלו\" של (עבודת) בעל יום ההולדת „גובר\" — אַז כל אחד ואחת דאַרף מוסיף זיין ביתר שאת וביתר עוז אין ענין החינוך:\nסיי חינוך עצמו, „קשוט עצמך\"95, כולל — דורך קיום הוראת המשנה „עשה לך רב\",\nאון סיי חינוך הזולת, „(ואח\"כ) קשוט אחרים\"95, אָנהויבנדיק פון חינוך בפשטות — חינוך ילדים, קטנים וקטנות96, און אויך חינוך פון קטנים וקטנות בידיעות, כולל — בידיעת ההכרח אַז פון יעדער ידיעה דאַרף אַראָפּקומען אין מעשה בפועל („טאָפּאָרו דאָ פּלאָחו\"<sup data-n=\"97\">97</sup>. ד.ה. ניט בלויז אַז „טוב הדבר\", נאָר „טוב לי הדבר\".",[["","","סוטה (י, סע\"א) „פונדק ללון\". וא\"כ צ\"ל בסוף דברי רש\"י שם „לינה\" במקום „לוי'\". וראה לקו\"ש חט\"ז ס\"ע 501. וש\"נ."],["90","90","ראה ד\"ה ויטע אשל — אוה\"ת פרשתנו (כרך ד) תשנט, ב ואילך. תר\"ל, תר\"ן, תרנ\"ה. סה\"מ תש\"ט ע' 94. ד\"ה הנ\"ל שנאמר בהתוועדות."],["91","91","ועפ\"ז מתורץ ומובן גודל העילוי בזה שאברהם נטע אשל בבאר שבע."],["92","92","פרשתנו יט, א."],["93","93","לך יג, יג."],["94","94","ראה בארוכה קונט' חנוך לנער."],["95","95","ב\"מ קז, סע\"ב. הובא בפרש\"י עה\"ת בראשית ד, כה."],["96","96","וידועה שיחת בעל יום ההולדת (ס' השיחות תורת שלום ע' 54. הועתק ממכתב כ\"ק מו\"ח אדמו\"ר (אגרות קודש שלו חי\"א ע' קפח ואילך)): אָט אַזוי ווי הנחת תפילין בכל יום איז אַ מצוה דאורייתא אויף יעדער אידן, אָהן אַ חילוק צי אַ גדול בתורה צי אַ איש פשוט, אָט אַזוי איז אַ חוב גמור אויף יעדער אידן טראַכטן יעדער טאָג אַ האַלבע שעה וועגן דעם חינוך פון קינדער און טאָן אַלץ וואָס בכחו איז צו טאָן, און יתר מכפי כחו פועל זיין באַ די קינדער אַז זיי זאָהלען גיין אין דעם דרך וואָס מי איז זיי מדריך."],["97","97","ראה ס' השיחות ה'ש\"ת ע' 105. תש\"ב ע' 84. תש\"ד ע' 104. ועוד."]]],[1300251335,"ובפשטות — דורך אויפשטעלן (אָדער מרחיב זיין) מוסדות חינוך בכל מקום ומקום, וואו אידישע קינדער קענען באַ־ קומען אַ חינוך הכשר וחינוך על טהרת הקודש, און אַזוינע מוסדות וואָס וועלן האָבן די מעגלעכקייט צו אַרייננעמען און צוציען וואָס מער אידישע קינדער, אַזוי אַז אין דער שטאָט (פון דעם מוסד חינוך) זאָל ניט זיין קיין עיכוב מצד המוסד פון אַרייננעמען און מחנך זיין די אַלע אידישע קינדער וואָס לעבן דאָרט (און די איינציקע השתדלות וואָס דאַרף זיין איז — צו אַראָפּנעמען די מניעה מצד העדר ידיעת ההורים וכיו\"ב).\nועד\"ז מוסדות חינוך פאַר גדולים בשנים — דורך אויפשטעלן בתי חב\"ד בכל מקום ומקום, וואָס ענינם איז צו מחנך זיין די אידן אין דעם מקום (כנ\"ל ס\"י).\nיב. אין דעם גופא קומט צו די הוראה פון דעם רבי'ן מהר\"ש (דער פאָטער פון דעם בעל יום ההולדת) — „מלכתחילה אַריבער\"98.\nוויבאַלד אַז הקמת מוסדות חינוך, בתי חב\"ד וכיו\"ב איז פאַרבונדן מיט הוצאות כספיות (ויגיעה וזמן כו') — קען זיין אַ קס\"ד, אַז ביז מ'האָט ניט די געלט במזומן, וועט מען ניט אויפשטעלן דעם מוסד.\nאויף דעם האָט מען די הוראה — אַז מ'דאַרף זיך אין דעם פירן באופן פון „מלכתחילה אַריבער\" (אָבער כמובן — אַ הנהגה פון עולם התיקון<sup data-n=\"99\">99</sup>, ניט אָפּ־ האַלטן די הקמה פון אַ מוסד חינוך צוליב דעם וואָס עס פעלט געלט; נאָר אויפשטעלן המוסד און דערנאָך זיך משתדל זיין שאַפן די געלט, און אויס־ צאָלן וכו'.\n[זיכער איז בעסער האָבן די געלט פאָראויס, אָבער מ'קען צוליב דעם ניט אָפּשטופּן די הקמה פון דעם מוסד חינוך].\nווי מ'לערנט אָפּ פון כ\"ק מו\"ח אדמו\"ר, וואָס ער האָט געזאָגט אַז ער האָט אַלעמאָל געהאַט אַ דעפיציט (בהנהלת המוסדות); אָבער לאידך גיסא — איז ער קיינמאָל ניט געבליבן קיין בעל־חוב, ווייל סוף סוף האָט ער אַלעמען אָפּגעצאָלט.\nאון די הסברה בזה איז בפשטות: אפילו אויב מ'האָט ניט די געלט גלייך אָפּצוצאָלן — איז דאָס טאַקע ניט אַזוי באַקוועם און געשמאַק, אָבער דורך דעם פעלט ניט אין דעם עצם הענין: אויב ער קען היינט ניט אָפּצאָלן, צאָלט ער אָפּ מאָרגן וכיו\"ב; משא\"כ אויב מ'וועט ניט גלייך אויפשטעלן (און אויפהאַלטן) דעם מוסד חינוך וכיו\"ב, און מ'וועט וואַרטן ביז מ'וועט האָבן די געלט מאָרגן, ועאכו\"כ „יש מחר לאחר זמן\"100 — קען דאָך דערוויילע פאַרפאַלן ווערן אַ אידיש קינד ר\"ל וועלכן מ'האָט איצטער געקענט מציל זיין און שפּעטער וועט מען אים ניט טרעפן. און יעדער קינד איז דאָך אַן „עולם מלא\"100*!\nד.ה. אַז דאָס איז אַ שאלה פון פקו\"נ (ברוחניות) — וואָס איז דוחה כל התורה כולה101. במילא איז מובן, אַז ווען מ'האָט",[["98","98","הובא במכתב כ\"ק מו\"ח אדמו\"ר (אגרות־ קודש שלו חי\"א ע' תריז)."],["99","99","ראה בארוכה שיחת יום שמח\"ת (סה\"ש תשמ\"ז ע' 32 ואילך) שהעבודה דמלכתחילה אַריבער הוא „אַריבער\" ההנהגה ד„עולם התיקון\", ולא ההנהגה ד„עולם התוהו\"."],["100","100","ע\"פ מכילתא ופרש\"י בא יג, יד. ועוד. 100*) סנהדרין לז, א (במשנה). וש\"נ. רמב\"ם הל' סנהדרין פי\"ב ה\"ג. וראה רמב\"ם הל' רוצח ושמירת נפש ספ\"א."],["101","101","ראה יומא פב, א. כתובות יט, א. ועוד."]]],[1300251336,"ניט קיין ברירה, און מ'דאַרף אויס־ קלייבן איינע פון די ביידע מעגלעכ־ קייטן (גלייך אויפשטעלן דעם מוסד, אָדער וואַרטן ביז מ'האָט געלט) — איז קיין ספק ניט אַז לכל לראש דאַרף זיין „תן לי הנפש\"102, הצלת נפשות, און דערנאָך געפינען די מיטלען אויסצו־ צאָלן די הוצאות.\nעאכו\"כ בזמננו זה, ווען דער צד שכנגד רוט ניט און זוכט אַלע מעג־ לעכקייטן צו פאַרכאַפּן ר\"ל אידישע קינדער (און ערוואַקסענע), מיט כל מיני פאַלשקייטן, ביז אויך אָפּרייסן קינדער פון זייערע עלטערן וכו',\n[ווי ס'איז געווען בנוגע צו די ילדי טהרן וילדי תימן ר\"ל103, ועד היום הזה האָט מען ניט מברר געווען שמותיהם און די ערטער וואו זיי זיינען אַהין־גע־ קומען] —\nאיז נאָך שטאַרקער נוגע מס\"נ בצד הקדושה בענין החינוך, צו אַריינציען וואָס מער אידישע קינדער אין מוסדות של חינוך הכשר ועל טהרת הקודש, און דאָס ניט אָפּשטופּן אפילו אויף אַ רגע אחד (צוליב געלט וכיו\"ב).\nדעריבער איז איצטער נאָכמער הכרח ואחריות וזכות לכל אחד ואחת — צו טאָן כל התלוי בו אין דעם שטח פון חינוך ניט אָפּשטעלנדיק זיך צוליב קיינע מניעות — כאו\"א לויט זיינע מעגלעכ־ קייטן:\nדי וואָס האָבן אַ השפעה וכח בנוגע צו הקמת מוסד של חינוך, הנהלת המוסדות, תומכי המוסדות וכיו\"ב — האָבן דעם גודל הזכות והאחריות צו טאָן אין דעם אופן, ניט וואַרטנדיק ביז מ'האָט מזומן;\nאון די וואָס האָבן ניט די מעגלעכ־ קייט, האָבן זיי אַן אַנדער מעגלעכקייט צו זיך משתדל זיין בענין החינוך: חינוך פון די אייגענע קינדער. און אפילו אויב דער חינוך ביז איצטער איז געווען בשלימות — איז אין גוט קיין שיעור ניטאָ.\nאון אפילו אויב מ'האָט ניט אייגענע קינדער — האָט יעדערער די מעגלעכ־ קייט צו משפיע זיין בנוגע צו קינדער פון אַ קרוב אָדער אַ שכן, וואָס יעדער מענטש קומט אין באַרירונג מיט קינ־ דער, ווי מ'זעט בפשטות.\nיג. לאידך גיסא:\nמס\"נ העלפט אויף „אַראָפּשפּרינגען פון אַ דאַך\", אָבער ניט אויף „אַרויפ־ שפּרינגען אויף אַ דאַך\". ובעניננו: אפילו אויב מ'האָט מס\"נ אויף חינוך, און מ'רעכנט זיך ניט מיט אַ דעפיציט, קען מען אָבער ניט העלפן מיט מס\"נ אויף אַ זאַך וואָס איז ניט בכחו לדעת רב שאינו נוגע בדבר (ניט וואָס זיין יצר שמועסט עם איין אַז עס איז ניט בכחו). ד.ה. אַז די מס\"נ וועט ניט העלפן בשעת ס'איז דאָ אַ מחנך וכיו\"ב וואָס וויל אָבער בעקשנות האָבן געלט במזומן, אָדער בשעת מ'קען ניט באַקומען אַ הלואה בכדי דעקן די הוצאות, וכיו\"ב.\nדעריבער איז אשרי חלקם וגדול זכותם פון די בעלי צדקה וואָס שטעלן צו געלט במזומן פאַר אַ מוסד חינוך, בית חב\"ד וכיו\"ב, אַזוי אַז מ'דאַרף זיך ניט פאַרלאָזן אויף מס\"נ שאינו בכחו בהקמת והרחבת המוסד. ומהם יראו וכן יעשו רבים, ביז אַז זיי (הרבים) ווערן אויך „נרות להאיר\".",[["102","102","ל' הכתוב — לך יד, כא."],["103","103","ראה ס' השיחות תש\"ג ע' 128 ואילך. וראה אגרות־קודש אדמו\"ר מהוריי\"צ ח\"ז ס\"ע קפז ובהנסמן שם. ח\"ח ס\"ע ח ובהנסמן שם."]]],[1300251337,"יד. ויש להוסיף השייכות פון ענין החינוך (עבודתו המיוחדת פון דעם בעל יום ההולדת) מיט ענין השמיטה (וואָס איז בדוגמא די עבודה פון דעם בעל יום ההולדת, כנ\"ל ס\"ו־ז):\nאיינער פון די גרעסטע שוועריקייטן פון שנת השמיטה איז דער שפּרונג ושינוי הרגילות מן הקצה אל הקצה — אַז לאחרי הרגילות והחזקה פון „שש שנים תזרע שדך גו'\"104 (צוויי מאָל תלת זימני הוי חזקה<sup data-n=\"105\">105</sup>, דאַרף גלייך (ניט לאַט לאַט) זיין „ובשנה השביעית שבת שבתון יהי' לארץ גו'\"106, במשך אַ שנה שלימה107.\nוואָס דאָס איז דער תוכן פון חסידות במיוחד — די עבודה פון שינוי טבע הרגילות (וואָס דעמולט ווערט מען אָנ־ גערופן „עובד אלקים\"<sup data-n=\"108\">108</sup>, שינוי טבע מדותיו109 — וואָס אין דעם איז צוגע־ קומען אַ חידוש דורך דעם בעל יום ההולדת, כנ\"ל בארוכה.\nועפ\"ז איז מובן די שייכות מיט חינוך: דער גאַנצער ענין פון חינוך איז — בכדי משנה זיין טבע הרגילות: אַ קינד בטבע טוט ווי ביי אים קומט אויס, בלי שום הגבלות. ובלשון הכתוב — „יצר לב האדם רע מנעוריו\"110. דעריבער דאַרף מען אים מחנך זיין — בכדי מגביל זיין און משנה זיין טבע הרגילות שלו, ביז אַז ביי אים זאָל זיין מוח שליט על הלב. ועד\"ז חינוך פון גדולים בשנים איז תוכנו — משנה זיין רגילות שלהם בעבר און צוקומען צו אַ דרגא נעלית יותר.\nוואָס אע\"פ אַז דאָס איז דער תוכן העבודה במשך כל השנים, האָט מען אויף דעם ספּעציעלע כחות בשנת השמיטה, וואו מ'זעט בהדגשה ובגלוי — ובאופן שלא בערך — דעם שינוי הרגילות פון אַ מצב פון עבודת האדמה צו אַ מצב פון שביתת הארץ, און במקום זה — לימוד התורה ועבודת התפלה וכו'.\nהאָט מען די הוראה ונתינת כח פון שנת השמיטה — ובפרט בכ\"ף חשון בשנה זו — בגודל הנחיצות אויף ענין החינוך111 — זיך אַליין מחנך זיין און מחנך זיין אַנדערע, און נתעלה ווערן צו אַ העכערע דרגא בעבודת ה', בלימוד התורה, עבודת התפלה, קיום המצוות בהידור, הפצת היהדות והמעינות חוצה וכו', העכער ווי מ'איז געשטאַנען ביז דעמולט112.",[["104","104","בהר כה, ג."],["105","105","ב\"מ קו, ריש ע\"ב."],["106","106","בהר שם, ד."],["107","107","ועד כדי כך, ששינוי הרגילות (אפילו מן עבודה קשה לעבודה קלה) נקראת „עבודת פרך\" (סוטה יא, ב ובפרש\"י). ולהעיר מ„אכלושי דמחוזא, דאי לא עבדי חלשי\" (ב\"מ עז, א. וראה המשך תער\"ב ח\"ב ע' א'מא. ועוד)."],["108","108","מלאכי ג, יח. חגיגה ט, ב. תניא פט\"ו."],["109","109","כדלעיל הערה 21."],["110","110","נח ח, כא."],["111","111","ולהעיר גם ששנת השמיטה היא הכנה למצות הקהל (בסיום שנת השמיטה) „מקץ שבע שנים במועד שנת השמיטה . . הקהל את העם האנשים והנשים והטף . . למען ישמעו ולמען ילמדו גו'\" (וילך לא, י ואילך), שזהו\"ע החינוך (חינוך עצמו וחינוך הנשים והטף). וראה פירוש רבינו מיוחס (ירושלים, תשכ\"ח) עה\"פ וילך שם (בהמשך לדרשת רז\"ל (חגיגה ג, א. פרש\"י וילך שם) „טף למה באין כדי ליתן שכר למביאיהן\"): מכאן שמצוה להוליך אדם את בנו לבית הספר ולבית הכנסת כדי להתחנך בכך. וראה תוד\"ה כדי — חגיגה שם. מס' סופרים פי\"ח ה\"ז (ובכסא רחמים שם). וראה לקו\"ש חי\"ד ע' 133."],["112","112","ולהעיר שענין השמיטה — „סאַבאַטיקל\" בלע\"ז — ישנה גם במנהג האומות, בכדי להוסיף בעניני חכמה ומדע וכיו\"ב."]]],[1300251338,"טו. ויה\"ר אַז דורך דעם וואָס מ'וועט אַרויסגיין אין „מלחמת בית דוד\" להפיץ המעינות חוצה, זאָל און וועט זיכער מקויים ווערן הבטחת רבותינו נשיאינו (דער בעל יום ההולדת ובנו ממלא מקומו, כ\"ק מו\"ח אדמו\"ר), אַז מ'וועט מנצח זיין במלחמה זו, און ברענגען דוד מלכא משיחא, ותיכף ומיד, נאָך בשנת השמיטה זו, ועאכו\"כ אַז בשנת הקהל הבע\"ל וועט מען זיין אין ארצנו הקדושה, און דאָרט מקיים זיין מצות „הקהל את העם האנשים והנשים והטף גו' למען ישמעו ולמען ילמדו ויראו את ה' אלקיכם גו'\"113,\nובמהרה בימינו ממש.",[["113","113","וילך לא, יב."]]],[1300251339,"א. בשבת זו הויבט זיך אָן דער כנס השלוחים. ובקשר עם זה האט מען ארויסגעגעבן די שיחה¹ וועגן דעם תפקיד פון א שליח, (גם) ווי מרומז אין דעם וואס משיח איז די גימטריא פון „שליח״ בצירוף עשר, אז א שליח דארף אריינעמען און נוצן זיינע עשר כחות, און דורך דעם מגלה זיין בחי׳ משיח (יחידה) שבו, ועי״ז — מגלה זיין יחידה הכללית, משיח².\nויש לקשר זה (דעם כנס און די שיחה) מיט דעם זוהר פון פרשתנו לויט דער ביאור פון טאטן אויפן זוהר:\nאין זוהר³ שטייט: „זכאין אינון מארי־הון דתשובה דהא בשעתא חדא ביומא חדא ברגעי⁴ חדא קריבין לגבי קב״ה״.\nפרעגט דער טאטע אין זיינע הערות אויפן זוהר⁵: „לכאורה הוא שלא על הסדר, כי הול״ל יומא שעתא רגע, שכ״א יותר רבותא מחבירו, בדרך לא זו אף זו⁶. גם אם די ברגע חדא לאיזה צורך אמר שעתא ויומא״? און ער פאר־ענטפערט: „י״ל יש ג׳ בחי׳ תשובה המגיעים במל׳ בז״א בבינה כמ״ש בלקו״ת בד״ה מה טובו⁷ ע״ש [אן עס איז דא א דרגא אין תשובה וואס ענינה איז „סור מרע״⁸, וואס זי איז מגיעה במלכות; א העכערע דרגא אין תשובה וואס איר ענין איז „ועשה טוב״⁸ — ומגיעה בז״א: און נאך א העכערע תשובה וואס ענינה איז „בקש שלום״⁸, לימוד התורה — ומגיעה בבינה]. זהו בשעתא במל׳ הנק׳ שעה, ביומא בז״א הנק׳ יום, ברגע בבינה״.\nויש לומר (— מ׳זוכט דאך מעלות אין דעם ענין פון „שליח״):\n„שליח״ איז ר״ת — „שעתא״, „לימוד״ (תשובה הג׳ בבינה, „בקש שלום״, לימוד התורה), „יומא״, „חדא״.\nוהפירוש:\nנתבאר לעיל⁹ אז יעדער איד איז א שליח פון הקב״ה, וועלכן דער אויבער־שטער האט אראפגעשיקט אלס נשמה בגוף דא למטה בעולם הזה בכדי ער זאל מקיים זיין תומ״צ און פארשפרייטן אלקות בעולם. וואס מזה מובן, אז „שליח״ (בשלימותו) איז כולל אין זיך אלע דרגות בעבודת ה׳ דא למטה, אלע דרגות בעבודת התשובה — וואס דאס (עבודת התשובה) איז תכלית ירידת הנשמה בגוף (כמבואר בלקו״ת שם) בשליחותו של הקב״ה — די דריי דרגות אין תשובה:\nתשובה ב„שעתא״ — „סור מרע״ (שמגיע במלכות): תשובה פארבונדן",[["1","1","מליל שמחת תורה שנה זו — נדפסה גם בקונטרס השליחות (הוצאה שני׳, תשמ״ו — ע׳ 11 ואילך), ובלקו״ש חכ״ט ע׳ 358 ואילך."],["2","2","נסמן בשיחה הנ״ל הערה 27."],["3","3","פרשתנו קכט, סע״א ואילך."],["4","4","כ״ה בכמה דפוסי זוהר „ברגע״ (וכן הועתק בלקוטי לוי״צ דלקמן). אבל בכו״כ דפוסי הזוהר (וכן נעתק באור יקר, באור החמה, ובכ״מ) „ברגעא״ — ועפ״ז מתאים ל„חדא״ שלאחריו ול„שעתא״ וכו׳ שלפניו."],["5","5","לקוטי לוי״צ לזח״א ע׳ פא."],["6","6","הביאור בסדר זה בפשטות הענינים — נתבאו בלקו״ש ח״כ ע׳ 86 ואילך."],["7","7","בלק עג, ב ואילך."],["8","8","ל׳ הכתוב — תהלים לד, טו."],["9","9","בלקו״ש חכ״ט שם."]]],[1300251340,"מיט „לימוד (התורה)״, בחי׳ „בקש שלום״¹⁰ (שמגיעה בבינה): תשובה ב„יו־מא״, „עשה טוב״ (שמגיעה בז״א). און אלע ג׳ תשובות זיינען באופן פון „חדא״¹¹ — (דער חי״ת און) חותם („פעטשאטקע״) פון דעם גאנצן וואָרט „שליח״ (וואס דאס איז מדגיש אז אלע (ג׳) אותיות שלפנ״ז זיינען נחתמין מיט דעם „חדא״).\nב. ובפרטיות יותר — בנוגע צו די שלוחים פון נשיא דורנו, דעם רבי״ן דעם שווער: זייער שליחות מיוחדת (נוסף צו דער שליחות הכללית פון קיום התומ״צ והפצת היהדות) באשטייט פון הפצת המעינות חוצה, וואס דאס איז כולל, כמובן, „חוצה״ שבתורה, נגלה, הגוף¹² דתורה, מ׳זאל מפיץ זיין די מעינות התורה (פנימיות התורה) אין „חוצה״ שבתורה (נגלה דתורה).\nדאס הייסט: בחי׳ תשובה פארבונדן מיט לימוד התורה, „בקש שלום״ (כנגד דער למ״ד פון תיבת „שליח״) טיילט זיך בפרטיות (בא די שלוחים פון נשיא דורנו) אויף לימוד והפצת ויחוד פני־מיות התורה ונגלה דתורה, והפצת המצות בחוצה דעולם.\nוואס דער ענין איז מרומז בתיבת מ״ם: עס שטייט אין גמרא¹³ אז, „מ״ם פתוחה מ״ם סתומה״ באווייזן אויף „מאמר פתות מאמר סתום״. טייטשן מפרשים¹⁴, אז „מאמר פתוח״ גייט אויף נגלה דתורה און „מאמר סתום״ גייט אויף סתים דתורה.\nויש לומר אז דאס איז דער ענין וואס פון „שליח״ ר״ת „שעתא, לימוד, יומא, חדא״ ווערט „משיח״, ד.ה. אז פון דעם למ״ד פון „שליח״ (בצירוף עשר כחות שלו) ווערט דעם מ״ם פון „משיח״: פון דעם למ״ד ר״ת „לימוד״ ווערט (דורך עבודת האדם בלימוד התורה) א מ״ם, לימוד התורה אין אן אופן פון יחוד¹⁵ נגלה דתורה (מאמר פתוח) ופנימיות התורה (מאמר סתום).\nאון דער קשר מיט משיח: דורך יפוצו מעינותיך חוצה (כולל — הפצת פנימיות התורה בנגלה דתורה) איז „אתי מר״ דא מלכא משיחא¹⁶, וואס ר״ת של שמו — משיח איז מיט א מ״ם (וואס ווייזט אויף הפצת פנימיות התורה בנגלה דתורה), און פון דעם מ״ם פתוחה (בסוף התיבה)¹⁷ פון גלות ווערט א מ״ם סתומה (באמצע התיבה) „לסרבה המשרה״¹⁸ בגאולה העתידה¹⁹.",[["10","10","ועפ״ז י״ל טעם שבחי׳ תשובה הג׳ (בקש שלום) מרומזת בלמ״ד (בתיבת „שליח״) ר״ת לימוד התורה, ולא בתי״ו ר״ת תורה סתם — כי תורה כולל גם מצות עשה ומצות לא תעשה, סו״מ ועש״ט, שהם כבר מרומזים בהשי״ן (שעתא) והיו״ד (יומא), והכוונה כאן היא לרמז על תשובה הג׳, „בקש שלום״, שזה מורה דוקא על „לימוד התורה״ ר״ת למ״ד."],["11","11","כי תשובה היא מצוה חדא (לגבי כל התומ״צ) — „תשובה ו(עי״ז כל ה)מעשים טובים״ (אבות פ״ד מי״א. ועוד. וראה לקו״ת מטות פב, א. שמע״צ פה, א. שה״ש יז, ג)."],["12","12","זוהר בהעלותך קנב, א."],["13","13","שבת קד, א. וראה של״ה בית הגדול בסופו (לז, ב ואילך)."],["14","14","רש״י שם. וראה ד״ה ביום השני תרכ״ט פ״ג. ד״ה מאימתי תרמ״ב (קה״ת תשכ״ה)."],["15","15","דשניהם מרומזים באות (אחת) מ (שבאה אחרי הלמ״ד — ראה שבת שם)."],["16","16","אגה״ק דהבעש״ט — נדפס בכש״ט (הוצאת קה״ת) בתחלתו. ובכ״מ."],["17","17","נחמי׳ ב, יג."],["18","18","ישעי׳ ט, ו."],["19","19","ראה לקו״ת במדבר ב, ב. אוה״ת מקץ (כרך ה׳) תתקעד, א ואילך. נ״ד ע׳ קפג ואילך. ובכ״מ. וראה ס׳ הערכים־חב״ד מערכת אותיות אות מ״ם (ב) ס״ע רב ואילך. וש״נ."]]],[1300251341,"ויומתק ע״פ המדובר לעיל²⁰ פון פס״ד הרמב״ם²¹ אז ביאת המשיח („מיד הן נגאלין״) איז תלוי אין „ישראל עושין תשובה״. בכל ג׳ דרגות הנ״ל בתשובה (וואס זיינען מרומז אין דעם וואָרט „שליח״), כולל תשובה פון „בקש שלום״, לימוד התורה, ובפרט באופן פון מ״ם (יפוצו מעינותיך חוצה). וכידוע אויך אז ענינו פון משיח איז פארבונדן במיוחד מיט תשובה²² — משיח אתא לאתבא\nצדיקיא בתיובתא²³.\nוהנה, די כוונה פון כל האמור לעיל איז מעשה בפועל — אז דאס זאל צו־געבן עידוד ובהנתינת כח וכו׳ בקיום השליחות פון אלע וכאו״א מהשלוחים. וואס דערפאר איז מובן, אז אע״פ וואס האמור לעיל איז ע״ד הרמז ובדרך אפשר — אבער וויבאלד אז דערפון קומט ארויס א עידוד ונתינת כח אין קיום השליחות פון די שלוחים, איז דאס כדאי און אויסגעהאלטן און א ר״ת קיים וכו׳ וטוב.",[["20","20","בשיחה הנ״ל סעיף ו׳ (לקו״ש שם ע׳ 363־4)."],["21","21","הל׳ תשובה פ״ז ה״ה."],["22","22","להעיר אשר תשו״ע (שלימותה) הוא לימוד התורה (תניא ח״ג ספ״ח ואילך)."],["23","23","לקו״ת שמע״צ צב, ב. שה״ש מה, א. נ, סע״ב (וראה שם ר״ה נח, ד. האזינו עה, סע״ב). וראה זח״ג קנג, ב."]]],[1300251342,"משיחת ש״פ חיי שרה, מבה״ח כסלו ה׳תשמ״ז — יום התחלת כנס השלוחים שי׳ הרביעי בארצות הברית —\nא. דעם שבת הויבט זיך אָן דער כנס השלוחים שי׳ (פון ארצות הברית) — די שלוחים און שלוחי שלוחים פון כ״ק מו״ח אדמו״ר נשיא דורנו.\nוואס אין דעם ענין השליחות איז בא־שטאנען איינער פון די חידושים פון כ״ק מו״ח אדמו״ר נשיא דורנו: אע״פ וואס אין תורה רעדט זיך וועגן ענין השליחות (אויך בשייכות צו כללות עבודת ה׳, כדלקמן), און מ׳געפינט דעם ענין השליחות בדורות שלפני זה אז א גדול בישראל האט איינעם געשיקט מיט א שליחות מסויימת בעניני תומ״צ¹ — איז דעם צוגעקומען א חידוש מיוחד דורך כ״ק מו״ח אדמו״ר, וואס ער האט אויפגעטאן (און אנגעזאגט) אז אלע אידן פון דעם דור זיינען שלוחים אויף צו טאן אין הפצת התורה והיהדות והפצת המעינות חוצה. ביז אז ער האט ממנה געווען שלוחים און זיי געשיקט צו פאר־שידענע ערטער מיט עניני שליחות אין הפצת התורה והיהדות און הפצת המעינות חוצה.\nב. וביאור הענין:\nדי ערשטע שליחות — פון וועלכער עס נעמען זיך אלע עניני ואופני שליחות (אויך געשיקט פון בני אדם) — איז די שליחות וואס דער אויבערשטער גיט יעדער מענטשן אראפשיקנדיק אים אלס א נשמה בגוף² דא למטה אין עולם הזה הגשמי בכדי ער זאל מאכן א דירה לו יתברך בתחתונים³, דורך דעם וואס ער איז משמש את קונו⁴ ע״י קיום התורה ומצוותי׳, און איז אויך משפיע און פאר־שפרייט תומ״צ בא אנדערע, און איז מפרסם אלקות בחלקו בעולם, ביז בכל מקום וואו ער קען דערגרייכן⁵.\nכמבואר בלקוטי תורה⁶, אז יעדער איד איז שלוחו של אדם העליון⁷, שלוחו של אדם כמותו⁸, „כמותו⁹ דהמשלח ממש״¹⁰.\nאון די שליחות ווערט דורכגעפירט (ונתגלה) במיוחד דורך קיום המצוות —",[["1","1","ראה ירושלמי חגיגה פ״א ה״ח. וכהנה רבות."],["2","2","ושליחות זו — היא בכל הדרגות שלמעלה, שענין השליחות שלמעלה הוא „מה שנמשך הארה ע״י אמצעות איזה בחינה״ (לקו״ת ויקרא א, ג), וענין זה הוא בכל הדרגות שלמעלה, עד לדרגות הכי נעלות, כי כל המשכה והשפעה ואור כו׳ מחוץ לעצמותו ית׳ היא המשכה „ע״י אמצעות איזה בחינה״. וכן הוא גם בנוגע לירידת הנשמה, שמושרשת בעצמותו ית׳, „טהורה היא״, וירדה מדרגא לדרגא (ענין השליחות), עד למטה בעוה״ז."],["3","3","ראה תנחומא בחוקותי ג. שם נשא טז. במדב״ר פי״ג, ו. תניא פל״ו."],["4","4","ראה משנה וברייתא סוף קידושין."],["5","5","כמו שהי׳ בשליחות אברהם אבינו — „לך לך מארצך וממולדתך ומבית אביך גו׳״ (ר״פ לך), „והי׳ (רמב״ם הל׳ ע״ז ספ״א) מהלך וקורא כו׳ מעיר לעיר וממלכה לממלכה כו׳״, „ויקרא שם בשם ה׳ א־ל עולם״ (וירא כא, לג), וכפרש״י בפרשתנו (כד, ז) „כשלקחני מבית אבי ה׳ אלקי השמים ולא אלקי הארץ, שלא היו באי עולם מכירים בו ושמו לא הי׳ רגיל בארץ״, אבל „עכשיו הוא אלקי השמים ואלקי הארץ שהרגלתיו בפי הבריות״."],["6","6","ויקרא א, ג."],["7","7","ראה לקמן הערה 28 מתורת הבעש״ט ואדה״ז."],["8","8","משנה ברכות לד, ב. קידושין מא, ב. וש״נ."],["9","9","לקו״ת שם. וכ״ה (הלשון: כמותו ממש) בתשובות הריב״ש סרכ״ח. ועוד."],["10","10","וכמאחז״ל (קידושין שם) „מה אתם בני ברית אף שלוחכם בני ברית״."]]],[1300251343,"כדאיתא במדרש¹¹, „היו מכבדין את המצות שהן שלוחי, ושלוחו של אדם כמותו״. ד.ה. אז מצוות זיינען „שלוחים״ פון דעם אויבערשטן, דורך וועלכע עס ווערט (מצוה מלשון) צוותא וחיבור¹² צווישן דעם אדם המקיים את המצוה מיטן אויבערשטן¹³.\nוואס דער ענין (השליחות) האט זיך בעיקר אויפגעטאן בא מתן תורה — ווען אידן זיינען געווארן שלוחים של הקב״ה — „ואתם תהיו לי ממלכת כהנים״¹⁴, שלוחי דרחמנא¹⁵ — צו מאכן א דירה לו יתברך בתחתונים, דורך קיום התומ״צ, און משפיע זיין בזה אויף אנדערע, ביז אויך אויף אומות העולם, כפס״ד הרמב״ם¹⁶ „צוה משה רבינו מפי הגבורה לכוף את כל באי העולם לקבל מצות שנצטוו בני נח״.\nג. אין דעם גופא (די שליחות פון יעדער איד אין כללות תומ״צ) האט מען אבער אויך דעם ציווי „בכל יום יהיו בעיניך חדשים״¹⁷. און וויבאלד אז תורת אמת מאנט עס, איז מובן אז דער אמת איז אזוי, אז בכל יום ווערט טאקע א חידוש אמיתי אין תומ״צ, דערפאר קען מען מאנען אז מ׳זאל דאס מקיים זיין בכל יום ווי א דבר חדש (אדער עכ״פ „כחדשים״¹⁸ (מיט א כ״ף הדמיון) — אויב ער האלט נאך ניט בא שלימות ההתבוננות וואס ברענגט דעם רגש ועשי׳ בפועל אז דאס איז „חדשים״ ממש)¹⁹. ויומתק זה ע״פ תורת הבעש״ט²⁰ אז התהוות העולם איז בכל רגע ורגע מחדש²¹. וע״פ המבואר באגה״ק²² אז בכל שנה „יורד אור חדש עליון יותר שלא הי׳ מאיר עדיין מימי עולם אור עליון כזה״²³.\nד.ה. אז קבלת וקיום שליחותו של הקב״ה בתומ״צ ע״י כאו״א מישראל",[["11","11","תנחומא ויגש וא״ו."],["12","12","לקו״ת בחוקותי מה, ג. וראה תניא מהדו״ק (קה״ת, תשמ״ב) ספמ״ט."],["13","13","ועפ״ז מובן הטעם שמצוות הן „שלוחי״, כי בקיום המצוות פועלים צוותא וחיבור בין הקב״ה וישראל, ודבר המחבר צ״ל בדוגמא להדברים שהוא מחבר (הקב״ה וישראל), כי בלאו הכי אין זה חיבור אמיתי (ואדרבה — הפסק). וזהו ע״י שהמצוות הן „שלוחי״, ששלוחו של אדם כמותו, דומה להמשלח (הקב״ה), ודומה לבני ישראל שהם שלוחיו של הקב״ה כמותו. וראה לקו״ת יוהכ״פ סח, ב. אוה״ת וישלח רמח, ב."],["14","14","יתרו יט, ו."],["15","15","ראה קידושין כג, ב ובתוס׳ שם. וש״נ."],["16","16","הל׳ מלכים פ״ח ה״י. וראה בארוכה לקו״ש חכ״ו ע׳ 132 ואילך."],["17","17","פרש״י עה״פ תבוא כו, טז. וראה פרש״י יתרו יט, א. עקב יא, יג."],["18","18","ראה ספרי ופרש״י ואתחנן ו, ו."],["19","19","ועפ״ז מתורצת השאלה: איך שייך לתבוע שתומ״צ תהיינה בכל יום „חדשים״ ממש אם לא הרגיש החידוש בדבר? די״ל שהוא ע״ד המבואר בנוגע להציווי על אהבת ה׳, כי איך שייך ציווי על רגש שבלב? אלא הציווי הוא על ההתבוננות בדברים המביאים לידי אהבה, וזה בהכרח מביא לידי אהבה בפועל (ראה ס׳ הערכים חב״ד (כרך א) ערך אהבת ה׳ (ע׳ רסז ואילך). וש״נ). כן י״ל בנדו״ד: הציווי הוא על ההתבוננות בדברים המביאים לידי רגש שתומ״צ הן בכל יום — „חדשים״ (או עכ״פ „כחדשים״). ומהענינים של התבוננות המביאים לרגש זה הן — תורת הבעש״ט ואדה״ז דלקמן בפנים."],["20","20","שעהיוה״א פ״א."],["21","21","ראה גם לקו״ש חכ״ט ע׳ 285 הערה 52."],["22","22","סי״ד."],["23","23","שזהו חידוש על חידוש: חידוש הראשון — „אור חדש״, חידוש השני — עליון יותר שלא הי׳ מאיר עדיין מימי עולם אור עליון כזה״. *) כי „אור חדש״ פירושו — „שלא הי׳ מאיר עדיין מימי עולם״, אבל אפ״ל עליון כמותו, או גם תחתון ממנו (להעיר ממקדש הב׳ לגבי הא׳)."]]],[1300251344,"דארף זיין בכל יום ויום באופן פון „חדשים״ ממש (ובפרט אז אין דעם ווערט אויפגעטאן א חידוש בפועל בכל יום ויום). ס׳איז ניט מספיק קבלת וקיום שליחותו של הקב״ה ע״י בני ישראל טויזנטער יארן צוריק בא מתן תורה, אדער אין די יארן שלאחרי זה, נאר עס דארף שטענדיק זיין „חדשים״. ואדרבה: „מעלין בקודש״²⁴ — עס דארף אין דעם שטענדיק צוקומען אן עילוי נעלה יותר.\nד. בכדי צו מאכן לייכטער און בכדי ארויסצוברענגען מער בגלוי דעם „חידוש״ (חדשים) אין דער שליחות פון יעדער אידן אלס שלוחו של הקב״ה — האט דער אויבערשטער געמאכט אז מזמן לזמן ומדור לדור זאלן צוקומען נייע ענינים אין וועלכע מ׳זעט בגלוי (לעיני בשר) דעם חידוש אין דער שליחות פון א אידן (וואס דעמולט איז לייכטער בא זיך פועל׳ן דעם „חדשים״ בקיום השליחות); און דערצו האט דער אויבערשטער געגעבן אידן א נשיא בכל דור ודור²⁵, און הוי׳ „גלה סודו אל עבדיו הנביאים״²⁶, וואס דער נשיא הדור גיט כחות לכל אנשי הדור²⁷ צו אויס־פירן שליחותם בקיום התומ״צ און מאכן די וועלט פאר א דירה לו יתברך, ובמיוחד — אין דער שליחות חדשה וואס קומט צו בכל דור ודור.\nאון אין דעם גופא איז צוגעקומען א חידוש דורך דעם נשיא פון אונזער דור — כ״ק מו״ח אדמו״ר — וואס ער האט אויפגעטאן א חידוש וגילוי מיוחד ונעלה און אריינגעגעבן א כח חדש אין כללות ענין השליחות פון יעדער אידן אלס שליח של הקב״ה²⁸ — ער האט אויפגע־טאן אז דאס זאל אראפקומען בגלוי ובפועל ממש אלס א יסוד ודרך בעבודת ה׳ לכאו״א מישראל²⁹,\nדורך דעם וואס ער האט אנגעזאגט (און געגעבן כח) אז די שליחות פון יעדער אידן בדור זה איז צו פאר־שפרייטן תורה ויהדות און הפצת המעינות חוצה. און האט געזאגט אז דערצו דארף מען אוועקגיין ממקומו",[["24","24","ברכות כח, א. וש״נ."],["25","25","ראה יומא (לח, סע״ב. הובא בתניא פ״א (ה, ב)): עמד (הקב״ה) ושתלן בכל דור ודור."],["26","26","עמוס ג, ז."],["27","27","ראה גם תניא פ״ב. ועוד."],["28","28","נוסף על החידוש שבזה ע״י הבעש״ט — וכתורתו הידועה (כש״ט הוצאת קה״ת הוספות ס״ג) עה״פ (תבוא כו, ב) „והלכת אל המקום אשר יבחר ה׳ אלקיך לשכן שמו שם״, „אז א איד גייט אין אן ארט, איז דאס ניט וואס ער גייט נאר מ׳פירט עם כו׳, אז ער קומט אין אן ארט איז די כוונה — „לשכן שמו שם״ — לפרסם אלקות בעולם״ (וראה כש״ט שם סקל״ז. מאמרי אדה״ז הקצרים ע׳ רנו; ענינים ע׳ קלא). ולהעיר מתורת אדה״ז („היום יום״ י׳ תמוז. אגרות־קודש אדמו״ר מהוריי״צ ח״ה ע׳ קג. קי׳) — „אז א איד קומט אין א ארט, איז עס צוליב א כוונה, טאן א מצוה וכו׳, א איד איז א שליח של מעלה, א שליח וואו ער איז, איז ער דער כח המשלח״."],["29","29","וי״ל שהוא ע״ד המבואר (ראה לקו״ש ח״ז ע׳ 64. ח״ח ע׳ 354. ליקוט פירושים כו׳ לשעהיוה״א פ״א) ב„פי׳ הבעש״ט״ (שעהיוה״א פ״א) בענין „לעולם ה׳ דברך נצב בשמים״ (תהלים קיט, פט), שההתהוות היא בכל רגע ורגע מחדש — אף שנאמר כן במדרש תהלים (עה״פ. הובא בלקו״ת אחרי כה, ג. וראה הנסמן בליקוט פירושים שם ע׳ נג) — כי הבעש״ט פירש, האט עס פאנאנדערגעשפרייט, ועשה ופעל שהלימוד במדרש תהלים יהי׳ יסוד ודרך בעבודת ה׳ בתומ״צ דכאו״א מישראל במעשה בפועל. ועד״ז הוא חידוש כ״ק מו״ח אדמו״ר בענין השליחות: אף שכללות ענין השליחות (בשייכות לעבודת ה׳ בכלל) נאמר במדרש תנחומא, „היו מכבדין את המצוות שהן שלוחי״, ובלקו״ת — שכל איש ישראל הוא שליח של אדם העליון, וענין זה הי׳ כבר במתן תורה וכו׳, ובמיוחד ע״י הבעש״ט המגיד ואדה״ז ונשיאי חב״ד ממלאי מקומו — נתחדש ע״י כ״ק מו״ח אדמו״ר שמ״ש בספרים הנ״ל ע״ד ענין השליחות יבוא לידי פועל בתור יסוד ודרך בעבודת כאו״א."]]],[1300251345,"(כולל — ממדריגתו) און קומען בכל המדינות ובכל המקומות שבעולם שיכול להגיע שם, און דארטן טאן די שליחות פון הפצת התורה והיהדות והפצת המעינות חוצה.\nביז אז דאס האט זיך אויסגעדריקט בגלוי ממש דורך דעם וואס ער האט צו זיך אריינגערופן מענטשן און זיי ממנה געווען אלס שלוחים מיוחדים אויף מקיים זיין פארשידענע עניני שליחות בהפצת התורה והיהדות והפצת המעינות חוצה (אבער אויך די וועלכע ער האט ניט אריינגערופן און ניט גע־שיקט בשליחות מסויימת — האבן זיי די שליחות בעסקים הפרטיים שלהם, כאו״א לפי ענינו).\nאנהויבנדיק ווי ס׳איז געווען נאך במדינה ההיא (מאחורי מסך הברזל) — די ערשטע שלוחים וואס ער האט אויס־געקליבן, צוזאמען מיט א כריתת ברית וכו׳³⁰ (ווי ס׳איז איצטער שוין ידוע);\nדערנאך ארויסגייענדיק ממדינה ההיא, למקומות וואו דאס האט שוין גע־קענט זיין מיט א גרעסערן פרסום — האט ער ארויסגעשיקט שלוחים בפרסום גדול יותר ובהתרחבות גדולה יותר;\nביז אנקומענדיק במדינה זו, ארצות הברית, בעשר שנים האחרונות שלו בחיים חיותו בעלמא דין — וואו מ׳האט אויך דעם סיוע פון דער ממשלה ואנשי המדינה (עאכו״כ — אז ס׳איז ניטא קיין התנגדות, ווי דאס איז געווען במדינה ההיא) — האט זיך דער ענין השליחות פאנאנדערגעשפרייט באופן הכי רחב, דורך דעם וואס ער האט געשיקט שלוחים לכל קצוי תבל, כולל דערנאך — דורך תלמידיו ותלמידי תלמידיו, והולך ומתפשט באורך ברוחב ובעומק³¹.\nווי מ׳זעט איצטער דעם מצב בפועל ובגלוי לעיני בשר, אז אין א ריבוי מקומות בעולם, גרויסע שטעט און קליינע שטעטלעך, ביז אפילו אין פינות רחוקות שבעולם, אין אוסטראליא, און אפריקא וכיו״ב, געפינען זיך די שלוחים וואס כל התעסקותם איז בשליחותו פון דעם משלח, בשליחותו של הקב״ה — אין הפצת התורה והיהדות והפצת המעינות חוצה.\nאון אויך די אידן בדור זה וואס זיי־נען (בגשמיות) ערגעץ ניט געפארן, האבן זיי אויך די שליחות מיוחדת צו טאן אין הפצת התורה והיהדות ומעינות חוצה (אנהויבנדיק בא זיך אליין, און אויך) דורך אוועקגיין ממקומם ומד־ריגתם הרוחנית, און מפיץ זיין תורה כו׳.\nה. און אין דעם גופא איז צוגע־קומען (בשנים האחרונות) נאך א שלב וחידוש — אז בכל שנה ושנה מאכט מען (בכמה מקומות, בארץ הקודש, ארצה״ב, ועוד) א „כנס השלוחים״, וואו אלע שלוחים (פון א געוויסער מדינה אדער מדינות) קלייבן זיך צוזאמען על מנת עס זאל זיין „אז נדברו גו׳״³², „איש את רעהו יעזרו ולאחיו יאמר חזק״³³, וואס דעמולט קומט צו אין דעם חיזוק הדבר, כמבואר בקונטרס החלצו³⁴ די מעלה פון טאן אלע ענינים בעבודת ה׳ ברבים, ווייל „כשמדברים יחד ממציא כל א׳ עצות לזה כו׳ ועושים הסכם בקבלה על",[["30","30","ס׳ השיחות תש״ב ע׳ 154. שיחת י״ג תמוז תרצ״ב."],["31","31","להעיר מש׳ היחוד (לאדהאמ״צ) בתחלתו."],["32","32","מלאכי ג, טז. הובא ברמב״ם סוף הל׳ טומאת צרעת (נת׳ בשיחת יום ב׳ דראש השנה (תשמ״ז))."],["33","33","ישעי׳ מא, ו."],["34","34","תרנ״ט — פ״י (סה״מ תרנ״ט ע׳ סא)."]]],[1300251346,"להבא כו׳, וההסכם אשר עושים שנים או רבים יש לזה חיזוק הרבה יותר מההסכם שעושה בפ״ע:\nאלע שלוחים האבן דאך פארשידענע פעולות משותפות, אין וועלכע יעדערער קען זיך אפלערנען און בא־קומען אן עצה ועידוד וחיזוק פון א צווייטן שליח וואס האט מצליח געווען בשטח מסויים.\nנוסף לזה האט א כנס השלוחים מעלת וכח הציבור, וואס גיט א כח מיוחד צו יעדערן פון די שלוחים בשליחותו הפרטית במקומו בפרט, און צו אלע שלוחים צוזאמען אלס א כלל — צו ממשיך זיין בעבודתם בהפצת התורה והיהדות והפצת המעינות חוצה, כולל גם — פארשפרייטן צדק ויושר אויך בא אוה״ע דורך קיום ז׳ מצוות בני נח, און זיך צונויפרעדן ווי מ׳קען אין דעם אלעם מוסיף ומרחיב זיין בכל מיני אופנים. וכדלקמן.\nו. אין דעם חידוש (פון נשיא דורנו) בענין השליחות גופא — איז דא נאך א חידוש אין אופן פעולת השלוחים לגבי דעם אופן העסקנות פון א טייל פון אנ־דערע עסקנים ציבוריים:\nבשעת מ׳קומט אין אן ארט, א שטאט, מיט א געוויסע שליחות אין עסקנות — קען מען דערביי גיין אין צוויי אופנים:\nדער סדר בא כו״כ אנדערע עסקנים איז, אז קומענדיק אין א שטאט האלט מען לכל לראש א פייערדיקע דרשה וועגן דעם מצב פון כלל ישראל און מצב העולם, ווי די וועלט שטייט אין סכנה, און מ׳דארף איר ראטעווען, און דערפאר דארף מען מאכן אסיפות און באשטימען וועידות און קאמיטעטן וכיו״ב, און צום סוף פירט אויס דער עסקן — אשר לכן דארף מען העלפן דעם מוסד פרטי, די מלמדים ומלמדות מסויימים, און די תלמידים ותלמידות מסויימים וכדומה.\nד.ה. אז צום אלעם ערשטן רעדט מען וועגן דעם ענין מצד כלל ישראל און כל העולם, און דערפון קומט מען צו עזר פאר דעם מוסד פרטי.\nדער אויפטו פון שלוחי נשיא דורנו איז — אז מ׳גייט מיט פונקט א פאר־קערטן סדר: היות אז נשיא דורנו האט אים געגעבן א שליחות אין א מקום מסויים, מיט א שליחות מסויימת (וברוב הפעמים — אים גלייך אנגעזאגט אין וואס עס באשטייט די שליחות) — איז בשעת ער קומט אין דעם מקום מסויים, הויבט ער אָן לכל לראש רעדן מיט די תושבי המקום אז ער איז געקו־מען צו זיי עצמם, צו העלפן דורך חיזוק נאכמער אין אידישקייט און צדק ויושר ביי זיי און זייערע פרויען און קינדער און פריינט, און פאר אלע תושבי המקום, אויך די ניט־אידן. אשר לכן, בעט ער זיי און זיי דארפן אים ארויס־העלפן צו אויפשטעלן אין זייער ארט א מוסד (א „בית חינוך״ וכיו״ב), און זיי אליין זאלן ווערן חברים אין דעם מוסד, און ארויסהעלפן מיט עזר גשמי, בגופו ובממונו, וכו׳.\nאון ערשט דערנאך און בהוספה על זה — גיט צו נשיא דורנו — אז דורך דער הוספה אין הפצת היהדות והצדק והיושר במקום פרטי זה, העלפט מען כלל ישראל, ביז אז מ׳ברענגט דורך דעם די גאולה פאר כלל ישראל און פאר כל העולם כולו, כולל — פאר שכינתא בגלותא³⁵;",[["35","35","ראה מגילה כט, א. זהר ח״א קכ, ב. ח״ג ד, ב. צ, ב. ועוד."]]],[1300251347,"אבער צום אלעם ערשטן טוט דער שליח — וכל מעינו בו³⁶ — אין זיין שליחות הפרטית אין דעם מקום מסויים און מיט די תושבי המקום מסויימים, דורך פאראינטערעסירן זיך מיט אן אמת אין דעם מצב הפרטי פון די תושבי המקום, אנשים נשים וטף, און אויסגע־פינען ווי מ׳קען זיי ארויסהעלפן אין אלע זייערע ענינים, און פארשפרייטן אידישקייט און חסידות, און צדק ויושר בכלל.\nנאר בהוספה על זה ווייסט ער אויך שכרו בצדו, און דאס גיט אים נאך מער געשמאק אין דער עבודה — אז זיינע פעולות פרטיות אין דעם מקום מסויים, העלפן ארויס כלל ישראל און ברענגען די גאולה [כפס״ד הרמב״ם³⁷, אז דורך א „מצוה אחת כו׳ הכריע את עצמו ואת כל העולם כולו לכף זכות וגרם לו ולהם תשועה והצלה״]. אבער דאס טאר ניט מבלבל זיין צום אויספירן די שליחות פרטית אין דעם מקום מסויים מיט די תושבי המקום.\nאון בשעת מ׳גייט מיט אָט דעם צו־גאנג איז מען מצליח שלא בערך מער ווי מיט דעם ערשטן צוגאנג, כמובן בפשטות וכנראה במוחש.\nואדרבה: ווי טוט מען אויף פאר כלל ישראל און די גאולה — דוקא דורך דעם וואס יעדער שליח פארט צו זיין „פינה רחוקה״, זיין „קליין שטעטעלע״, און ליגט אינגאנצן אין די פעולות פון הפצת היהדות והצדק והיושר צווישן די געציילטע תושבים פון זיין קליין שטעטעל. וואַרום פון אלע יחידים בישראל שטעלט זיך צוזאמען כלל ישראל, און פון די אלע פינות רחוקות און קליינע שטעטלעך — שטעלט זיך צוזאמען די גאנצע וועלט!\nאויב ער וועט טראכטן נאר וועגן כלל ישראל און וועגן דער גאולה, און דורך דעם וועט פעלן אין זיין שימת לב צר־צושטעלן די צרכים הפרטיים (בעניני יהדות וכו׳) פון תושבי המקום — קען מען ניט מציל זיין כלל ישראל און די גאנצע וועלט, וואַרום כלל ישראל בא־שטייט פון יחידים, און די גאנצע וועלט באשטייט פון א ריבוי קליינע ווינקלעך!\nז. און דער ביאור בזה איז פאר־שטאנדיק אויך פון כללות השליחות דירידת הנשמה בגוף לשמש את קונו בתומ״צ:\nדער אויבערשטער האט באשאפן א וועלט וואס באשטייט פון א ריבוי פרטים ופרטי פרטים³⁸. און יעדער פרט ופרט איז ניט באשאפן געווארן „לבטלה״ ח״ו, נאר יעדער פרט האט אין זיך א חידוש וואס קיין אנדער פרט פארמאגט ניט און קען ניט פארבייטן, און „כל³⁹ מה שברא הקב״ה בעולמו לא בראו אלא לכבודו״⁴⁰, יעדער נברא ברענגט ארויס כבודו של הקב״ה אין אן אופן וואס קיין אנדער נברא ופרט קען דאס ניט ארויסברענגען. לדוגמא: בשעת א יחיד אין א פינה רחוקה שבעולם נעמט אן איינפאכן גלאז ווא־סער און מאכט דערויף א ברכה —",[["36","36","ע״פ תהלים פז, ז."],["37","37","הל׳ תשובה פ״ג ה״ד."],["38","38","ואדרבה — ריבוי ההתחלקות הוא דוקא מצד פשיטות העצמות (תו״ח נח ע, ב ואילך. דרמ״צ מט, א (במהדו״ת). סהמ״ת תרס״ב ע׳ של ואילך. עת״ר ע׳ קצד. השי״ת ע׳ 132 ואילך. ועוד)."],["39","39","אבות ספ״ו."],["40","40","ולשון זה („לא . . אלא״) מורה דהוא לעיכובא (ראה מנחות פג, ב תוד״ה מתני׳)."]]],[1300251348,"ברענגט דאס ארויס כבודו של הקב״ה⁴¹ מיטן גאנצן שטורעם, ע״ד ומעין ווי די גרעסטע פעולה וואס רירט אָן בכל העולם כולו בגלוי.\nוכשם ווי דאס איז אין עולם (מקום), אזוי איז דאס אויך (אין זמן און) אין נפש⁴² — אז יעדער איד בפרט איז אנ־געזאגט געווארן צו מקיים זיין אלע מצוות⁴³, ווארום יעדער איד האט זיין שליחות מיוחדת בעולם וואס קיין צוויי־טער קען ניט פארבייטן⁴⁴.\nאון דוקא דורך צירוף כל הפרטים, יעדער פרט בשלימותו, האט מען דעם כלל און שלימות הכלל.\nאזוי איז אויך מובן בנוגע צו די שלוחים פון נשיא דורנו: א שליח האט ניט צו זיין אראפגעפאלן בא זיך, אז ער געפינט זיך אין א פינה רחוקה, און פארנעמט זיך לכאורה מיט איינ־פאכע זאכן, לערנען תורה מיט א קינד, דערציילן א פרוי וועגן צינדן נרות שבת ויו״ט, וועגן פרטי האדעווען די בני בית — ווייל אדרבה ואדרבה: דוקא אין דעם איינפאכן טאג־טעגלעכן לעבן פון א מאן און א פרוי והנהגת בני ביתם, וואס מ׳טוט לכאורה בלי התפעלות — דוקא אָט דארט ליגט די כוונה עליונה, און דוקא דאס ברענגט ארויס כבודו של הקב״ה, ובאופן כזה וואס קיין אנדער מענטש און קיין אנדער זאך אין וועלט קען דאס ניט ארויסברענגען!!\nאון דוקא בשעת יעדער שליח פרטי פירט אויס זיין שליחות הפרטית במקומו ופינתו הפרטי מיט די תושבי המקום הפרטיים — ברענגט דאס, בצירוף כולם יחד, הצלת כלל ישראל און די גאולה האמיתית והשלימה!\nח. ולאחרי ההקדמה זו — קומט צו גאר אן אנדער געשמאק אין דעם כנס השלוחים, וואו עס קלייבן זיך צוזאמען שלוחים פון פארשידענע שטעט און שטעטלעך, וואס יעדער יחיד קען מוסיף זיין אין אלע אנדערע שלוחים, „איש את רעהו יעזרו ולאחיו יאמר חזק״, און מוסיף זיין ניט קיין דבר טפל, נאר א דבר הכי עיקרי.\nאון דורך צירוף כולם יחד שטעלט זיך צוזאמען א כלל הכי גדול⁴⁵ — די אלע שטעט און שטעטלעך רעפרעזענטירט (פארגעשטעלט) יעדערער דורך זיין שליח, וואס דאס איז אין זיך כולל א ריבוי גדול פון אידן.\nאון דער כלל גדול (וואס שטעלט זיך צוזאמען פון די פרטים) גיט נאכמער כח צו יעדער שליח בפרט, אז צוריקפארנ־דיק למקום שליחותו זאל ער האבן נאכ־מער ידיעות, עידוד, חיות וחיזוק צו אויספירן שליחותו אין מקומו הפרטי אין זיין „איינפאכן״ טאג טעגלעכן לעבן, וביתר שאת וביתר עוז, באופן פון הולך ומוסיף ואור, וויסנדיק אז דוקא דורך דעם איז ער מוסיף בכבודו של הקב״ה.\nאון דוקא דורך דעם — ווערט נאך לייכטער צו העלפן כלל ישראל, ביז „איינעמען״ די גאנצע וועלט מיט צדק, יושר וידיעת ה׳, און בנוגע צו אידן במיוחד — בתורה ומצוות ומעינות",[["41","41","„השוה ומשוה קטן וגדול״ (פיוט וכל מאמינים בימים הנוראים)."],["42","42","אשר על ענין ג׳ בחי׳ אלו הוא יסוד של ספר יצירה (תורת שמואל סהמ״ת תרכ״ח ד״ה והר סיני עשן ע׳ קמד)."],["43","43","כמבואר בכ״מ בהטעם שעשרת הדברות נאמרו בלשון יחיד (יל״ש יתרו רמז קפו. מפסיקתא דר״כ פ׳ בחודש השלישי. וראה פסיקתא רבתי פכ״א. רמב״ן עה״ת יתרו כ, א)."],["44","44","וכמובן מדברי המשנה (אבות רפ״ד) „איזהו חכם הלומד מכל אדם״."],["45","45","ראה (שבת סח, א) בענין „כלל גדול״ — ומזה מובן בנוגע „הכי גדול״."]]],[1300251349,"החסידות. ביז — אז מ׳ברענגט די גאולה פון כלל ישראל און פון כל העולם כולו.\nט. אין דעם אלעם קומט צו נאך א „דבר חידוש״ (לגריעותא) בדורנו זה במיוחד (ובפרט אין די יארן נאך שנת תש״י), וואס ברענגט אבער מיט זיך א „דבר חידוש״ (למעליותא) — עס איז איצט געגעבן יעדערן א מעגלעכקייט, און עס ליגט אויף יעדערן אן אחריות, צו טאן אין הפצת התורה והיהדות והפצת המעינות חוצה:\nבדורנו זה זעט מען בפועל די ירידה גדולה ר״ל אין דעם מצב פון אידן און אידישקייט: עס זיינען דא אזויפיל אידן וואס באקומען ניט קיין שום הדרכה וחינוך אין אידישקייט, תורה ומצוות.\nאע״פ וואס כמה עסקנים טוען אין מתקן זיין דעם מצב — איז לאחרי אלע השתדלות ופעולות — בלייבן איבער ארום ר״ל דריי פערטל אידישע קינ־דער, און אויך ערוואקסענע, וואס בא־קומען ניט קיין אידישן חינוך, ר״ל!\nהאט יעדערער איצטער די געלעגנ־הייט — און די ערנסטע אחריות — צו „איבערקערן די וועלט״ למעליותא, דורך ארויסגיין (בפשטות און ארויסגיין פון זיך) און טאן כל התלוי בו צו מקרב זיין אידן צו אידישקייט, ובדרכי נועם ובדרכי שלום, אן קיין מחלוקת — און אין היינטיקן מצב איז וויפל אנדערע טוען בשטח זה, איז דא א ריבוי עבודה אין דעם אלעם און עס איז דא א ריבוי אידן וועלכע מ׳קען און מען מוז העלפן.\nיוד. האט מען דערפון דעם לימוד בקשר מיט שליחות נשיא דורנו, און אויך אן ענטפער צו די וואס זוכן ערטער וואו צו פארן אויף שליחות:\nס׳איז נאך קיינמאל ניט געווען אזא מצב ווי היינט ווען מ׳קען איינעמען די גאנצע וועלט מיט תורה און אידישקייט בדרכי נועם ובדרכי שלום — וואַרום „כל הארץ לפניך״⁴⁶ (ניט נאר ארץ ישראל, נאר אויך חוץ לארץ), באופן פון „ופרצת ימה וקדמה וצפונה ונגבה״⁴⁷,\nוואַרום בכל מקום ומקום (אפילו אין ברוקלין, ניו־יארק, וכיו״ב) זיינען דא טויזנטער אידישע קינדער און ערוואק־סענע וואס באקומען ניט קיין אידישן חינוך, און בכדי זיי מקרב זיין צו אידיש־קייט דארף מען מיט קיינעם ניט מלחמה האבן. ועד״ז אין אנדערע עניני יהדות.\nדעריבער דארף מען מכריז זיין צו אלע אידן, ובמיוחד צו תלמידי ישיבת תומכי תמימים, וועלכע די רביים האבן אויפגעהאדעוועט (און זיך מוסר נפש געווען אויף דעם) אז זיי זאלן ארויסגיין אין „מלחמת⁴⁸ בית דוד״ צו ברענגען משיח צדקנו⁴⁹, און אז זיי זאלן אויס־וואקסן צו זיין עסקני ציבור און שלוחים:\nווערט שלוחים און גייט איינ־נעמען די וועלט מיט אידישקייט!\nואין הדבר תלוי אלא ברצון⁵⁰ — מ׳זאל ניט ליגן אין „פערל־גרויפען אין יויך״, נאר אין „פערל אויפן האלדז״⁵¹ (כפתגם כ״ק מו״ח אדמו״ר).",[["46","46","ל׳ הכתוב — לך יג, ט."],["47","47","ויצא כח, יד."],["48","48","ל׳ חז״ל — שבת נו, א."],["49","49","ראה שיחת כ״ק אדמו״ר מהורש״ב נ״ע שמחת תרס״א הנ״ל, ד״ה „כל היוצא למלחמת בית דוד״ — נדפסה בס׳ השיחות תש״ב ס״ע 141 ואילך. לקו״ד ח״ד תשפז, ב ואילך."],["50","50","ולאידך גיסא — „אין לך דבר שעומד בפני הרצון״ (ראה סה״מ תש״ג ע׳ 12. ובכ״מ)."],["51","51","להעיר שא׳ מכ״ד קשוטי כלה הוא „הנטיפות״ — „שתלויות על הצואר ונוטפות על החזה והן כמין מרגליות נקובות וחרוזות בחוט״ (ישעי׳ ג, יט ובפרש״י)."]]],[1300251350,"יא. ולהעיר — בתור מאמר המוסגר:\nמ׳דארף ניט אנקומען צו ראיות אז דרך חב״ד ושלוחי חב״ד איז דוקא מתוך אהבת ישראל ובדרכי נועם ובדרכי שלום⁵² — ווייל דאס איז די מהות פון חב״ד און ליובאוויטש⁵³ — אהבת ישראל ואחדות ישראל⁵⁴.\nאון אפילו ווען עס זיינען דא אזוינע אידן וואס פירן זיך ח״ו שלא כרצוי — זאגט די גמרא⁵⁵ „יתמו חטאים״⁵⁶ ולא חוטאים ח״ו: חב״ד האט מלחמה מיט עבירות, אבער ניט מיט די חוטאים, אדרבה — מ׳איז זיך משתדל זיי מחזיר זיין בתשובה.\nזיכער טאר מען ניט געבן א „הכשר״ אויף די הנהגה פון די „חוטאים״, און מ׳דארף באווארענען אז אנדערע זאלן זיך אזוי ניט פירן: אבער דאס איז א מלחמה מיט די „חטאים״ ניט מיט די „חוטאים״. בדוגמא ווי עס איז אן איסור וחה״ש וכו׳ געבן א הכשר אויף בשר טריפה, דאס איז אבער א התנגדות צו דעם בשר טריפה, ניט צו דעם קצב.\nיב. דערפון האט מען נאך א נקודה הכי עיקרית וועלכע מ׳דארף צוגעבן צו דעם „סדר היום״ פון דעם כנס השלוחים:\nאיצטער איז א צייט ווען יעדער שליח קען איינעמען זיין גאנצע שטאט מיט הפצת הצדק והיושר והפצת התורה והיהדות והמעינות חוצה, בדרכי נועם ובדרכי שלום.\nאבער כאמור לעיל, דער סדר בזה דארף זיין — ניט מ׳גייט כובש זיין כל העולם כולו, נאר מ׳הויבט אן מיט דער אייגענער שטאט און די מענטשן וואס וואוינען דארט. און דערפון קומט מען דערנאך צו הצלת כלל ישראל וכל העולם כולו.\nיג. ובכל זה קומט צו א תוספת כח אין דעם כנס השלוחים דערפון וואס דאס הויבט זיך אן בשבת זו:\nשבת בכלל גיט א כח אז די עבודה (פון די שלוחים) זאל אנקומען מתוך עונג, ובאופן פון „כל מלאכתך עשוי״⁵⁷.\nובפרט בשבת זו — וואס ווערט גע־בענטשט פון דעם שבת שעברה, כ״ף חשון, דער יום הולדת פון דעם רבי״ן (מהורש״ב) נ״ע⁵⁸, דער מייסד פון ישיבת תומכי תמימים, און דער נשיא וואס האט אנגעהויבן די עבודה פון ממנה זיין די תלמידי התמימים אלס שלוחים וחיילים במלחמת בית דוד, צו מפיץ זיין די מעינות חוצה און ברענגען משיח צדקנו, און דער המשך ושלימות בזה — ע״י בנו ממלא מקומו, כ״ק מו״ח אדמו״ר נשיא דורנו.\nיד. ולסיכום — בנוגע לפועל:\nיהי רצון אז דער כנס השלוחים זאל זיין בהצלחה רבה ומופלגה, און דער כח",[["52","52","ולהעיר גם מהלימוד בזה משיעור היומי ברמב״ם בגודל החומר דאונאת דברים, ש„לא ניתן להשבון״ והוא „דבר מסור ללב״ שנאמר בו (בהר כה, יז) „ויראת מאלקיך״ (הל׳ מכירה ספי״ד)."],["53","53","ע״ש ענין האהבה („ליובאו״ — בשפת המדינה ההיא) — ראה ספר הזכרונות ח״א ס״ע 17. וראה גם שם ריש ע׳ 342."],["54","54","ראה ס׳ הערכים־חב״ד ערך אהבת ישראל ס״ט. וש״נ."],["55","55","ברכות י, א."],["56","56","תהלים קד, לה."],["57","57","מכילתא ופרש״י יתרו כ, ט. טושו״ע (ואדה״ז) או״ח סש״ו ס״ח (סכ״א)."],["58","58","ראה לעיל ע׳ 312 ואילך — בארוכה."]]],[1300251351,"הציבור זאל אריינגעבן כח וחיות צו יעדערן פון די שלוחים בפרט צו אומ־קערן זיך למקומו און אראפברענגען בפועל בקיום שליחותו די נקודות האמורות:\nאז איצטער איז א צייט צו איינעמען די גאנצע וועלט מיט צדק ויושר און אידישקייט בדרכי נועם ובדרכי שלום. און דער סדר בזה דארף זיין — לכל לראש דורך דעם וואס יעדער שליח פירט דורך שליחותו בא די תושבים פון זיין שטאט.\nובמיוחד — דורך אויפבויען (אדער מרחיב זיין) א „בית חב״ד״ במקומו⁵⁹, א בית תורה תפלה וצדקה, כמדובר כמה פעמים לאחרונה⁶⁰.\nויש להוסיף בזה עוד הצעה: בכדי עס זאל זיין א המשך פון דעם כח הציבור פון א כנס השלוחים, כו״כ שלוחים ביחד — איז כדאי, אז מ׳זאל באשטימען א מקום מרכזי (און א טעלעפאן) וואו יעדער שליח קען זיך פארבינדן און בעטן אן עצה אדער הילף אין קיום שליחותו במקומו, מ׳זאל אים צושטעלן א רעדנער וכו׳ וכו׳.\nובכל זה האט מען די הבטחה — אז „איני מבקש כו׳ אלא לפי כחן״⁶¹, און נאכמער: מ׳גיט נאכמער כח, מער וויפל מ׳דארף אויף דעם האבן⁶².\nאון דורך דעם וואס מ׳וועט טאן בזה באופן האמור — וועט מען צום אלעם ערשטן מצליח זיין אין קיום השליחות, און מיט א הצלחה למעלה מן המשוער; און דערצו וועט מען אויך האבן הצלחה אין די אייגענע ענינים — בבני חיי ומזוני רויחי ובכולם רויחי — געזונטע קינדער, און געזונטע אייניקלעך, און מאכן גוטע שידוכים, און זיין גע־בענטשט מיט אלע ברכות.\nטו. ולהוסיף נאך א נקודה: די רביים האבן געמאנט אז חב״ד זאל נתפשט ונתפרסם און ווערן בכל קצוי תבל. דערי־בער איז א דבר נכון במאד — אז בנוגע דעם כנס השלוחים ופעולת השלוחים זאל מען ניט טאן בזה באופן פון „הצנע לכת עם אלקיך״⁶³, מצד החשש אז דער־פון קען ח״ו צוקומען ישות כו׳⁶⁴, נאר ע״פ המבואר והציווי — „מצוה לפרסם עושי מצוה״⁶⁵, מ׳זאל דאס מפרסם זיין באופנים האפשריים, אזוי אז עס זאל זיין מהם יראו וכן יעשו רבים, און אויך די רבים זאלן ווערן „נרות להאיר״.\nטז. דער אויבערשטער זאל העלפן אז דורך די עבודה פון די שלוחים",[["59","59","רמז לזה בפרשתנו (כד, סז ובפרש״י) „ויביאה יצחק האהלה שרה אמו״, „ויביאה האהלה והרי היא שרה אמו, כלומר ונעשית דוגמת שרה אמו, שכל זמן ששרה קיימת הי׳ נר דלוק מערב שבת לערב שבת וברכה מצויה בעיסה וענן קשור על האהל ומשמתה פסקו וכשבאת רבקה חזרו״, ומשום זה „ויקח את רבקה ותהי לו לאשה״. ובזה נראית המעלה אפילו בחידוש פעולה ב„האהלה שרה אמו״ (בלא הקמה חדשה) ע״י רבקה — ע״ד הרחבת „בית חב״ד״: עאכו״כ הקמת „בית חב״ד״ חדש."],["60","60","ראה לעיל ע׳ 302 ואילך; 320 ואילך."],["61","61","במדב״ר פי״ב, ג."],["62","62","להעיר מספורנו לויקהל לו, ז."],["63","63","מיכה ו, ח."],["64","64","להעיר ממענה כ״ק אדמו״ר האמצעי לאחר שהתאונן על רגש הישות מחזרת דא״ח: א ציבעלע זאל פון דיר ווערן, אבער חסידות זאלסטו חזור׳ן! נת׳ בלקו״ש חי״א ע׳ 329. חכ״ד ע׳ 144. ועוד."],["65","65","שו״ת הרשב״א ח״א סתקפ״א. רמ״א יו״ד סרמ״ט ס״יג. מג״א או״ח סקנ״ד ס״ק כג. ולהעיר ממחז״ל (ויק״ר פל״ד, ח): אילו הי׳ יודע ראובן שהקב״ה מכתיב עליו כו׳."]]],[1300251352,"במיוחד, אין הפצת התורה והיהדות בכלל, ובמיוחד — הפצת המעינות חוצה, זאל דאס נאכמער ממהר זיין דעם אתי מר דא מלכא משיחא⁶⁶.\nאון „טרם כלה לדבר״⁶⁷ זאל שוין זיין „קפצה הארץ״⁶⁸, קפיצת הדרך פון די לעצטע אמות אין גלות, און אלע אידן — און די שלוחים בראשם — טאנצן גלייך אריין אין די גאולה האמיתית והשלימה, ע״י משיח צדקנו,\nומתוך שמחה וטוב לבב, ובמהרה בימינו ממש.",[["66","66","אגה״ק הידועה דהבעש״ט (נדפסה בכש״ט (הוצאת קה״ת) בתחלתו. ובכ״מ)."],["67","67","ל׳ הכתוב — פרשתנו כד, טו. נת׳ בלקו״ש ח״כ ע׳ 91 ואילך."],["68","68","ראה פרש״י פרשתנו כד, מב."]]],[1300251353,"משיחת ש״פ תולדות, מבה״ח וער״ח כסלו ה׳תשד״מ — בקשר עם כנס השלוחים שי׳ (שהתחיל בשבת זה).\nא. דעם שבת¹ הויבט זיך אויך אָן דער כנס פון די שלוחים (פון ארצות הברית). ובקשר דערמיט וועט מען רעדן כמה נקודות וועגן דעם ענין ותפקיד פון די שלוחים.\nאַלע אידן זיינען שלוחים² פון דעם אויבערשטן ובפרט דורך דעם וואָס זיי זיינען מקיים תומ״צ, כמאחז״ל³ ״היו מכבדין את המצוות שהן שלוחי״. האָבן זיי דעם עילוי פון שלוחו של אדם (העליון) כמותו⁴, און ווי דער אַלטער רבי⁵ איז מוסיף⁶ — כמותו (דהמשלח) ממש.\nצווישן אידן גופא זיינען דאָ די וועלכע האָבן זוכה געווען צו זיין שלוחים מיוחדים פון נשיא דורנו כ״ק מו״ח אדמו״ר, אָדער ע״י שלוחו ושליח עושה שליח⁶* וכו׳ — אויף הפצת היהדות בכלל, ובמיוחד — הפצת המעינות חוצה.\nהאָבן די שלוחים אין זיך די אַלע עילויים וואָס אַ שליח האָט: שלוחו של אדם כמותו, ביז כמותו ממש פון נשיא דורנו וואָס הנשיא הוא הכל⁷.\nאון ווי געשריבן⁸ און גערעדט⁹ צו די שלוחים בארץ הקודש — ופשוט אַז דאָס איז אויך שייך צו די שלוחים וואָס געפינען זיך איצטער דאָ, און צו אַלע שלוחים בכל העולם כולו — אַז עס זיינען דאָ דריי דרגות ואופנים אין שליחות¹⁰: (א) די מעשה השליח איז דעם משלח׳ס, (ב) דער אבר השליח (לדוגמא — ידו) מיט וועלכע ער איז מקיים שליחותו איז דעם משלח׳ס, (ג) כל מציאות השליח איז כמותו דהמשלח.\nדערנאָך איז דאָ נאָך אַ פערטע דרגא¹¹ [והיות אַז דער משלח איז נשיא דורנו ששמו ״יוסף״, וואָס הנהגתו איז געווען באופן פון ״טוב עין הוא יבורך״¹² — האָט ער זיכער אַריינגעגעבן אין דער שליחות אויך די פערטע (העכסטע) דרגא]: ניט דער שליח ווערט כמותו פון דעם משלח, נאָר ער איז די מציאות המשלח אַליין, ווי דער רשב״א¹³ שרייבט (כמדובר כמ״פ, וכמ״פ בארוכה) בנוגע צו דעם וואָס מ׳זאָגט אויף אַן עבד ״מה",[["1","1","דשיעור החומש שלו מתחיל: וישלח יצחק את יעקב גו׳."],["2","2","ראה לקו״ת ר״פ ויקרא."],["3","3","תנחומא ויגש וא״ו."],["4","4","ברכות לד, ב (במשנה). קידושין מא, ב. וש״נ."],["5","5","לקו״ת שם."],["6","6","וכן הוא לשון הריב״ש (בתשובותיו סרכ״ח). ובודאי נמצא בכ״מ. 6*) קידושין שם, א."],["7","7","פרש״י עה״ת חוקת כא, כא."],["8","8","מכתב דט״ז מנ״א — לכל המשתתפים בכינוס השלוחים כו׳ — תשמ״ג (נדפס בלקו״ש חכ״ד ע׳ 393)."],["9","9","שיחת ש״פ עקב, כ״ף מנ״א תשמ״ג."],["10","10","ראה בארוכה לקח טוב (להר״י ענגיל) כלל א. וראה שו״ע אדה״ז או״ח סי׳ רסג סכ״ה בקו״א."],["11","11","ראה שיחה שבהערה 9, ששם נתבאר אופן ד׳ ע״ד מעלת אתכפיא על אתהפכא, עיי״ש."],["12","12","משלי כב, ט שדרז״ל על יוסף (זח״ג קל, א. וראה המשך תער״ב ח״ב ע׳ א׳לא)."],["13","13","קידושין כג, ב."]]],[1300251354,"שקנה עבד קנה רבו״¹⁴ — ס׳איז ניט דער פירוש אַז פריער איז דער עבד קונה די זאַך און דערנאָך איז רבו קונה פון אים, נאָר רבו איז דאָס מלכתחילה קונה, וואָרום דער עבד איז קיין מציאות ניט בפ״ע, נאָר ער איז מציאות רבו, במילא גלייך ווי דער עבד באַקומט די זאַך, איז רבו דאָס קונה.\nב. דער שליח דאַרף אָבער האָבן די זהירות ניט צו משנה זיין משליחותו, אויב ער איז ח״ו משנה משליחותו ווערט ער אויס שליח¹⁵, און פשיטא — ווערט אויס מציאות המשלח; לאידך גיסא אָבער — אויב ער איז מקיים שליחותו כפי רצון המשלח, איז ער אַ שליח מיטן גאַנצן תוקף, ביז אַז שלוחו של אדם כמותו ממש, ער איז ממש דער משלח אַליין, ביז ווי די פערטע דרגא הנ״ל, ובמילא האָט ער בכח צו מאַכן נאָך אַ שליח (שליח עושה שליח) א.א.וו. אויף דורכפירן די שליחות פון הפצת היהדות והפצת המעינות (ביז אין) חוצה.\nג. ווערט אַ שאלה באַ דעם שליח: ער איז דאָך אַ בשר ודם, און ער האָט אַ גוף, ״הנדמה בחומריותו לגופי אומות העולם״¹⁶ — האָט ער מורא און ער ווייסט ניט ווי וועט ער מכוון זיין (בדיוק) צו דורכפירן רצון המשלח, דערפון ניט משנה זיין וכו׳?\nענטפערט מען אים: דורך דעם וואָס ער וועט זיך פירן באופן פון ״תמים תהי׳ עם ה׳ אלקיך״¹⁷, און ער איז מחליט זיך מתגבר זיין איבער די פיתויי היצר מבפנים און מניעות ועיכובים מבחוץ — איז זיכער אַז ער וועט מכוון זיין צו רצון המשלח,\nוואָרום ״איני מבקש כו׳ אלא לפי כחן״¹⁸, האָט מען אים זיכער געגעבן די כחות אויף דורכפירן די שליחות בשלימותה, מכוון זיין לרצון המשלח, כאָטש אַז מ׳איז אַ נשמה בגוף. ואדרבה: דער משלח האָט אויסגעקליבן ניט אַ מלאך אויף טאָן די שליחות, נאָר דעם איד דוקא און ווי ער איז אַ נשמה בגוף — במילא האָט ער זיכער באַוואָרענט אַז ער זאָל האָבן די כחות צו דורכפירן די שליחות, צו מכוון זיין לרצון המשלח בשלימותו ובמילואו, ביז אין אַן אופן פון ״כדבעי לי׳ למיעבד״¹⁹, און — בהרחבה.\nאון ווי נשיא דורנו (המשלח) האָט געזאָגט אַז עס דאַרף נאָר זיין דער ״עמדו הכן כולכם״²⁰, וואָרום ס׳איז שוין מוכן. וכאמור, פירן זיך באופן פון ״תמים תהי׳ עם ה׳ אלקיך״ — האָט מען די אַלע ברכות והצלחה און ווינטשוואַניעס (בלשון העולם).\nד. רבותינו נשיאינו האָבן געוואָלט און האָבן געגעבן כחות אַז אַלע זאַכן זאָל מען מקיים זיין בשלימות. וואָס דאָס איז כולל אויך — אַז מ׳זאָל מקיים זיין די שליחות פון רבותינו נשיאינו בשמחה ובטוב לבב, ווי מ׳זעט במוחש אַז בשעת מ׳טוט אַ זאַך, בנדו״ד — דורכפירן די שליחות פון הפצת היהדות והפצת",[["14","14","קידושין שם. פסחים פח, ב."],["15","15","רמב״ם הל׳ שלוחין ושותפין פ״א ה״ב ואילך. שו״ע חו״מ סי׳ קפב ס״ב ואילך."],["16","16","תניא פמ״ט (ע, רע״א)."],["17","17","שופטים יח, יג. וראה לקו״ת נצבים מה, ג."],["18","18","במדב״ר פי״ב, ג."],["19","19","ראה כתובות סז, רע״א."],["20","20","מכתב כ״ק מו״ח אדמו״ר מכ״ז אייר תרח״ץ (נדפס בהקדמה לקונטרס צו בתחלתו — סה״מ קונטרסים ח״ב שצז, ב. אגרות קודש שלו ח״ד ע׳ רעט)."]]],[1300251355,"המעינות חוצה — בשמחה ובטוב לבב, צופרידענערהייט, גיט עס צו שלימות אין דער פעולה.\nוואָס דאָס — מקיים זיין די שליחות בשמחה ובטוב לבב — האָט אויך אַ שייכות מיט דער פרשה וועלכע מ׳גייט איצט לייענען צו מנחה²¹ מנחת שבת (זמן רעוא דרעוין) פ׳ ויצא:\nבהמשך צו ״ויצא יעקב מבאר שבע וילך חרנה״²² שטייט ״וישא יעקב רגליו״²³. איז רש״י מפרש (און נאָכמער בארוכה אין מדרשים²⁴): ״משנתבשר בשורה טובה כו׳ נשא לבו את רגליו ונעשה קל ללכת״.\nאַזוי אויך בעניננו — די שליחות פון רבותינו נשיאינו: וואָס פאַר אַ בעסערע בשורה טובה איז דאָ — ווי די הבטחה פון רבותינו נשיאינו צו אַלע זייערע שלוחים, אַז זיי וועלן מצליח זיין און זיי וועלן באַקומען אַלע ברכות והצלחות וכו׳. במילא פועל׳ט עס זיכער באַ דעם שליח אַז ״נשא לבו את רגליו ונעשה קל ללכת״ און ער גייט מקיים זיין שליחותו בשמחה ובטוב לבב, וויסנדיק אַז ער האָט די אַלע הבטחות ובשורות טובות, און וויסנדיק אַז ער איז שלוחו של אדם כמותו ממש, ער איז מציאות המשלח, איז ער זיכער מקיים שליחותו בשמחה ובטוב לבב.\nה. ויש להוסיף בזה ע״ד הרמז: ״שליח״ איז בגימטריא ״שמח״, וי״ל הפי׳: אמיתית ענין השליח איז — אַז ער איז ״שמח״: ניט אַז מ׳נייט אים (ובהרגש שלו — אַז מען איז כופה אַז ער זאָל מבטל זיין יישותו ומציאותו להמשלח) און מ׳איז אים מכריח גיין און מקיים זיין שליחותו, נאָר ער גייט צופרידענער־הייט — ער איז ״שמח״ דערפון וואָס ער איז — (וכמרומז בהגימטריא שלו) שליח, ביז שלוחו של אדם כמותו ממש.\nאָבער לאידך גיסא — ״שליח״ איז נאָר בגימטריא ״שמח״, ס׳איז ניט בגלוי אין דעם וואָרט ״שליח״, נאָר בהעלם אַלס אַ גימטריא²⁵: דער ענין אַז דער שליח איז ״שמח״ ובפרט וויסנדיק אַז ער האָט אַלע כחות והבטחות צו מצליח זיין אין זיין שליחות — איז נאָר אַ זאַך וואָס ער דאַרף וויסן פאַר זיך (בכדי ער זאָל דורכפירן שליחותו במילואה ובשלימותה), אָבער ביחס צו דער סביבה אַרום אים דאַרף עס זיין בהעלם (ווי אַ גימטריא), ד.ה. בגלוי (ביחס צו די מענטשן אַרום אים) טאָר ער זיך ניט פירן אין אַן אופן אַז היות ער איז דער שלוחו של אדם כמותו פון נשיא דורנו והנשיא הוא הכל — קען ער ח״ו טרעטן אויף אַנדערע און אויף דער וועלט, ובשעת ער קומט אין אַן אָרט און ער ווייס פאַר זיך עכ״פ — אַלס שליח פון נשיא דורנו — קען ער ח״ו שטופן, וואַרפן אַנדערע, אַמאָל אויך די וואָס זיינען פריער געווען דאָרטן, פירן מחלוקת וכו׳ — איז דאָס אַ שינוי בהחלט מ(רצון) המשלח והתוצאה כנ״ל. וד״ל. — ער מוז און דאַרף זיך פירן",[["21","21","וכמרז״ל במעלת תפלת מנחה (ברכות ו, ב. וראה בארוכה ד״ה לעולם יהא אדם זהיר כו׳ תרנ״ד (סה״מ תרנ״ד ע׳ פז ואילך), עזר״ת (סה״מ עזר״ת ע׳ פב ואילך), תרצ״א (סה״מ קונטרסים ח״א רג, ב ואילך). ובכ״מ)."],["22","22","ר״פ ויצא (כח, י)."],["23","23","שם כט, א."],["24","24","ב״ר פ״ע, ח."],["25","25","ראה תניא שער היחוד והאמונה ספ״א. פ״ז (פד, ב)."]]],[1300251356,"דוקא בדרכי נועם ובדרכי שלום — מ״ע מה״ת וכל התורה ניתנה ע״ז²⁶ — דער רצון פון נותן התורה — המשלח את המשלח שלו.\nו. אויב ער האָט בדקות דדקות עכ״פ ״נעגל״ איז דאָס אַ פנימיות׳דיקער ענין, ער קען עס נוצן, אויב מען דאַרף, בנוגע זיך, בנוגע צו אַנדערע דאַרף און מוז זיין די הנהגה דוקא באהבה וקירוב ודרכי נועם ודרכי שלום²⁷ [כמדובר לעיל²⁸ דער רמז פון ״ועשתה את צפרני׳״²⁹, ״ועשתה״ מלשון תיקון³⁰ — ביחס צו זיך, ניט ביחס צו אַנדערע],\nכרצון המשלח, נשיא דורנו ששמו ״יוסף״, די הנהגה זאָל זיין דוקא באופן פון ״טוב עין הוא יבורך״ (כהנהגת יוסף), און מ׳האָט אָנגעזאָגט אַז דוקא דאָס איז דער וועג צו מצליח זיין!\nויה״ר אַז דורך דעם ענין פון יפוצו מעינותיך חוצה ובאהבה³¹ זאָל מען נאָכמער ממהר זיין דעם ״אתי מר״ דא מלכא משיחא³², גאולה האמיתית והשלימה ע״י משיח צדקנו, במהרה בימינו ממש.\nבמענה על הפ״נ שנמסר לכ״ק אדמו״ר שליט״א מהשלוחים שי׳ משתתפי הכנס — הואיל כ״ק אדמו״ר שליט״א לענות:\n״בנוסף על השיחה (כולל — ש״בין השורות שלה״) מלתייהו אמורה* — כל המברך מתברך בברכתו של הקב״ה שתוספתו מרובה על העיקר** — מתחיל בהעיקר מילוי השליחות בשלימות״.",[["26","26","רמב״ם סוף הל׳ חנוכה מספרי נשא ו, כג. וראה לקו״ש ח״ח ע׳ 349 ואילך."],["27","27","ראה ״היום יום״ כב אלול. אגרות קודש אדמו״ר מהוריי״צ ח״ב ע׳ תקכה. ח״ד ע׳ יד ואילך. סה״מ קונטרסים ח״ב שב, ב ואילך. ועוד."],["28","28","שיחה ב׳ דההתוועדות."],["29","29","תצא כא, יב."],["30","30","להעיר: בהמשך תער״ב (ח״ג ע׳ א׳שפט) ״ועשתה צפרני׳ ת״א ותקנית״. ובת״א שלפנינו — ליתא. ואולי צ״ל ״ועשתה את צפרני׳ ותר׳ ותתקני׳״. ועפ״ז יומתק ג״כ שלא שינה מל׳ הלקו״ת שלח (לח, ב), סידור (שער המילה) קמה, א וסהמ״צ להצ״צ מצות מילה (ט, א). ויש לברר בכת״י התרגומים."],["31","31","היפך סיבת החורבן (יומא ט, ב)."],["32","32","אגה״ק דהבעש״ט הידועה — נדפסה (גם) בכש״ט (הוצאת קה״ת) בתחלתו. ובכ״מ. *) ירושלמי (ברכות ספ״ח) הובא בתוד״ה ואברכך — חולין מט, א. **) ב״ר פס״א, ד. וראה בארוכה לקו״ש ח״ה ע׳ 422 ואילך. ועוד."]]],[1300251357,"משיחת ש\"פ תולדות, מבה\"ח וער\"ח כסלו ה'תשד\"מ – הוראה לשלוחים תלמידי ישיבה ואברכי כולל שי'.\nא. בהמשך להההוראה הנ\"ל¹) דערפון וואס „שליח\" איז נאר בגימטריא (בהעלם) „שמח\", אז מ'דארף זיין זהיר בהשליחות צו זיך פירן בדרכי נועם ובדרכי שלום און ניט פירן מחלוקת וכו' — איז אזוי אויך, כפשוט, בנוגע צו די בחורים אדער יונגע־לייט וועלכע מ'האט געשיקט אלס שלוחים מהכא להתם למקום שני, אדער ממקום שני להכא בכדי צו לערנען אין א ישיבה אדער אין א כולל:\nמ'האט זיי געשיקט אלס שלוחים צו זיין תלמידים אדער חברי הכולל און „נרות להאיר\"²) (ווי מ'האט מדגיש גע־ וועזן בתחלת שליחותם) . . ניט צו זיין מנהלים. און וויבאלד אז מ'האט זיי אויסגעקליבן אלס שלוחים, באווייזט עס אז זיי זיינען פון די מובחרים ומשובחים שבתלמידים, און מ'האט זיכער אפגע־ שאצט אז זיי קענען אויספירן שליחותם (ווייל „איני מבקש כו' אלא לפי כחן\"³).\nבמילא האט כלל קיין ארט ניט אז זיי זאלן זיך מישן אין הנהלת הישיבה (דער — ראש ישיבה וכיו\"ב) אדער הנהלת הכולל דארטן, און זאגן דיעות ווער זאל אנפירן און ווער ניט, עאכו\"כ פרואווען אימעצן אראפווארפן, ובכלל — אי שימת לב לההנהלה ולהסדרים, בוי־ טשען זיך און פירן קליינע מחלוקת'ן וכיו\"ב!\nפשיטא אז אויף דעם זיינען זיי ניט שלוח ואדרבא, במילא אויב זיי טוען דאס, זיינען זיי משנה מרצון המשלח (ועד — להפכו), ווערן זיי אויס שלו־ חים⁴)...!\n— וואס דאס איז (אויך) מיוסד אויף די שיחה פון דעם רבי'ן (מהורש\"ב) נ\"ע (שוין געדרוקט אין „תורת שלום\"⁵) וועגן אור המשפיע ואור המקבל וכו' (נאר ווי עס ווייזט אויס זיינען דארטן פארצייכנט די רייד בקיצור, אבער דער תוכן — איז דער יסוד פון וואס מ'רעדט איצטער).\nובפרט אז איצטער איז א צייט, ווען מ'וויל און מ'דארף ברענגען משיח צדקנו וואס שנעלער, ובמילא — אויף טאן דוקא אין אהבת ישראל ואחדות ישראל, און ניט ח\"ו דער היפך דערפון, וואס איז א סיבה אויף דעם גלות⁶.\nב. דעריבער זאגט מען ובכל לשון של בקשה, צו די בחורים אדער כולל יונגע־לייט וועלכע געפינען זיך בשלי־ חות מהכא להתם אדער מהתם להכא:\nזייער שליחות במקומם עתה איז צו לערנען תורה און צו זיין „נרות להאיר\", ניט צו מישן זיך אין הנהלת הישיבה והמוסדות.\nאויב א בחור (א שליח) האט א טענה קעגן דעם ראש ישיבה וכיו\"ב, ולדעתו",[["1","1","לעיל ע' 342."],["2","2","ראה לקו\"ש ח\"ב ע' 484 ואילך. ח\"י ע' 310. חי\"ב ע' 149. ועוד. וראה לקו\"ש חי\"ד ע' 310 ואילך. שם ע' 314 ואילך — אודות כללות התפקיד והשליחות של תלמידי תומכי תמימים."],["3","3","לשון במדב\"ר פי\"ב, ג."],["4","4","רמב\"ם הל' שלוחין ושותפין פ\"א ה\"ב ואילך. שו\"ע חו\"מ סי' קפב ס\"ב ואילך."],["5","5","ע' 75 ואילך."],["6","6","יומא ט, ב."]]],[1300251358,"קומט אויס אז מ'דארף עפעס מתקן אדער משנה זיין, ולדעתו איז ער „מאה־ אחוז\" גערעכט — איז א גוטע זאך און א גלייכע זאך אז ער זאל זיך משתדל זיין דאס מתקן צו זיין, אבער אך ורק בדרך התורה, בדרכי נועם ובדרכי שלום: רעדן וועגן דעם מיט דעם ראש ישיבה און בחשאי ופשיטא בלא רעש, אדער (אויב לא הועיל) רעדן עד\"ז (בידיעת הר\"י) מיט דעם עומד על גביו (של הר\"י), ניט ח\"ו וח\"ו פירן מחלוקת'ן און שושקען זיך וכיו\"ב.\nאון מ'איז דערביי מפרש בפירוש: דער דרך צו מתקן זיין די זאך איז ניט דורך שרייבן מיר בריוו, דערציילן וועגן דעם מצב וכו' — ניט מען מוז מיר מישן אין דעם, ניט איך דארף זיך מישן אין דעם; דער דרך וסדר המסודר מרבו־ תינו נשיאינו איז — צו רעדן מיט דער הנהלה אדער מיט די עומדים על גבם בכבוד בדרכי נועם ובדרכי שלום, בעטן אז זיי (ההנהלה) זאלן עס מתקן זיין (אויב ס'וועט זיך ארויסווייזען אז ס'איז א דבר הצריך תיקון).\nאון אויב דעת ההנהלה קומט אויס ניט כפי דעתו — דארף ער זיך „אוועק־ זעצן\" (בהתיישבות) פאר זיך אליין ומתבונן זיין זיך בינו לבין עצמו:\nהיות אז ער איז געשיקט געווארן אלס שליח צו לערנען תורה און צו זיין א „נר להאיר\", ניט צו פירן מחלוקת און איבערקערן די הנהלה, דארף ער אנ־ נעמען אויף זיך די מרות פון הנהלת הישיבה, און אויב ער איז משנה מרצון המשלח ווערט ער אויס שליח — איז ממה־נפשך:\nאויב ער קען אננעמען אויף זיך מרות ההנהלה און זייער החלטה ווי ער דארף\nזיך פירן, און ער וועט „זיצן\" (בהתיי־ בות און) לערנען, צי מ'גיט אים נאך ווי ער האט געוואלט (מאיזה סיבה) אדער ניט, און לאזן דעם תיקון הדבר אין די הענט פון דער הנהלה, און ניט נעמען דאס אין די אייגענע הענט — איז מה טוב ומה נעים שבת גו'⁷.\nאבער אויב ער באטראכט זיך אז מאיזה סיבה שתהי' קען ער ניט בלייבן זיצן לערנען אננעמענדיק די מרות פון דער הנהלה, און קען זיך ניט פירן בדרכי נועם ובדרכי שלום, איז ער דאך משנה פון רצון המשלח וכו' — זאל ער איינפאקן זיינע פעקלעך און פארן צוריק למקום פון וואנעט מ'האט אים געשיקט צו זיין א שליח (מהכא להתם אדער מהתם להכא), און מ'וועט ניט האבן דערפאר טענות צו אים און ער וועט ניט האבן טענות צום ראש ישיבה און הנהלה.\nג. ויהי\"ר אז עס זאל זיין דער „תרבה הדעה והחכמה כו'\"⁸, תרבה החכמה, הבינה⁹ והדעת, צוזאמען מיט תרבה „האמת והשלום אהבו\"¹⁰,\nאון דורך דעם וואס מ'איז מבטל סיבת הגלות — שנאת חנם⁶ — ווערט בדרך ממילא גלייך בטל דער מסובב, דער גלות, און — „מיד הן נגאלין\"¹¹, בגאולה האמיתית והשלימה ע\"י משיח צדקנו,\nוואס השם וועט ארויסנעמען פון",[["7","7","תהלים קלג, א."],["8","8","רמב\"ם הל' תשובה פ\"ט ה\"ב."],["9","9","י\"ל שנרמזה (ברמב\"ם) בתיבת תרבה."],["10","10","זכרי' ח, יט. רמב\"ם סוף הל' תעניות."],["11","11","רמב\"ם הל' תשובה פ\"ז ה\"ה. וראה אגה\"ת פי\"א (ק, א)."]]],[1300251359,"זכרון, נאָר) אין עבודה ומעשה בפועל (נעשים).\nדערפון איז פאַרשטאַנדיק, אַז אין אַ התוועדות בקשר מיט יו\"ד כסלו דאַרף מען אַרויסנעמען אַ לימוד והוראה פון גאולת כ\"ק אדמו\"ר האמצעי, אַ לימוד והוראה ניט בלויז אין עבודה רוחנית, נאָר אויך (ובעיקר) אין עבודה גשמית, בעשי' בפועל, המעשה הוא העיקר9,\nוואָס אין דעם באַשטייט דער עיקר חידוש פון גאולת כ\"ק אדמו\"ר האמצעי, און פון אַ התוועדות בקשר עם זה, כדלקמן.\nב. דערביי שטעלט זיך די שאלה:\nמ'זעט בפועל אַז דער שטורעם און התוועדות פאַרבונדן מיט דער גאולה פון דעם אַלטן רבי'ן בי\"ט כסלו, וואָס ווערט אָנגערופן „חג החגים\"10, „ראש השנה לחסידות\"11, איז אַ סאַך גרעסער (עכ\"פ בכמות) ווי די וואָס איז פאַר־ בונדן מיט דער גאולה פון יו\"ד כסלו.\nקען מען פרעגן: בשעת מ'שטייט אונטערן איינדרוק פון י\"ט כסלו, מ'גע־ דענקט וועגן חגיגת הגאולה פון י\"ט כסלו פאַר־יאָרן, און מ'ווייסט אַז אין עטלעכע טעג אַרום וועט מען (נאָכ־ אַמאָל) פראַווען י\"ט כסלו (ובפרט אַז יו\"ד כסלו עצמו דערמאָנט וועגן י\"ט כסלו) — ווי קען מען זיך ברענגען צו שטורעמען וועגן די גאולה פון יו\"ד כסלו, און אַרויסנעמען דערפון דוקא אַ לימוד והוראה בעבודת ה'?!\nאמת טאַקע, אַז ס'איז מובן ופשוט אַז יו\"ד כסלו מוז אין זיך האָבן אַ מעלה איבער י\"ט כסלו, וואָרום „כל יומא ויומא עביד עבידתי'\"12, און ביום זה איז ער דער „שער\" דורך וועלכע אַלע אַנדערע ימי השנה זיינען דעמולט עולה13. ועאכו\"כ אַ יום ווי יו\"ד כסלו, אַ חג הגאולה פון אַ נשיא בישראל — וואָס איז „אחת בשנה\" — האָט ער זיכער אַן „עבידתי'\" מיוחדת וואָס אפילו י\"ט כסלו פאַרמאָגט ניט, און נאָכמער, כנ\"ל — דאָס איז דעמולט דער „שער\" דורך וועלכע שאר ימי השנה, כולל י\"ט כסלו, זיינען עולה, ד. ה. אַז (די עלי' פון י\"ט כסלו ב)יו\"ד כסלו טוט אויף אַן עלי' אויך לגבי ווי י\"ט כסלו שטייט מצ\"ע —\nאָבער תורה בכלל און חסידות בפרט מאָנט אַז נוסף צו אמונה דאַרף יעדער זאַך אַראָפקומען אין הבנה והשגה, בחכמה בינה ודעת, און פון דעת (מפתחא דכליל שית<sup data-n=\"14\">14</sup> — אין מדות, ביז אין מחשבה דיבור ומעשה בפועל, עבודה בפועל,\nובפרט אַז מ'זעט בפועל אַז בשעת מ'פאַרשטייט אַן ענין אין שכל והבנה, דערנעמט עס דעם מענטשן מער בפנימיות (מער ווי אויב ער האָט אין דעם אמונה בלבד), און דאָס (צוזאַמען מיט די אמונה בדבר) ברענגט אים נאָכ־ מער און ברייטער לקיום הדבר בפועל.",[["9","9","אבות פ\"א מי\"ז."],["10","10","לשון כ\"ק מו\"ח אדמו\"ר במכתבו — כ' כסלו תש\"ג (אגרות קודש שלו ח\"ז ע' ל). הקדמה לחוברת י\"ט כסלו. נת' בלקו\"ש ח\"ה ע' 436 ואילך, לקמן ע' 385 ואילך."],["11","11","מכתב כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע — ט\"ז כסלו תרס\"ב (נדפס ב„מבוא\" לקונט' ומעין ע' 17 (פקסימילי' מגוכתי\"ק). „היום יום\" בתחלתו. אגרות קודש שלו ח\"א ע' רנט)."],["12","12","זח\"ג צד, ריש ע\"ב."],["13","13","ראה לקו\"ד ח\"ד תשמז, ב. ס' השיחות ה'ש\"ת ע' 22. וראה שיחת ש\"פ ויצא, יו\"ד כסלו תשמ\"ו. ובכ\"מ."],["14","14","זח\"ב קעז, א. וראה לקו\"ת ואתחנן ו, ד."]]],[1300251360,"ג. וועט מען עס פאַרשטיין לויט דעם הפרש (בדא\"פ) פון דעם מיטעלן רבי'ן און אַלטן רבי'ן בכלל15:\nס'איז ידוע אַז גילוי תורת חסידות חב\"ד איז געווען באופן מסודר, בהתאם ווי דער סדר התגלות פון אַ שכל חדש, אַז פריער ווערט נתגלה נקודת השכל — חכמה, און דערנאָך קומט די נקודה אַראָפ אין בינה16, אין הבנה והשגה, ביז מיט די התפשטות והתרחבות, „רחובות הנהר\", פון בינה17. בדוגמא ווי אַ נהר (בינה) וואָס ווערט נמשך פון מעין (חכמה), וואָס די מי הנהר קומען פון מי המעין, אָבער אין נהר ווערן זיי נתרחב ונתפשט, „רחובות הנהר\".\nדער אַלטער רבי האָט מגלה געווען די ענינים אין חסידות אין אַן אופן פון אַ נקודה — דרגת החכמה פון תורת החסידות18; און דער מיטעלער רבי האָט אַרויסגעבראַכט די נקודה (נקודת החכמה) בביאור רחב — דרגת הבינה19 פון תורת החסידות18.\nאון ווי דער בעל הגאולה (דער מיטע־ לער רבי) אַליין שרייבט בהקדמה צו כמה פון זיינע ספרים, אַז זיינע דרושים זיינען פון זיין פאָטער, דער אַלטער רבי, בתוספת ביאור והרחבה כו'.\nווי מ'זעט עס בפשטות אין זייערע דרושי חסידות (אפילו בשעת מ'קוקט אַריין אין די מאמרים, עאכו\"כ בשעת מ'לערנט זיי).\nובלשון הקבלה והחסידות 20 — „נקודה בהיכלא\"21, נקודת החכמה בהיכל דבינה, „צריך להיות שתיהן כאחד כו'\"22.\nאון כשם ווי דאָס איז בתורתו של בעל הגאולה — איז דאָס אויך אַרויס בהנהגתו בפועל, אַז ער האָט זיך גע־ פירט מיט אַ התרחבות והתפשטות גדולה, ווייל ער איז דער כח הבינה פון חסידות חב\"ד 23.\nד. דערמיט וועט מען פאַרשטיין — בהבנה והשגה, חכמה בינה דעת — דעם אויפטו פון גאולת אדמו\"ר האמצעי ביו\"ד כסלו אפילו לגבי גאולת אדה\"ז בי\"ט כסלו (ביז אַז דאָס טוט אויף אַן עלי' אויך אין י\"ט כסלו):\nבכללות איז דער מאסר וגאולה (סיי פון דעם אַלטן רבי'ן און סיי פון דעם מיטעלן רבי'ן) געווען פאַרבונדן מיט דעם ענין פון „יפוצו24 מעינותיך",[["15","15","בהבא לקמן — ראה לקו\"ש ח\"ה ע' 129 ואילך. ח\"י ע' 99. לעיל ע' 162 ואילך."],["16","16","ע\"ד סדר התגלות נגלה דתורה — משנה ואח\"כ גמרא (חכמה ואח\"כ בינה — ראה ביאוה\"ז להצ\"צ (כרך א) ע' שסג ואילך. ועוד) — ראה לעיל שם (ע' 162). וש\"נ."],["17","17","ראה זח\"ג קמב, א. אגה\"ק סו\"ס טו. מקומות שבהערה 20. לקו\"ת שה\"ש לט, א ואילך."],["18","18","ראה ס' השיחות תש\"ב ע' 19. תש\"ה ע' 60. אגרות קודש אדמו\"ר מהוריי\"צ ח\"ט ע' תטז. מקומות שבהערה הבאה."],["19","19","ראה „התמים\" חוברת ב ע' עח [פח, ב]. לקוטי לוי יצחק — אגרות ע' שלג ואילך."],["20","20","ד\"ה ראה אנכי נותן לפניכם היום ברכה — לקו\"ת ר\"פ ראה. מאמרי אדמו\"ר האמצעי דברים ח\"ב בתחלתו (נדפס ז\"ע). ועוד. — ולהעיר שגם בדרושים הנ\"ל (בביאור הענין דנקודה בהיכלא) — נראה בגלוי הרחבת הביאור דבעל הגאולה בנקודת הענין שבלקו\"ת לאדה\"ז."],["21","21","ראה זח\"א ו, רע\"א. תקו\"ז ריש תיקון ה (יט, א). תיקון כח (עב, ב). ועוד. אגה\"ק ס\"ה (קז, א). ועוד."],["22","22","לשון הלקו\"ת שם."],["23","23","„התמים\" שם."],["24","24","לשון אגה\"ק הידועה דהבעש\"ט — נדפסה בכש\"ט הוצאת קה\"ת בתחלתו. ובכ\"מ."]]],[1300251361,"חוצה\"25: דער מאסר איז געקומען צוליב דעם קטרוג (למעלה)26 אויף זייער עבודה אין הפצת המעינות חוצה, און די גאולה האָט באַוויזן אויף זייער נצחון, אַז זיי זיינען געווען גערעכט מיט זייער מפיץ זיין מעינות החסידות חוצה27.\nואדרבה: דורך דעם מאסר וגאולה איז צוגעקומען אַ יתרון האור מן החושך — אַ תוספת גילוי והרחבה אין הפצת המעינות חוצה. כידוע די שיחה28 בנוגע לגאולת אדה\"ז בי\"ט כסלו, אַז נאָך פעטערבורג האָט זיך אָנגעהויבן דער עיקר ענין פון „יפוצו מעינותיך חוצה\". ועד\"ז איז מובן בנוגע צו די הוספה וואָס איז צוגעקומען ע\"י גאולת אדמו\"ר האמצעי ביו\"ד כסלו.\nויש לומר, אַז די הוספה והרחבה בהפצת המעינות חוצה ע\"י די גאולה פון דעם מיטעלן רבי'ן טוט אויף אַ מעלה אפילו אין די הוספה והרחבה ע\"י די גאולה פון דעם אַלטן רבי'ן29 — ע\"ד ובהתאם צו דער עילוי כללי הנ\"ל וואָס דער מיטעלער רבי האָט אויפגעטאָן אין די תורה פון דעם אַלטן רבי'ן (אפילו לאחרי גאולתו בי\"ט כסלו), אַז ער האָט אַרויסגעבראַכט די נקודת החכמה (בתורת החסידות) פון דעם אַלטן רבי'ן30 בביאור רחב, „רחובות הנהר\" פון בינה31:\nדער כללות החידוש פון הפצת המעינות חוצה ע\"י חסידות חב\"ד הויבט זיך אָן לכל לראש — מיט דער הפצה אין דעם „חוצה\" שבאדם, וואָס איז כולל — אַז די „מעינות\" (ווי זיי שטייען למעלה משכל) זאָל מען מפיץ זיין אין הבנה והשגה בשכל האדם32.\nוואָס אין דעם גופא איז צוגעקומען אַ מעלה דורך דעם מיטעלן רבי'ן (און ביי אים גופא — איז צוגעקומען נאָכמער עילוי בזה דורך זיין גאולה, כמובן מגאולת אדה\"ז), וואָס ער האָט אַראָפ־ געבראַכט נקודת החכמה פון דעם אַלטן רבי'ן אין הרחבת הביאור דבינה כו', וואָס דאָס גיט צו אין דער הפצת",[["25","25","אלא, בפרטיות — הי' הקטרוג על אדה\"ז על כללות חידושו בהפצת המעינות חוצה (ראה ס' השיחות תש\"ג ע' 59. בית רבי ח\"א פט\"ו בהערה (לא, א). לקו\"ש ח\"י ע' 223. 269. ח\"ל ע' 170), בחב\"ד שבשכל (שעד אז לא הי' ענין זה); משא\"כ הקטרוג על אדהאמ\"צ הי' בעיקר על הענין דרבי וחסיד כו' (שיחת יו\"ד כסלו תשי\"א (ס' השיחות תשי\"א ס\"ע 50). וראה אגרות קודש אדמו\"ר האמצעי (קה\"ת תש\"מ) ע' שב)."],["26","26","ונשתלשלו מהן (ראה תניא רפ\"ג) — המאסר למטה."],["27","27","וכדברי הבעש\"ט והה\"מ לאדה\"ז בהיותו במאסר (על שאלת אדה\"ז „ואם אצא מכאן האם אפסיק מלומר ד\"ח\"): כיון שהתחלת לא תפסיק ואדרבה לכשתצא תאמר יותר (בית רבי שם. נת' בלקו\"ש ח\"ל שם). — ומזה מובן גם בנוגע לגאולת אדהאמ\"צ ביו\"ד כסלו."],["28","28","ס' השיחות תורת שלום ס\"ע 112 ואילך."],["29","29","וכמובן גם מזה, שלמרות גאולת אדה\"ז, הי' אפ\"ל עוד קטרוג והעלם והסתר על הפצת המעינות חוצה ע\"י מאסר של אדהאמ\"צ. ומזה מוכח, שגם ע\"י גאולתו ניתוסף עילוי בהפצת המעינות חוצה, עילוי שלא הי' ע\"י גאולת אדה\"ז. וראה בזה ובהבא לקמן שיחת יו\"ד כסלו תשמ\"א."],["30","30","שגם לאחרי גאולתו בי\"ט כסלו היתה תורתו בבחי' נקודת החכמה בערך להרחבת הבינה דאדמו\"ר האמצעי."],["31","31","ואף שרוב תורתו של אדהאמ\"צ (באופן דהרחבה כו') נאמר ונכתב לפני גאולתו (לא כבגאולת אדה\"ז, שלאחרי הגאולה נתרחבה ונתגלתה תורתו לגבי לפני הגאולה) — הרי הכוונה היתה שילמדוה והפצתה (כדלקמן בפנים), ומבלי רדיפות וכו' מהמלכות דאז וכו' — והשלימות בזה נעשה ע\"י הגאולה."],["32","32","ראה אוה\"ת לתהלים (יהל אור) ע' תנה, שהמדות (ז\"א) נק' חוץ לגבי חו\"ב. וי\"ל, שגם המוחין נק' חוץ לגבי האמונה שלמעלה מהשכל ובפרט לגבי עצם הנפש (ראה לקו\"ת ויקרא ד, ב)."]]],[1300251362,"המעינות חוצה — (מתחיל) אין הבנה והשגה בשכל האדם33 (וואָס בינה איז „חוצה\" בערך צו חכמה).\nובפשטות: בשעת מ'לערנט אַ מאמר פון דעם אַלטן רבי'ן (חכמה) צוזאַמען מיט דעם תוספת והרחבת הביאור פון דעם מיטעלן רבי'ן (בינה) — איז דאָס כביכול געשמאַקער, און ברענגט אַרויס מער שמחה, „אם הבנים שמחה\"34 (וואָס גייט אויף בינה35 — „אם הבנים\").\nה. ועוד (ובמובן רחב יותר) ובעיקר:\nדער עיקר מאסר וגאולה (פון דעם אַלטן רבי'ן און פון דעם מיטעלן רבי'ן, ועד\"ז פון כ\"ק מו\"ח אדמו\"ר במאסר וגאולה שלו בי\"ב־י\"ג תמוז) איז געווען ניט אַזוי אויף לימוד התורה וחסידות וקיום המצות פאַר זיך (אפילו פאַר דעם „חוצה\" שבאדם עצמו, חב\"ד ומדות), נאָר אויף הפצת התורה והיהדות והפצת המעינות חוצה, אין חוצה כפשוטו — לערנען און מפיץ זיין אידישקייט און חסידות באַ אַנדערע אידן.\nובפרטיות יותר: חסידות מאָנט אַז ס'איז ניט מספיק בלויז זיין אַ „משכיל\" און לערנען תורה, כולל חסידות חב\"ד בחב\"ד שבשכל (אפילו ווען דאָס קומט אַראָפ בהרחבת הבינה), נאָר די השכלה דאַרף אַראָפקומען36 אין עבודה37 — אין מדות שבלב („חוצה\" בערך למוחין), ביז אין מחשבה ודיבור, ביז — והוא העיקר — אין מעשה בפועל („חוצה\" שאין חוצה ממנו אין דעם אדם).\nביז — אין מעשה בפועל פון הפצת המעינות חוצה, חוצה כפשוטו (מחוץ להאדם) — ביי אַנדערע אידן, כנ\"ל. וואָס די עבודה פון לערנען און מפיץ זיין מעינות החסידות ביי אַנדערע (בדבור) איז אַן ענין של עשי' בערך צו די עבודה מיט זיך.\nדאָס הייסט:\nנוסף לזה וואָס תורה בכלל זאָגט אָן אַז „לא המדרש הוא העיקר אלא",[["33","33","וידוע שאדמו\"ר האמצעי עסק וביותר בהדפסת ספרי חסידות, ובאופן שיגיעו לכאו\"א בנקל כו', ועד שהשתדל להדפיסם באופן שגם עניים יוכלו לקנותם (ראה אגרות קודש אדמו\"ר האמצעי — קונטרס המילואים (קה\"ת, תשמ\"א) ע' יג ואילך. ח\"ב ע' פא ואילך). וראה שיחת יו\"ד כסלו תשמ\"ה."],["34","34","תהלים קיג, ט."],["35","35","זהר ח\"א ריט, א. ח\"ב פד, א. פה, ב. פרדס שער ערה\"כ ערך אם הבנים. לקו\"ת שמע\"צ פח, ד. ובכ\"מ."],["36","36","בלשון וכפס\"ד המשנה „לא המדרש הוא העיקר אלא המעשה\" (אבות פ\"א מי\"ז)."],["37","37","וענין זה — כמו כל ענינים בחסידות — נמצא גם בנגלה דתורה*, כי נגלה דתורה הוא גופא לנשמתא דאורייתא (זח\"ג קנב, א): פס\"ד הרמב\"ם (בספרו „הלכות הלכות\") ש„ראוי לאדם להתבונן במשפטי התורה הקדושה ולידע סוף ענינם כפי כחו\" (סוף הל' מעילה) ו„אע\"פ שכל חוקי התורה גזירות הם כו' ראוי להתבונן בהן וכל מה שאתה יכול ליתן לו טעם תן לו טעם כו' ורוב דיני התורה אינן אלא** כו' לתקן הדעות וליישר כל המעשים\" (סוף הל' תמורה), כלומר שדיני התורה (גם חוקים וגם מצוות התלויות בכהן וכיו\"ב) לא ניתנו אלא ללמוד הוראה בעבודת ה', „לתקן הדעות וליישר כל המעשים\". *) אלא שחסידות גילתה ופירשה הענין (ע\"ד „ופירש הבעש\"ט\" (שעיהו\"א פ\"א) בענין „לעולם ה' דברך נצב בשמים\" (תהלים קיט, פט) — שנאמר לפני זה במדרש תהלים (עה\"פ. וראה לעיל ע' 331 הערה 29. וש\"נ). ועד\"ז בענין השגחה פרטית (ראה אוה\"ת לתהלים (יהל אור) ע' קלב. סה\"מ תרע\"ח ע' תיג. תרפ\"ו ע' קנו ואילך. ועוד. וראה לקו\"ש ח\"ל ע' 149־50] אבל לאחרי הגילוי ע\"י תורת החסידות אפשר למצוא כל הענינים בנגלה דתורה. **) ולשון זה מורה דהוא לעיכובא (ראה מנחות פג, ב בתוד\"ה מתני')."]]],[1300251363,"המעשה\"36, ונוסף אויף די הדגשה גדולה אין חסידות, אַז ס'איז ניט גענוג אמונה בלבד, נאָר עס דאַרף אַראָפ־ קומען אין הבנה והשגה שבשכל (כנ\"ל) — איז אָבער אויך ניט גענוג השכלה בלבד, און ניט גענוג די כוונות און אפילו עבודה רוחנית (ניט קוקנדיק אויף דעם גודל העילוי שבזה), נאָר יעדער השכלה דאַרף אַראָפקומען אין אַ „בכן\"38 (ניט נאָר אַ מסקנא והלכה שבשכל, נאָר) אין עבודה ומעשה בפועל בגשמיות העולם. ואדרבה: אַ משכיל גדול — דאַרף זיין אַן עובד גדול, און וואָס גרע־ סער דער משכיל — אַלץ מער דאַרף צוקומען אין זיין עבודה, וי\"ל אַז לפעמים איז צוליב דעם (עבודה) איז עס געגעבן געוואָרן די השכלה!\n[ויש להוסיף ביאור בזה ע\"פ המבואר בתניא39, אַז אַלע גילויים דלעתיד לבוא זיינען „תלוי במעשינו ועבודתינו40 כל זמן משך הגלות\": וויבאַלד אַז הפצת המעינות חוצה ברענגט אתי מר דא מלכא משיחא41 — דעריבער שטייט דאָרט בהדגשה יתירה דער הכרח אויף מעשה ועבודה בפועל, ווייל אין דעם („מעשינו ועבודתינו\"<sup data-n=\"42\">42</sup> איז תלוי אַלע גילויים דלעתיד לבוא].\nונוסף על כל זה — איז צוגעקומען אַ הוספה והרחבה אין דעם הכרח אויף עבודה ומעשה בפועל דורך די גאולה פון דעם אַלטן רבי'ן בי\"ט כסלו, וואָס איז אַ גאולה והרחבה (וועלכע קומט נאָך דעם קטרוג ומאסר) בעיקר אין דעם ענין פון הפצת המעינות חוצה (ניט אַזוי פאַר זיך אַליין) בעבודה ומעשה בפועל, בעיקר — צו אַנדערע אידן.\nאון אין דעם גופא איז צוגעקומען נאָכמער עילוי דורך די גאולה פון דעם מיטעלן רבי'ן ביו\"ד כסלו (און נאָכמער — דורך די גאולה פון כ\"ק מו\"ח אדמו\"ר בי\"ב־י\"ג תמוז) — זייענדיק ספירת הבינה:\nבשרש הענינים (אין מוחין עצמן) איז חכמה שייך לעצמו און בינה שייך להזולת43, ד.ה. אַז בערך צו נקודת החכמה איז בינה דער שרש ומקור אויף עבודה ועשי' און שייכות עם הזולת: בינה ברענגט אַראָפ נקודת החכמה אין הבנה והשגה בפרטים ופרטי פרטים. וואָס דאָס ערמעגלעכט אַז מ'זאָל קענען מסביר זיין דעם דבר שכל צו אַ צווייטן, משא\"כ בשעת עס לייכט נאָר נקודת החכמה, איז דאָס נאָר אַ נקודה בלבד, וואָס האָט אָבער ניט קיין תפיסא בהסברה ומשלים וואָס מ'קען איבער־ געבן אַ צווייטן.\nאון פון חכמה ובינה ווערט נשתלשל בפרטיות יותר (אין דעם חילוק צווישן) מוחין און מדות: מוחין איז שייך לעצמו, און מדות איז שייך להזולת. וואָס דער־ פאַר איז בינה דער מקור המדות, „אם הבנים\", ווייל תולדות המדות איז דוקא מהתרחבות השכל בבינה וואָס איז שייך להזולת44 (משא\"כ פון חכמה עצמה וואָס",[["38","38","ראה סה\"מ קונטרסים ח\"א קצה, סע\"א ואילך. ה'ש\"ת ע' יא. תש\"א ע' 57. ס' השיחות ה'ש\"ת ע' 44 ואילך. תש\"ג ס\"ע 66 ואילך."],["39","39","רפל\"ז."],["40","40","לכאו' כצ\"ל [ועבודתינו — ביו\"ד] כמו „במעשינו\" הסמוך לו."],["41","41","אגה\"ק דהבעש\"ט הנ\"ל הערה 24."],["42","42","„מעשינו\" — מלשון כפי' (ראה לקו\"ת בחוקותי מח, א. מאמרי אדמו\"ר האמצעי ויקרא ח\"ב ע' תשסא. ועוד), „ועבודתינו\" מלשון עיבוד עורות (תו\"א משפטים עו, א)."],["43","43","ראה תו\"א לך יא, ג. תו\"ח שם פא, ב ואילך. לקו\"ת חוקת נז, ד. ובכ\"מ."],["44","44","ובפרט בחי' תבונה (שבבינה) אותיות בן ובת שהן דחילו ורחימו (מדות שבבינה) — תניא ספט\"ז בהג\"ה. מזח\"ג (אדר\"ז) רצ, ב. ע\"ח שער הזווגים"]]],[1300251364,"איז למעלה פון השגה ושייכות להזולת לא ילדו המדות)45.\nביז אַז דערפון (פון בינה) ווערט נשתלשל (למטה מטה) — עבודה ומעשה בפועל46, ביז אויך — עם הזולת, כולל — הפצת המעינות חוצה, צו אַנדערע אידן.\nועפ\"ז יש לומר, אַז דורך דער גאולה פון דעם מיטעלן רבי'ן (אַ גאולה אין בינה) איז צוגעקומען אַ הוספה והרחבה אין עיקר כוונת (המאסר ו)הגאולה — הפצת המעינות חוצה בעבודה ומעשה בפועל47, ובמיוחד — צו אַנדערע אידן48.\nו. אין דעם לימוד פון יו\"ד כסלו קומט צו נאָכמער תוקף בשעת מ'פאַר־ בינדט עס מיט אַ התוועדות פון כמה וכמה מישראל49 — וואָרום אַ התוועדות מטרתה דעם זעלבן תוכן וכוונה ווי די גאולה — הפצת המעינות חוצה (ניט פאַר זיך, נאָר) ברבים און במעשה בפועל (וואָס אויף דעם איז געווען דער קטרוג ומאסר וגאולה, וכנ\"ל):\nלכל לראש — די עצם זאַך אַז אידן קלייבן זיך צוזאַמען, איז אַ הפצה ברבים, וואָס פאַרשטאַרקט אהבת ישראל ואחדות ישראל (ובפרט אַז ס'איז אויך דאָ „גדולה לגימה שמקרבת\"<sup data-n=\"50\">50</sup>. און",[["","","פ\"ד. שער אח\"פ פ\"א. מאו\"א ת, ז. וראה ביאורי הזהר להצ\"צ ע' תקכ ואילך."],["45","45","דרושי פ' ויצא (פרשתנו): ביאורי הזהר ריש פרשתנו. ד\"ה ויצא תר\"ל, תר\"פ, תרפ\"ז, ועוד. וראה לקמן סעיף ז־ח."],["46","46","ראה הערה 49."],["47","47","ולהעיר משיחת יו\"ד כסלו תש\"ז (לקו\"ד ח\"ג תפז, ב ואילך) — לפני ארבעים שנה — שמבאר גודל ההכרח שכל השכלה תבוא בעבודה בפועל. עיי\"ש."],["48","48","ועפ\"ז יש להוסיף בהשייכות דגאולת אדה\"ז בי\"ט כסלו וגאולת אדהאמ\"צ ביו\"ד כסלו — לימי חנוכה, בסיום חודש כסלו (נוסף להמבואר בכ\"מ): גם נס חנוכה ונצחון החשמונאים הי' על התנגדות היונים לא לענין ההשכלה שבתורה בלבד, כי אם „להשכיחם תורתך ולהעבירם מחוקי רצונך\", וכתוצאה מזה — ההכרח דעבודה ומעשה בפועל, כולל הפצת התומ\"צ גם אצל הזולת. ולזה קבעו הנס בנרות — שמדליקים על פתח ביתו מבחוץ, להאיר ב„נר (משלי ו, כג) מצוה ותורה אור\"* (ובפרט פנימיות התורה, שמן** שבתורה (אמרי בינה ש' הק\"ש פנ\"ד ואילך)) גם בחוץ, וע\"י מנורה שכל שבעה קני המנורה (כנגד שבעה סוגים דישראל — לקו\"ת ר\"פ בהעלותך. שערי אורה ד\"ה כי עמך פ\"ד. ובכ\"מ) הם „מקשה אחת\" (תרומה כה, לו), וממנה יוצאה אורה לכל העולם כולו (ראה מנחות פו, ב. ויק\"ר פל\"א, ז. ירוש' ברכות פ\"ד ה\"ה), וי\"ל גם לאוה\"ע. *) ראה בכ\"ז מאמרי אדה\"ז תקס\"ג ע' נז. שערי אורה ד\"ה בכ\"ה בכסלו פמ\"א־מב. פנ\"ג. סהמ\"צ להצ\"צ מצות נ\"ח (עא, א. שם, סע\"ב ואילך). וראה לעיל ע' 237 ואילך. **) ולהעיר מדברי אדמו\"ר מהורש\"ב נ\"ע אשר הקטרוגים וכו' והגאולה די\"ט כסלו הוא ע\"ד דע\"י שכותשין אותו הזית נותן שמנו (ס' השיחות תורת שלום ע' 26)."],["49","49","להעיר מלקו\"ד שם (תפח, ב), שיו\"ד כסלו הוא זמן הלידה של חסיד, וענין הלידה של חסיד הוא התוועדות חסידית. ויש לומר השייכות, כי לידה הו\"ע הגילוי בעולם גם להזולת (ולא כעובר במעי אמו), וזהו גם ענין ההתוועדות — גילוי לרבים. ובספירות — ספירת הבינה הו\"ע הלידה וגילוי שבמוחין מנקודת החכמה שהיא בבחי' העלם. כי אף שבכללות מוחין הן בחי' עיבור ומדות בחי' לידה והתגלות (תניא פט\"ז בהג\"ה הא'. ביאורי הזהר לאדהאמ\"צ קג, סע\"א ואילך. קמה, ג. להצ\"צ (כרך ב') ע' תתקצג ואילך. הנסמן בליקוט פירושים כו' לתניא שם) — הרי במוחין עצמן בינה היא בחי' (עיבור ואח\"כ) לידה (גילוי) בערך לחכמה, כי מקור המדות הוא מהולדת המדות שבבינה (תבונה), הנק' „תעלומות לב\" (תניא שם. אגה\"ת ספ\"ד. לקו\"ת מסעי צ, א), בחי' „בינה לבא\" (קיצורים והערות לתניא שם. וראה אוה\"ת יתרו ע' תתנו ואילך), וראה הערה 44. ועד שאפשר להיות שבחי' תבונה זו מתלבשת במעשה דבור ומחשבת התורה ומצותי' כו' כאלו עסק בהם בדחילו ורחימו ממש אשר בהתגלות לבו (תניא שם). וראה הג\"ה הב' בתניא שם ש„לפעמים התבונה יורדת להיות מוחין בנוק' דזעיר אנפין שהן אות' התורה והמצות\"."],["50","50","ראה סנהדרין קג, סע\"ב ואילך."]]],[1300251365,"האָט אין זיך אַן עילוי הכי גדול — כח הציבור51, נוסף אויף דעם וואָס (נאָר) „איש את רעהו יעזרו ולאחיו יאמר חזק\"52. דער גאַנצער (כח ה)ציבור העלפט, ובפרט לויט די „פתקא אשר משמי שמיא נחיתא\" וואָס דער אַלטער רבי האָט איבערגעגעבן53 וועגן דעם גודל העילוי פון אַ חסידישען פאַר־ ברענגען, אַז דאָס טוט אויף מער וויפל עס קען אויפטאָן מלאך מיכאל, שרם של ישראל54, און שאַפט נחת רוח — און במילא אַן אחדות מיט — אבינו שבשמים.\nועוד ועיקר: די כוונה פון דער התוועדות איז, אַז דורך דעם זאָל צוקומען אַ הוספה והרחבה אין הפצת התורה והיהדות בכלל, ובמיוחד הפצת המעינות חוצה בעבודה ובמעשה בפועל, אַזוי אַז דאָס זאָל דערגרייכן בפועל אויך צו אַנדערע אידן.\nאון דוקא דאָס איז די בחינה (אויס־ פרואוו) אַז מ'האָט זיך באמת משתתף געווען אין דער התוועדות און ס'איז ניט געווען אַ דמיון בעלמא — בשעת עס זעט זיך אָן אויף דעם מתוועד אַ שינוי בהנהגתו בפועל (אַלס תוצאה פון דער התוועדות) אין זיין עבודה פון הפצת המעינות חוצה במעשה בפועל, אַזוי אַז מ'קען אָנווייזן מיטן פליישיקן פינגער בעוה\"ז הגשמי די הוספה אין הפצת המעינות חוצה! אויב מ'קען דאָס ניט אָנווייזן, איז אַ ספק צי מ'איז טאַקע געווען באַ דער התוועדות באמיתית, וואָרום דאָס איז די כוונה פון דער התוועדות — דאָס צוגעבן אַ הוספה אין מעשה בפועל.\nער (ל' נסתר) קען האָבן אַ תירוץ אַהער און אַ תירוץ אַהין — אָבער „כמאן דעבד לא אמרינן\"55 (אפילו ווען „אונס (וואָס) רחמנא פטרי'\"<sup data-n=\"56\">56</sup>, די עבודה בפועל פעלט.\nעאכו\"כ ווען דאָס איז אַ התוועדות ביו\"ד כסלו — וואָס דאָס (גאולה שני') גיט אַ כפל'דיקע הדגשה אויף דעם הכרח פון הפצת המעינות חוצה במעשה ועבודה בפועל.\nז. דאָס אַלעס שטייט נאָכמער בהדגשה מצד דעם וואָס די התוועדות (למחרת יו\"ד כסלו) איז בשבת פ' ויצא57 — הן מצד כללות הפרשה, והן מצד דעם שיעור חומש הפרטי פון יום השבת (שביעי עד סוף פ' ויצא):\nחסידות איז מבאר דעם פירוש אין „ויצא יעקב מבאר שבע וילך חרנה\" — אַז דאָס גייט אויף דער יציאה פון יעקב, יו\"ד עקב (בחי' חכמה) למטה מטה גם בבחי' עקביים58. וואָס די יציאה וירידה איז דורך „באר שבע\" — בחי' בינה, מקור השבע מדות59. ד.ה. אַז „ויצא",[["51","51","ראה ד\"ה החלצו תרנ\"ט פ\"י (סה\"מ תרנ\"ט ע' סא). ועוד."],["52","52","ישעי' מא, ו."],["53","53","הובא במכתב כ\"ק מו\"ח אדמו\"ר (קובץ מכתבים שבסו\"ס תהלים אהל יוסף יצחק ע' 198 ואילך. אגרות קודש שלו ח\"ג ע' תיג ואילך)."],["54","54","ראה דניאל י, כא. שם יב, א. ועוד."],["55","55","ירושלמי קידושין פ\"ג ה\"ב."],["56","56","ב\"ק כח, ב."],["57","57","עוד שייכות — ראה לעיל ע' 159 ואילך."],["58","58","תו\"א ותו\"ח ריש פרשתנו. אוה\"ת שם קצב, א ואילך. מאמרי אדה\"ז תקס\"ח (כרך ב) ע' תרכו ואילך. וראה מקומות שבהערה 62."],["59","59","ולהעיר שבפרשתנו מסופר גם שלאה ילדה ששה בנים ובת אחת, שהו\"ע הולדת שבע מדות (ז\"א ומלכות) מבחי' בינה (לאה) (ראה פרדס שבהערה 35. תו\"ח פרשתנו כט, ב. אוה\"ת חנוכה רחצ, ב. מאמרי אדה\"ז תקס\"ה (כרך ב) ס\"ע תשפח)."]]],[1300251366,"יעקב מבאר שבע\" מיינט יציאת בחי' חכמה פון בחי' בינה60, מקור המדות (באר שבע), צו מאיר זיין אין מדות, ביז למטה מטה אין עולמות בי\"ע, „חרנה\"61.\nדער ענין איז אויך דאָ באַ יעדער אידן: יציאת יעקב מבאר שבע לחרן גייט אויף ירידת הנשמה בגוף62, די נשמה וואָס נעמט זיך מבחי' חכמה (ולמעלה מזה), איז יוצא מבחי' בינה אין די מדות, ביז אין עולמות בי\"ע, ביז אַ נשמה בגוף בעוה\"ז הגשמי.\nובעבודת האדם — די עבודה ונתינת כח פון דעם מיטעלן רבי'ן: לימוד התורה באופן פון נקודת החכמה דאַרף אַראָפקומען אין הבנה והשגה בהרחבה פון בינה. און דערפון דאַרף די השכלה והבנה נמשך ווערן אין מדות, ביז אין מחשבה דיבור ומעשה ביז אין עבודה בעלמא דפרודא, רשות הרבים 63 — הפצת המעינות חוצה.\nח. ויש לומר עוד:\nפון כללות יציאת וירידת יעקב אבינו „מבאר שבע\" אין „חרנה\" ווערט נשתלשל (לאחרי כמה צמצומים והעלמות כו') אויך אַלע ירידות אין גלות64. כולל אויך דעם מאסר וגלות (בתוך גלות) פון דעם מיטעלן רבי'ן. אָבער די כוונה בכל ירידות אלו איז — ירידה צורך עלי', אַז דורך דער ירידה פון חכמה אין בינה, אין מדות, אין מעשה בפועל ביז אין די עבודה אין „חוצה\" (מיט אַנדערע אידן) און אין גלות — זאָל צוקומען אַ גאולה ועלי' נעלית יותר, די גאולה פון דעם מיטעלן רבי'ן, וואָס טוט אויף אַ הרחבה והתפשטות אין הפצת המעינות חוצה, ביז שלימות העלי' — בגאולה האמיתית והשלימה, שאין אחרי' גלות65.\nויש לומר, אַז די צוויי ענינים — דער מאסר וגלות (די ירידה פון „באר שבע\" אין „חרן\"), און די גאולה ועלי' וואָס קומט דורך דעם אַרויס — זיינען מרומז אין תחלת הפרשה און סוף הפרשה: בתחלת הפרשה רעדט זיך וועגן דער ירידה — „ויצא יעקב מבאר שבע וילך חרנה\"; דערנאָך בהמשך הפרשה רעדט זיך וועגן עבודת יעקב בפועל אין „חרן\" (גלות); און בסוף הפרשה רעדט זיך וועגן סיום וגמר עבודת הבירורים אין גלות — ווי יעקב ווערט געראַטעוועט פון לבן הארמי אין חרן, און „ויעקב הלך לדרכו ויפגעו בו מלאכי אלקים גו' ויקרא שם המקום ההוא מחנים\"66, וואָס דערפון ווערט נשתלשל דער סיום וגמר העבודה פון כל גלות וגלות, אויך דער גלות (מאסר) פון דעם מיטעלן רבי'ן.\nוהענין בזה:\n„ויפגעו בו מלאכי אלקים\" מיינט „מלאכים של ארץ ישראל באו לקראתו ללותו לארץ\", ד.ה. אַז די מלאכים פון ארץ ישראל זיינען געקומען אין חוץ",[["60","60","ויש לומר, ש„ויצא\" קאי גם על היציאה מחכמה לבינה."],["61","61","ובפרטיות יותר — כפירוש השני בזהר (פרשתנו קמו, ב ואילך. וראה ביאוה\"ז לאדהאמ\"צ (יז, ד) ולהצ\"צ ריש פרשתנו. מקומות שבהערה הבאה) ב„ויצא יעקב מבאר שבע וילך חרנה\", שהיציאה היא מ„באר שבע\", בחי' מלכות, לעלמא דפרודא."],["62","62","ד\"ה ויצא תר\"ל, תר\"פ, תרפ\"ז. ועוד."],["63","63","ראה תניא ספל\"ג. ועוד."],["64","64","ראה ב\"ר פס\"ח, יג. רמב\"ן ריש פרשתנו מפדר\"א (פל\"ה — ונשמט בפדר\"א שעם פירוש הרד\"ל!). וראה בארוכה לעיל ע' 153 ואילך. וש\"נ."],["65","65","ראה מכילתא בשלח טו, א. הובא בתוד\"ה ה\"ג ונאמר — פסחים קטז, ב. ועוד."],["66","66","פרשתנו לב, ב־ג."]]],[1300251367,"לארץ67. און „ויקרא שם המקום ההוא מחנים\" (ל' רבים), „שתי מחנות של חוצה לארץ שבאו עמו עד כאן ושל ארץ ישראל שבאו לקראתו\".\nובעבודה: דער גמר העבודה פון יעקב אבינו אין גלות (בחוץ לארץ)68 איז געווען — צו מאַכן דאָרט „ארץ ישראל\"69, ועד כדי כך אַז ער האָט גע־ פועל'ט אַז „מלאכים של ארץ ישראל באו לקראתו (בחוץ לארץ) ללותו לארץ\". און נאָכמער: דאָס האָט ניט מבטל געווען די מציאות פון חוץ לארץ, נאָר ער האָט מחבר געווען די מציאות פון חוץ לארץ מיט די מציאות פון ארץ ישראל — „ויקרא שם המקום ההוא מחנים\", על שם די „שתי מחנות של חוצה לארץ שבאו עמו עד כאן ושל ארץ ישראל שבאו לקראתו\".\nדער לימוד דערפון איצטער: דער גמר ושלימות העבודה פון גלות אדמו\"ר האמצעי און פון גלות זה האחרון בכלל איז די עבודה פון „מאַך דאָ ארץ ישראל\". וואָס דאָס איז דער כללות העבודה פון הפצת המעינות חוצה: „ויצא\", ניט בלייבן במקומו (בדרגתו ובמצבו הרוחני — נאָר להעלות בקודש), די יציאה והתפשטות מנקודת החכמה בהרחבת הבינה, ביז אין מדות, אין מחשבה דיבור ומעשה, ביז „ויצא\" בפשטות — אַרויסגיין און מפיץ זיין די מעינות חוצה אויך באַ אַנדערע אידן, אַזוי אַז מ'מאַכט „דאָ\" אין „חוצה\" — „ארץ ישראל\".\nט. דער לימוד פון דעם אַלעם בנוגע לפועל:\nדי התוועדות בקשר מיט יו\"ד כסלו און בש\"פ ויצא דאַרף צוגעבן אַ הוספה והרחבה מער וויפל ס'איז געווען ביז איצטער (כנ\"ל אַז „הימים האלה נזכרים ונעשים\" באופן פון מעלין בקודש) — אין אַרויסגיין („ויצא\") טאָן אין הפצת התורה והיהדות והפצת המעינות חוצה בעבודה ובמעשה בפועל, ד.ה. ניט נאָר אין אַ הוספה בלימוד החסידות בהרחבה והבנה והשגה דבינה, נאָר אויך אין עבודה ומעשה בפועל באַ זיך אַליין, ועוד ועיקר — אַ הרחבה אין די עבודה פון הפצת התורה והיהדות און המעינות חוצה אויך צו אַנדערע אידן.\nובמיוחד — שטייענדיק אין די טעג פון חודש כסלו — שהחיתום70 שלו חנוכה. — אין די הכנות צו מבצע חנוכה, זען אַז יעדער איד בכל מקום ומקום זאָל צינדן נרות חנוכה און מקיים זיין די אַנדערע מצוות פון חנוכה.\nולפני זה — מאַכן די פאַסיקע הכנות צו י\"ט כסלו (ולפנ\"ז — צו חמשה עשר בחודש, קיימא סיהרא באשלמותא): פון דעם שבת מתברכין כולהו יומין71, די ימי המעשה וואָס זיינען אַ הכנה צו דעם קומענדיקן שבת, וואָס למחרתו איז י\"ט כסלו. ובפרט אַז ס'איז אויך יו\"ד כסלו (וואָס טוט אויף אַן עלי' אויך אין י\"ט כסלו, כנ\"ל). האָט מען אַ נתינת כח פון דעם שבת ויו\"ד כסלו צו מאַכן די אַלע",[["67","67","ראה מפרשי רש\"י כאן. רמב\"ן כאן. וראה לעיל שם (ע' 150). וש\"נ."],["68","68","ראה לעיל שם ע' 153 ואילך."],["69","69","כפתגם הצ\"צ הידוע על שאלת חסיד א' ע\"ד הנסיעה לארץ ישראל: „מאַך דאָ ארץ ישראל\" (אגרות קודש אדמו\"ר מהוריי\"צ ח\"א ע' תפה ואילך). ומזה מובן במכש\"כ וק\"ו בנוגע לעבודת יעקב אבינו, ובפרט שיעקב הי' לפני כיבוש ארץ ישראל, שע\"י הכיבוש נקבעה קדושת הארץ (אף שנתינת ובעלות הארץ היתה מזמן אברהם. — ראה לקו\"ש חט\"ז ע' 205 ואילך. לעיל שם ע' 152־3)."],["70","70","והכל הולך אחר החיתום (ברכות יב, א)."],["71","71","זח\"ב סג, ב. פח, א."]]],[1300251368,"פאַסיקע הכנות אין די קומענדיקע טעג צו איינאָרדענען אַז בי\"ט כסלו (אָדער בסמיכות לו) זאָלן זיין התוועדויות בכל מקום ומקום, וואו מ'זאָל זיך אַלע צוזאַ־ מען שטאַרקן אין טאָן די עבודה ומעשה בפועל פון הפצת המעינות חוצה בכל מקום ומקום.\nכולל ובמיוחד — שטורעמען, און אַראָפברענגען דעם שטורעם לפועל, צו מרחיב זיין (אָדער אויפשטעלן מחדש) אַ „בית חב\"ד\"72 בכל מקום ומקום (כמדובר לאחרונה בארוכה<sup data-n=\"73\">73</sup>.\nוהיות אַז עס זיינען איצטער דאָ אַזוינע וואָס פאָרן נאָך שבת (ניט אום שבת גערעדט) צו אַנדערע ערטער קודם י\"ט כסלו — זאָלן זיי אַריינגיין אין „מזכירות\"74 נאָך שבת און דאָרט נעמען משקה — אַ דבר גשמי — פון דער התוועדות ביו\"ד כסלו, במקום שמגדלין בו תורה ותפלה וצדקה פון כ\"ק מו\"ח אדמו\"ר (ממלא מקומו פון דעם בעל הגאולה), פון וואַנעט ער האָט אַרויס־ געשיקט שלוחים בכל העולם כולו צו מפיץ זיין תורה ויהדות בכלל און די מעינות חוצה. און מיט די משקה זאָלן זיי מאַכן אַ התוועדות במקומם, און שטורעמען על מנת להביא בפועל, אין כל הענינים האמורים לעיל.\nיוד. דער עיקר איז — כמדובר לעיל בארוכה — אַז כל האמור לעיל זאָל אַראָפקומען אין מעשה ועבודה בפועל ממש, אָן קיינע פשט'לעך!\nאון אע\"פ אַז מעשה ועבודה (אָנ־ הויבנדיק פון „ויצא\" — ממשיך זיין מנקודת החכמה אין הרחבת הבינה, און דערנאָך אין מדות, ביז אין מחשבה דיבור ומעשה, ביז די עבודה ומעשה פון הפצת המעינות חוצה צו אַנדערע אידן) פאָדערט אַ יגיעה גדולה („מעשה\" מלשון כפי', און עבודה מלשון „עיבוד עורות\"<sup data-n=\"75\">75</sup>, כמאחז\"ל76 „לא יגעתי ומצאתי אל תאמין כו', יגעתי ומצאתי תאמין\" — האָט מען דעם כלל אַז „אדם לעמל יולד\"77 און „איני מבקש כו' אלא לפי כחן\"78, ניט לפי כח כלל ישראל, נאָר לפי „כחן\", כחו של כאו\"א בפרט.\nאון מ'דערציילט וועגן דעם (די שוועריקייט פון מעשה ועבודה) יעדער אידן (ניט בכדי פועל'ן אַ נמיכת רוח ח\"ו, נאָר אדרבה —) בכדי אַרויסרופן אַ שמחה בשעת מ'דערוויסט זיך אַז ניט קוקנדיק אויף די שוועריקייטן אין די עבודה ומעשה, איז דאָס בכחו של כאו\"א79, און מ'האָט געגעבן יעדערן דעם זכות („לזכות את ישראל\"<sup data-n=\"80\">80</sup> ואחריות צו דאָס קענען מקיים זיין בפועל, וכדבעי81.\nאון נאָכמער: אע\"פ וואָס דאָס פאָ־ דערט טאַקע אַ יגיעה גדולה — בשעת",[["72","72","רמז לזה בפרשתנו (כח, כב) — „והאבן הזאת אשר שמתי מצבה יהי' בית אלקים\"."],["73","73","ראה לעיל ע' 338. וש\"נ."],["74","74","והעיקר — „להכנס\" בעניני זכור וזכרון (עיין הל' ת\"ת לאדה\"ז פ\"ב סוס\"י. דרושי פ' זכור. ועוד)."],["75","75","נסמן לעיל הערה 42."],["76","76","מגילה ו, ריש ע\"ב."],["77","77","איוב ה, ז. סנהדרין צט, ב."],["78","78","במדב\"ר פי\"ב, ג."],["79","79","וכמודגש גם בפרשתנו, שתיכף בתחלת העבודה (יציאת יעקב מבאר שבע) מבטיח לו הקב\"ה „והנה אנכי עמך ושמרתיך בכל אשר תלך והשיבותיך אל האדמה הזאת גו'\" (כח, טו), ומשום זה „וישא יעקב רגליו\", „משנתבשר בשורה טובה שהובטח בשמירה נשא לבו את רגליו ונעשה קל ללכת\" (כט, א ובפרש\"י)."],["80","80","משנה מכות כג, ריש ע\"ב."],["81","81","ראה כתובות סז, רע\"א."]]],[1300251369,"אָבער אַ איד איז זיך מתבונן אין דעם וואָס ער טוט אויף דורך די עבודה ביגיעה, ווערט דאָס פאַר אים ניט קיין טירחא וצער, נאָר אדרבה — אַ שמחה גדולה. ע\"ד משל ווי די יגיעה פון טראָגן אַ משא של אבנים טובות ומרגליות. פאַרשטייט יעדערער, אַז פאַר אים איז די גרעסטע שמחה (ועאכו\"כ ניט קיין צער) צו טראָגן די שווערע משא — אַבי ער קען צו זיך אַריינ־ טראָגן די אבנים טובות ומרגליות. ער פרעגט זיך גאָר ניט נאָך וויפל וועגט די משא, אדרבה: ער פרעגט וויפל אבנים טובות ומרגליות זיינען פאַראַן, און אויב מ'ענטפערט אים צוויי מאָל אַזויפיל וויפל ער האָט זיך פאָרגעשטעלט — האָט ער ניט צוויי מאָל אַזויפיל צער, נאָר צוויי מאָל אַזויפיל שמחה!\nובפרט, אַז בדורנו זה האָט מען שוין די הבטחה פון כ\"ק מו\"ח אדמו\"ר82, אַז היינט דאַרף מען שוין ניט אָנקומען צו אַן עבודה ויגיעה גדולה בהנ\"ל, און אין „הימים האלה נזכרים ונעשים\" — וואָרום אַלץ איז שוין היינט צוגעגרייט, עס דאַרף נאָר זיין „עמדו הכן כולכם\", שטיין מיט אַ תוקף (עמדו), און צוגע־ גרייט (הכן), און צוזאַמען מיט אַנדערע אידן (כולכם) — באַקומט יעדערער אַלע השפעות והמשכות.\nועאכו\"כ אַז היינט איז ניט מוכרח עבודת הבירורים וואָס קען גורם זיין צער [וואָרום המברר מוז זיך מתלבש זיין בלבושי המתברר83, והמתאבק עם כו'84, במילא דאַרף זיין אַ יגיעה מתוך צער, און דערנאָך זיך טובל זיין אין אַ מקוה, „אָפוואַשן\" דעם דבר בלתי רצוי וואָס האָט זיך צו אים צוגעקלעפט דורך טבילה במי המקוה, אָדער בדמעות, אָדער בתורה (מי הדעת הטהור<sup data-n=\"85\">85</sup>], נאָר יגיעה ועבודה בקדושה עצמה86 (ע\"ד משא של אבנים טובות ומרגליות).\nאון אפילו די עבודה וואָס דאַרף יע זיין — באַשטייט נאָר פון „צופוצן די קנעפלעך\"87: די קאָפ און האַרץ זיינען שוין „צוגעפוצט\", ואפילו הלבושים — אַ איד דאַרף אָבער האָבן תכלית השלימות — דאַרף ביי אים אויך זיין צוגעפוצט די קנעפ פון די לבושים החיצוניים88.",[["82","82","במכתבו — נדפס בסה\"מ קונטרסים ח\"ב שצז, ב. אגרות קודש שלו ח\"ד ע' רעט."],["83","83","ראה ד\"ה פדה בשלום לאדמו\"ר האמצעי (בשערי תשובה ח\"א) פ\"ד. ד\"ה ולאחותו הבתולה תרכ\"ז, תרכ\"ט. סה\"מ תרנ\"ט ע' קסב. תש\"ד ע' 106 ואילך. ועוד."],["84","84","תניא ספכ\"ח."],["85","85","ראה רמב\"ם הל' מקואות בסופן."],["86","86","ראה תו\"א ותו\"ח ר\"פ שמות."],["87","87","שיחת שמח\"ת תרפ\"ט (סה\"ש תרפ\"ט ע' 42)."],["88","88","ע\"ד וכדוגמת הביהמ\"ק (שכל א' מישראל הוא בדוגמת המקדש, „ושכנתי בתוכם\" (תרומה כה, ח) — „בתוך כאו\"א\" (ראה ראשית חכמה שער האהבה פ\"ו קרוב לתחלתו. אלשיך תרומה שם. של\"ה חלק תושב\"כ פ' תרומה שכה, ב. שכו, ב. ועוד) — שכל פרט שבו צ\"ל בתכלית השלימות, ואין עניות במקום עשירות (תמיד כט, א. וראה אנציקלופדי' תלמודית (כרך א) ערך „אין עניות במקום עשירות\". וש\"נ), ולא רק בקדש הקדשים (בדוגמת „צופוצן\" המוח והלב) כו', אלא גם בכל פרט ופרט, עד שמשקין הבהמה קודם (ולכאורה מחוץ למקום) שחיטתה בכוס של זהב (תמיד שם). וענינו בעבודה (ראה לקו\"ד ח\"ד תשכ, א): משקין הבהמה משום סירכא על הריאה (ביצה מ, א ובפרש\"י. יו\"ד סל\"ט סי\"ב ובש\"ך שם ס\"ק לב), שיכול לעכב נענוע הריאה ונשימת הבהמה, וע\"י ההשקאה מסירים הסירכא. וברוחניות: התלבשות הנפש אלקית בנפש הבהמית נקרא בשם סרכות הריאה, שהריאה נסרכת ודבוקה ומושרשת עד שאינה יכולה להניף על הלב (לקו\"ת ר\"ה סב, א. וש\"נ), ולזה משקין הנפש הבהמית כדי להסיר סרכות הריאה, שמעכבין נשימת רוח חיים של הנה\"ב (מנפש האלקית), שנשתלשל מ„ויפח באפיו נשמת חיים\" (בראשית ב, ז), מאן דנפח מתוכי' נפח"]]],[1300251370,"און בשעת מ'פאַרענדיקט דעם צופוצן די קנעפ — קומט גלייך די גאולה.\nאון נאָכמער: ווי ס'איז מבואר אין די דרושים פון פ' וישלח89 (וואָס מ'גייט באַלד לייענען) — אַז יעקב אבינו איז שוין געווען גרייט צו דער גאולה, און מצדו איז עשו אויך געווען גרייט, נאָר מפני סיבות האָט זיך דאָס דעמולט באַ עשו'ן פאַרהאַלטן; אָבער איצטער, לאחרי וואָס „כלו כל הקיצין\"90, איז אַ דבר ברור אַז אויך אוה\"ע מצדם זיינען צוגעגרייט צו דער גאולה, מ'דאַרף נאָר האָבן אַז אַ איד זאָל דאָס אים מודיע זיין און אויפשטורעמען — קומט גלייך די גאולה, „מיד הן נגאלין\"91,\nובפרט דורך די הוספה אין הפצת המעינות חוצה וואָס איז בכחו של כל או\"א בפרט, וואָס ברענגט קאתי מר דא מלכא משיחא, די גאולה כללית — ע\"ד ובדוגמא ווי דער בעל הגאולה, אַ יחיד לכאורה, איז אויך „הנשיא הוא הכל\", און האָט גע'פועל'ט אַז ער זאָל נגאל ווערן לעיני כל העם,\nגיט ער כח לכאו\"א מישראל צו אויפ־ טאָן באַ זיך זיין גאולה הפרטית, ולהקדים די גאולה הכללית (ע\"י הפצת המעינות חוצה),\nבמהרה בימינו ממש ובשמחה ובטוב לבב.",[["","","(תניא רפ\"ב ואגה\"ק סט\"ז בשם הזהר. וראה לקו\"ש חי\"ט ס\"ע 437. וש\"נ). וגם עבודה זו צ\"ל „בעשירות\", בתכלית השלימות — בכלי זהב (בדוגמת „צופוצן די קנעפ\")."],["89","89","בתו\"א ותו\"ח."],["90","90","סנהדרין צז, ב."],["91","91","רמב\"ם הל' תשובה פ\"ז ה\"ה."]]],[1300251371,"משיחת ש״פ וישלח, ח״י כסלו ה׳תשמ״ז\nא. פון דעם שבת ווערט געבענטשט (מיני׳ מתברכין¹) דער טאג פון י״ט כסלו, דער חג הגאולה פון דעם אלטן רבי״ן, כ״ק אדמו״ר הזקן.\nדאס הייסט: אין צוגאב דערצו וואס י״ט כסלו פארמאגט מצד עצמו, ובפרט זייענדיק „חג החגים“² און „ראש השנה לחסידות“³ (מיט אלע תוארים ברשימות ושיחות רבותינו נשיאינו וואס באַ־צייכענען י״ט כסלו) — באקומט ער א תוספת ברכה והמשכה⁴ פון דעם שבת⁵.\nאון אין דעם גופא קומט צו נאך א שטארקערע השפעה וברכה (בגלוי) בקביעות שנה זו — ווען י״ט כסלו קומט אויס במוצאי שבת (יום הראשון)⁶, וואס דעמולט באקומט י״ט כסלו די ברכה פון שבת בלי שום הפסק זמן ובלי שום הפסק פון עובדין דחול, במילא האט די ברכה דעמולט נאך א שטארקערען תוקף.\nנוסף לזה וואס בשעת י״ט כסלו קומט גלייך במוצאי שבת (בלי שום הפסק פון עובדין דחול), איז די עבודה פון י״ט כסלו באופן נעלה יותר — קומענדיק גלייך פון א „ערב“ י״ט כסלו⁷ וואס איז א יום קודש⁸, יום השבת⁹.\nובפרט אין שבת עצמו — פון דעם סיום וחותם פון שבת, (און) זמן רעוא דרעוין, וואס דאס איז די העכסטע דרגא אין שבת גופא, כמאחז״ל¹⁰ „הכל הולך אחר החיתום“, ובפרט בנוגע צו דער",[["1","1","זח״ב סג, ב. פח, א."],["2","2","לשון כ״ק מו״ח אדמו״ר במכתבו — כ׳ כסלו תש״ג (אגרות קודש שלו ח״ז ע׳ ל. ונעתק בהקדמה ל„היום יום“). הקדמה לחוברת י״ט כסלו. נת׳ בלקו״ש ח״ה ע׳ 436 ואילך. לקמן ע׳ 385 ואילך."],["3","3","מכתב כ״ק אדמו״ר (מהורש״ב) נ״ע — ט״ז כסלו תרס״ב (נדפס ב„מבוא“ לקונט׳ ומעין ע׳ 17 (פאקסימיל׳ מגוכתי״ק). „היום יום“ — בתחלתו. אגרות קודש שלו ח״א ע׳ רנט)."],["4","4","ברכה מלשון המשכה — תו״א מקץ לז, ג."],["5","5","כפירוש הפשוט ב„מיני׳ מתברכין כולהו יומין“ (בנוגע לברכת המן בשבת) — ששבת אינו מהוה מציאות הימים, אלא שהוא ממשיך (תוספת) ברכה בכולהו יומין שהיו במציאותם בלאו הכי, ולהעיר ממחז״ל עה״פ (יתרו כ, יא. תשא לא, יז) „ששת ימים עשה ה׳“, ולא בששת, כל יומא ויומא עביד עבידתי׳“ (זח״ג צד, ריש ע״ב. הוספות לזח״א רסד, ב. ועוד)."],["6","6","כי אף שיחודים עליונים שב„קדושת שבת ויו״ט (וכן מובן בנוגע ל„חג החגים“ י״ט כסלו) הוא למעלה מגדר המקום והזמן“, וא״כ מהו הנפק״מ באיזה יום בשבוע הוא קביעות החג — הרי יחודים עליונים אלו מתלבשים בגדר ומדידת הזמן, ו„מאיר למטה לכל מקום ומקום בזמנו הראוי לו“ (לשון אדה״ז בשלחנו או״ח מהדו״ת ס״א ס״ח. וראה מאמרי אדה״ז תקס״ו ע׳ מג ואילך. תו״ח בשלח שמט, ב ואילך. אוה״ת נ״ך כרך ג ע׳ א׳קסו ואילך). ולכן, יש בו עילוי כשהוא ביום ראשון, שמתברך מיום השבת בלי שום הפסק ימים, כבפנים."],["7","7","ראה שיחת י״ט כסלו תש״ד (ע׳ 48), שלפני י״ט כסלו, ר״ה לחסידות, ישנו הערב ראש השנה."],["8","8","שזהו למעלה מקדוש וטוב, קדש מלה בגרמי׳ (זהר ח״ג צד, ב. סידור עם דא״ח ר, ג ואילך. וראה תו״א ר״פ חיי שרה)."],["9","9","ומובן שאי״ז סתירה לאין שבת מכינה לחול (משנה שבת ספט״ו. ושו״נ. מדרש לקח טוב בשלח סז, ה) — כי המדובר כאן הוא לא בנוגע להכנת שבת לי״ט כסלו, כי״א להשפעת שבת בי״ט כסלו כולל הבאה מסמיכותם. ויתרה מזה — המן דבר יום ביומו (בחול) הוכן ונעשה (ב„השמים“) בשבת דוקא (זהר שבהערה 1. מאמרי אדה״ז על פרשיות התורה כרך א ע׳ רצה ואילך. אוה״ת בשלח ע׳ תרלח ואילך. ועוד)."],["10","10","ברכות יב, א."]]],[1300251372,"חיתום פון שבת — רעוא דרעוין¹¹ — כמבואר בכ״מ¹² אז אין דער שלימות פון שבת עצמו איז רעוא דרעוין תכלית השלימות¹³.\nב. לויט דעם כלל¹⁴ אז המעשה הוא העיקר¹⁵, איז פארשטאנדיק, אז דער עילוי פון דעם שבת, שמיני׳ מתברך י״ט כסלו וכו׳, דארף מען אראפברענגען אין עבודה ומעשה בפועל.\nובפשטות: פון דעם שבת (וואס בענטשט, איז ממשיך תוספת ברכה והמשכה אין י״ט כסלו) דארף מען נעמען א תוספת כח והמשכה צו טאן אין די עבודה פון י״ט כסלו (א הוספה אפילו לגבי די עבודה פון י״ט כסלו מצ״ע) — „ראש השנה לחסידות“ — די עבודה פון „יפוצו מעינותיך חוצה“¹⁶, וואס עיקרה האט זיך אנגעהויבן בי״ט כסלו¹⁷.\nובמיוחד — כמנהג ישראל — דורך מאכן התוועדויות בי״ט כסלו בכל מקום ומקום¹⁸, און זיך אלע צוזאמען שטארקען אין טאן די עבודה פון הפצת המעינות חוצה.\nכולל — דורך אויפשטעלן (אדער מרחיב זיין) א „בית חב״ד“¹⁹, בכל מקום ומקום²⁰.\nאון לויט דעם כלל אז „איני מבקש כו׳ אלא לפי כחן“²¹, איז פארשטאנדיק אז נאך איידער בקשת (וציווי) הקב״ה אז „המעשה הוא העיקר“, האט יעדערער דעם כח („כחן“) צו מקיים זיין די בקשה, אפילו ווען עס רעדט זיך וועגן „כחן“ המוגבל (נאך איידער מ׳קומט צו די עבודה פון „בכל מאדך“²², שלמעלה מכחן).\nוכל זה — מתוך שמחה וטוב לבב, ווי דער אויבערשטער איז מבקש בנוגע צו כל עניני עבודה — „עבדת את ה׳ אלקיך בשמחה וטוב לבב“²³, במילא איז פאר־שטאנדיק אז ער גיט אויך אויף דעם כחות,\nובמיוחד — שמחה בקשר מיט י״ט כסלו, כידוע אז י״ט כסלו איז א „מועד“²⁴ (און „חג החגים“), וואס „מועדים לשמחה“, ווי מנהג ישראל איז אז מ׳פראוועט די התוועדויות בי״ט כסלו מתוך שמחה²⁵.",[["11","11","זח״ב פח, סע״ב. ח״ג קכט, א."],["12","12","ראה המשך תרס״ו ע׳ תקמג ואילך. המשך תער״ב ח״ב ע׳ א׳קכז ואילך. וראה אוה״ת בשלח ע׳ תרכא. בהר (כרך ד) ע׳ א׳קנב."],["13","13","וצ״ע אם העילוי דרעוא דרעוין קשור עם מעלת חותם השבת, דהכל הולך אחר החיתום, דיש לומר בב׳ אופנים: א) הם שני דברים נפרדים (כדמוכח לכאורה מזה שלא כל חיתום יש בו העילוי דרעוא דרעוין), ב) הא בהא תלי: העילוי דרעוא דרעוין בשבת (לגבי שאר הזמנים בשבת) הוא מצד החיתום דשבת, והכל הולך אחריו. ואכ״מ."],["14","14","אבות פ״א מי״ז."],["15","15","וכמבואר בתניא (פל״ח), שהמכוון כל הכוונות ולא קיים המצוה בפועל — „לא יצא ידי חובתו“."],["16","16","ראה אגה״ק הידועה דהבעש״ט — נדפסה בכש״ט (הוצאת קה״ת) בתחלתה. ובכ״מ."],["17","17","ס׳ השיחות תורת שלום ס״ע 112 ואילך."],["18","18","ע״ד אופן עריכת התוועדויות בי״ט כסלו — ראה לקו״ש ח״י ע׳ 230 ואילך."],["19","19","ולהעיר שגם התוועדות היא ע״ד הקמת (או הרחבת) „בית חדש“ — קיבוץ ואחדות של כמה וכמה מישראל, כדי שעי״ז יהי׳ „בית ישראל ברכו את הוי׳“ (תהלים קלה, יט) ע״ד הקמת בית שהוא ע״י קיבוץ כו״כ ענינים, אבנים כו׳."],["20","20","ראה לעיל ע׳ 338. ושו״נ."],["21","21","במדב״ר פ״ב, ג."],["22","22","ואתחנן ו, ה."],["23","23","תבוא כח, מז. וראה רמב״ם סוף הל׳ לולב. תניא פכ״ו (לג, א)."],["24","24","לשון אדה״ז — לקו״ד ח״א יט, ב."],["25","25","ראה מכתב כ״ק מו״ח אדמו״ר: קבעו את יום גאולת הוד כ״ק אדמו״ר הזקן, י״ט כסלו, ליום"]]],[1300251373,"ג. אין דעם לימוד הנ״ל פון דעם שבת שמברך (וערב) י״ט כסלו — קומט צו א תוספת הדגשה מצד די פרשה אין תורה וואס מ׳לייענט דעם שבת — פ׳ וישלח, כידוע דברי השל״ה²⁶ אז אלע מועדי השנה זיינען מרומז אין די פרשיות התורה וואס ווערן געלייענט אין די זמנים אין וועלכע די מועדים זיינען חל²⁷.\nדערפון איז פארשטאנדיק בנוגע דעם מועד²⁴ פון י״ט כסלו, וואס קומט אויס אלעמאל בסמיכות צו פ׳ וישלח²⁸ (ובשנה זו — בערב י״ט כסלו) — אז דער תוכן פון י״ט כסלו איז מרומז אין פ׳ וישלח:\nדי כללות העבודה פון „יפוצו מעינותיך חוצה“ (דער תוכן עיקרי פון י״ט כסלו) באשטייט פון „וישלח“²⁹: די מעינות (פון פנימיות התורה) זאלן ניט בלייבן במקומן (א מקום של קדושה ביותר), נאר ארויסגעשיקט („וישלח“) ווערן ממקומן און פאנאנדערגעשפרייט ווערן באופן פון „יפוצו“ ביז אין „חוצה“.\nובסגנון אחר: „וישלח“ איז מדגיש צוויי קצוות: מ׳שיקט א צווייטן אלס שליח (ניט זיך אליין); אבער צוזאמען דערמיט איז שלוחו של אדם כמותו³⁰, ביז כמותו דהמשלח ממש³¹.\nאזוי איז אויך בנוגע צו „יפוצו מעינותיך חוצה“: „חוצה“ מיינט אז דאס איז חוץ פון די מעינות עצמן (ניט די מעינות אליין): אבער עס דארף זיין „יפוצו מעינותיך חוצה“, מ׳דארף מפיץ זיין ניט נאר די מי המעינות, נאר די מעינות אליין אין „חוצה“³², אזוי אז עס ווערט אויס „חוצה“ און עס ווערט די „מעינות“ אליין — כמותו ממש.\nד. יש לומר אז דאס (יפוצו מעינותיך חוצה) האט א שייכות (ניט נאר מיט דעם פירוש פון דעם ווארט „וישלח“ (אבל — שם כל הפרשה), נאר אויך) מיט דעם תוכן פון „וישלח“ בפרשה זו³³:\nדער תוכן כללי פון סיפור יעקב ועשו בפרשתנו איז — עבודת הבירורים בעולם הזה הגשמי והחומרי, די עבודה פון יעקב צו מברר זיין עשו אחיו בארצה שעיר שדה אדום. און פון דעם סדר ואופן פון עבודת יעקב ווי דער־ציילט אין די פרשה קען מען ארויס־נעמען³⁴ דעם סדר ואופן ווי יעדער איד דארף טאן די עבודה אויך היינט.\nדער סדר בזה איז: לכל לראש — „וישלח יעקב מלאכים לפניו אל עשו",[["","","משתה ושמחה של מצוה (אגרות קודש שלו ח״א ס״ע תקנב)."],["26","26","חלק תושב״כ ר״פ וישב."],["27","27","וידועה תורת בעל הגאולה: מ׳דארף לעבן מיט דער צייט, מיט פרשת השבוע („היום יום“ ב׳ חשון. ס׳ השיחות תש״ב ע׳ 29 ואילך. ועוד)."],["28","28","בשבת פ׳ וישלח עצמו, או בימי השבוע שמתברכים משבת פ׳ וישלח. וראה ס׳ השיחות תש״ד ע׳ 50."],["29","29","שם כל הפרשה. וכמדובר כמ״פ, ששם הפרשה (כפי שנקרא ע״פ מנהג ישראל תורה היא) מורה על תוכן כל הפרשה (ראה לקו״ש ח״ה ע׳ 57 ואילך. ועוד)."],["30","30","משנה ברכות לד, ב. קידושין מא, ב. וש״נ."],["31","31","תשובות הריב״ש סי׳ רכח. ועוד. לקו״ת ויקרא א, ג. וראה שו״ע אדה״ז או״ח סי׳ רסג סכ״ה בקו״א: כעושה בעצמו ממש וכו׳ ה״ז כאילו אוחז ידו של חברו כו׳ שנעשית כידו אריכתא. וראה בארוכה לקח טוב (להר״י ענגיל) כלל א."],["32","32","ראה גם לקו״ש ח״ד ע׳ 1119. ח״י ע׳ 106. ועוד."],["33","33","בהבא לקמן ראה לקו״ש ח״י ע׳ 100 ואילך."],["34","34","דמעשה אבות סימן לבנים (ראה תנחומא לך ב. רמב״ן לך יב, ו. ועוד)."]]],[1300251374,"אחיו ארצה שעיר שדה אדום, ויצו אותם לאמר כה תאמרון לאדוני לעשו כה אמר עבדך יעקב עם לבן גרתי גו׳, ויהי לי שור וחמור גו׳ ואשלחה להגיד לאדוני למצוא חן בעיניך“³⁵. ווי חסידות איז מבאר אז דער טעם אויף דעם „וישלח“ איז געווען, בכדי מודיע זיין עשו׳ן אז יעקב האט שוין פארענדיקט די בירו־רים פון עולם התיקון זייענדיק אין גלות בא לבן חרן, און אויך די ניצוצות שנפלו ע״י שבירת הכלים בעולם התהו בעולמות בי״ע („ויהי לי שור וחמור גו׳“), און איצטער קען ער (און ער וויל) אויך מברר זיין עשו׳ן וואס שרשו איז מבחי׳ שבירת הכלים דתהו³⁶, ולמעלה מזה: „יעקב חשב שעשו נתברר כבר וחזר לשרשו הנעלה בחי׳ המקיפים דתהו שלפני התקון“, און דערפאר האט ער געשיקט מלאכים צו עשו׳ן בכדי „להמשיך בחי׳ המקיפים דתהו אליו למטה בתקון שהוא בחי׳ האו״פ ויאיר המקיף בפנימי ויתייחדו יחד“³⁷.\nאון בשעת יעקב האט דערהערט פון די מלאכים אז עשו איז נאך ניט מוכן לזה (אע״פ וואס יעקב איז שוין געווען מוכן), און אדרבה „הולך לקראתך וארבע מאות איש עמו“³⁸, האט יעקב פארשטאנען אז ער דארף עס אליין ממשיך זיין, דעריבער „ויקח מן הבא בידו מנחה לעשו אחיו“³⁹, דער ענין פון העלאת מ״ן לשרשו של עשו (בחי׳ תהו)⁴⁰, און דורך דעם וועט ער מבטל און מברר זיין עשו דלמטה⁴¹, און צו־גרייטן די וועלט צו „ועלו מושיעים בהר ציון לשפוט את הר עשו והיתה לה׳ המלוכה“⁴², „אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה׳ לעבדו שכם אחד“⁴³.\nוהיות אז עשו איז נאך ניט געווען מוכן לזה (ואדרבה, כנ״ל), האט יעקב אליין ניט געקענט גיין ברענגען די מנחה צו עשו׳ן, דעריבער האט ער אויף דעם (ווייטער) געשיקט שלוחים (זיינע עבדים) לפניו מיט די מתנות בידיהם, „ויאמר אל עבדיו עברו לפני גו׳“, „דרך יום או פחות ואני אבוא אחריכם“, און איר זאלט זאגן עשו׳ן אז איר זייט עבדים (שלוחים) „ליעקב“, און „מנחה היא שלוחה לאדוני לעשו והנה גם הוא (יעקב) אחרינו“⁴⁴. און דער טעם פאר־וואס יעקב האט אזוי געטאן איז „כי אמר אכפרה פניו (אבטל רוגזו) במנחה ההולכת לפני ואחרי כן אראה פניו אולי ישא פני“⁴⁵.\nאבער לאחרי ווי די שלוחים (עבדים) שלו גרייטן צו די וועג, דעמולט איז דער „ואני אבוא אחריכם“ און דער בירור פון עשו אויף א העכערן אופן (ווי עס וואלט געווען אן די שלוחים).\nווי ס׳איז געווען בפועל, אז דאס האט טאקע גע׳פועל׳ט א בירור אין עשו, „וירץ עשו לקראתו ויחבקהו גו׳ וישקהו",[["35","35","ריש פרשתנו (לב, ד ואילך)."],["36","36","תו״ח ריש פרשתנו."],["37","37","תו״א ריש פרשתנו."],["38","38","פרשתנו לב, ז."],["39","39","שם, יד."],["40","40","תו״א ותו״ח פרשתנו ד״ה ויקח מן הבא בידו."],["41","41","תו״א שם (כו, ריש ע״א). וראה ד״ה פדה בשלום לאדהאמ״צ (בשערי תשובה ח״א) פרק יא (נו, א)."],["42","42","עובדי׳ א, כא (הפטרה דפ׳ וישלח)."],["43","43","צפני׳ ג, ט. וראה רמב״ם הל׳ מלכים ספי״א."],["44","44","פרשתנו שם, יז ואילך ובפרש״י."],["45","45","שם, כא ובפרש״י."]]],[1300251375,"גו׳“⁴⁶. ביז אז עשו האט אים געזאגט אז ער זאל קומען אין ארץ שעיר.\nנאר וויבאלד אז „הילדים רכים והצאן והבקר עלות עלי גו׳“⁴⁷, ד.ה. אז דער בירור האט זיך נאך ניט אויפגעטאן בשלימות — האט יעקב געזאגט אז „ואני אתנהלה לאטי לרגל המלאכה אשר לפני ולרגל הילדים עד אשר אבוא אל אדוני שעירה“⁴⁸, בשעת עס וועט זיין דער שלימות הבירור בימי המשיח (ווען עס וועט זיין ועלו מושיעים בהר ציון לשפוט את הר עשו)⁴⁹.\nאון בינתיים איז „ויעקב נסע סוכתה ויבן לו בית גו׳“⁵⁰ — די עבודה (כולל — אין זמן הגלות) צו משלים זיין די עבודת הבירורים בעולם (בירור ותיקון עולם התהו — עשו).\nה. פון דעם סיפור בתורה (מלשון הוראה⁵¹) האט מען דעם לימוד בנוגע צו די עבודה פון אידן בכל הדורות⁵²:\nיש לומר אז דער ענין פון „וישלח יעקב מלאכים גו׳ אל עשו“, בכדי מברר זיין עשו׳ן (כנ״ל) — איז בדוגמת די שליחות⁵³ וואס דער אויבערשטער⁵⁴ גיט יעדער אידן⁵⁵ אראפשיקנדיק אים אלס א נשמה בגוף, וואס די כוונה בזה איז (ניט צוליב די נשמה אליין, „כי הנשמה עצמה אינה צריכה תיקון כלל כו׳“⁵⁶, נאר) צו מתקן זיין דעם גוף ונפש הבהמית וחלקו בעולם, לברר ניצוצין כו׳ בגשמיות וחומריות העולם, אויך די ניצוצות וואס זיינען געפאלן אין דברים גשמיים וחומריים כו׳, וואס געפינען זיך באַ די אומות העולם (בחי׳ עשו), און מאכן א דירה לו יתברך בתחתונים⁵⁶ ביז — שאין תחתון למטה ממנו (בירור ותיקון כל עולם התהו — עשו)⁵⁷.\nובפרטיות יותר: באַ יעדער איד דארף זיין בדוגמת „וישלח יעקב מלאכים גו׳ אל עשו“ — ארויסשיקן שלוחים, אַנ־הויבנדיק פון זיך אליין (מצוה בו יותר מבשלוחו⁵⁸), כולל זיינע כחות טבעיים (וואס ווערן אנגערופן „מלאכים“⁵⁹,",[["46","46","שם לג, ד."],["47","47","שם, יג."],["48","48","שם, יד."],["49","49","פרש״י שם."],["50","50","שם, יז."],["51","51","ראה זח״ג קנב, א (הובא בפרדס שער כז פ״א): ווי לאינון חייביא דאמרי דאורייתא לאו איהי אלא ספורא בעלמא. וראה מכתבי תורה (להרוגצ׳ובי) מכתב צט."],["52","52","כיון שנשמת יעקב „כלולה מכל הנשמות שבישראל מעולם ועד עולם“ (אגה״ק ס״ז (קיא, סע״ב))."],["53","53","כידוע שהשם מלאך הוא ע״ש ענין השליחות — לקו״ת ויקרא א, ג. וראה ס׳ הליקוטים דא״ח — צ״צ ערך מלאכים (ע׳ תלב ואילך). מקומות שבהערה 55."],["54","54","ולהעיר שיעקב נקרא „א־ל אלקי ישראל“ (פרשתנו לג, כ. מגילה יח, א. פרש״י פרשתנו עה״פ. זח״ג פו, א. וראה ב״ר פע״ט, ח). נת׳ במקומות שבהערה הבאה. וראה אגה״ק שבהערה 52."],["55","55","כמבואר בלקו״ת (ויקרא שם) שכאו״א מישראל הוא שלוחו של אדם העליון כמותו — כמותו דהמשלח ממש. וראה אוה״ת פרשתנו רמט, ב. ד״ה ויצב שם מזבח תרל״ג. ד״ה הנ״ל (עם הגהות) תרמ״ד (סה״מ תרמ״ד (קה״ת תשמ״ט) בהוספות ע׳ רצח); תרנ״ב (סה״מ תרנ״ב ע׳ נו ואילך)."],["56","56","תניא פל״ז (מח, ב)."],["57","57","ובפרטיות יותר: „ויצא יעקב מבאר שבע וילך חרנה“ — קאי על כללות השליחות דירידת הנשמה בגוף (אור החיים ויצא כח, יד. קיצורים והערות לתניא ע׳ נז. דרושי פ׳ ויצא — תר״ל, תר״פ, תרפ״ז. ועוד), שיעקב קיים שליחותו של אביו ואמו („וישמע יעקב אל אביו ואל אמו וילך פדנה ארם“ — תולדות כח, ז). ועבודתו של יעקב בחרן אצל לבן היתה עבודה בטוב וקדושה ע״י תומ״צ (עבודת הצדיקים); ולאחרי גמר הבירורים בחרן — הי׳ מוכן לירידה תחתונה יותר, בירור עשו, בחי׳ הרע דנוגה (עבודת התשובה) — אוה״ת פרשתנו רכז, א ואילך. סד״ה וישלח תרמ״ט. תרס״ו. תער״ג. תשמ״ג."],["58","58","קידושין מא, א."],["59","59","מו״נ ח״ב פ״ו."]]],[1300251376,"„שלוחים“) — צו מברר זיין גשמיות וחומריות העולם דורך הפצת התורה והיהדות והצדק והיושר באַ דעם אייגע־נעם גוף ונה״ב, און אין חלקו בעולם, ביז אויך באַ אוה״ע, דורך קיום שבע מצוות בני נח (כפס״ד הרמב״ם⁶⁰).\nובמיוחד ווערט דאס אויפגעטאן דורך די עבודה פון „יפוצו מעינותיך חוצה“ — ארויסשיקן („וישלח“) און פאר־שפרייטן די מעינות פון פנימיות התורה אין „חוצה“, ביז אין חוצה שאין חוצה ממנה, בירור הניצוצות שנפלו ע״י שבירת הכלים דתהו.\nוע״י וואס אידן זיינען מקיים שלי־חותם (אלס שלוחו של אדם (העליון) כמותו ממש), גרייטן זיי צו די וועג אז עס זאל זיין „ואני (דער משלח ממש, ניט שלוחו כמותו) אבוא אחריכם“ — גילוי אלקות אין וועלט, ביז א דירה לעצמותו ית׳ בתחתונים, וואס אין א דירה גע־פינט מען זיך בגלוי: ווי ס׳וועט זיין בשלימות לע״ל — „והיתה לה׳ המלוכה“ בגלוי.\nועפ״ז איז מובן די שייכות פון י״ט כסלו מיט פ׳ וישלח — ווייל „י״ט כסלו איז א תיקון צו שבירת הכלים דתהו“⁶¹: הפצת התורה והיהדות בכלל דורכ־גענומען מיט הפצת המעינות חוצה במיוחד (וואס האט זיך אנגעהויבן בעיקר בי״ט כסלו) איז דער ענין פון „וישלח“ וואס טוט אויף די (לעצטע) בירורים פון עוה״ז הגשמי והחומרי, בירור ותיקון עולם התהו, אלס הכנה צו „ועלו מושיעים בהר ציון לשפוט את הר עשו והיתה לה׳ המלוכה“ בגאולה העתידה (כידוע אז יפוצו מעינותיך חוצה ברענגט „אתי מר“ דא מלכא משיחא⁶²).\nו. אין דעם קומט צו א חידוש מיוחד בדורנו — וואס דערמיט וועט מען נאכ־מער פארשטיין די שייכות פון „וישלח“ מיט י״ט כסלו (יפוצו מעינותיך חוצה):\nדער כללות הענין פון „וישלח“ (די שליחות פון יעדער אידן אלס שלוחו של הקב״ה, צו מברר ומתקן זיין עוה״ז הגשמי והחומרי (בירור ותיקון עולם התהו), דורך הפצת התורה והיהדות וה־צדק והיושר, ובמיוחד דורך הפצת המעינות חוצה) איז דא בכל הדורות ובכל הזמנים — די שליחות פון ירידת הנשמה בגוף פון יעדער מענטשן, אנ־הויבנדיק פון אדם הראשון און חוה און אלע מענטשן וואס שטאמען פון זיי.\nובמיוחד ווי ס׳איז געשטאנען בגלוי באַ די אבות, ביז באַ יעקב אבינו וואס „וישלח יעקב מלאכים גו׳ אל עשו“ בכדי אויפטאן דעם בירור פון עשו.\nועד״ז אין די דורות שלאחרי זה, ווי מ׳געפינט בכמה מקומות אין תורה⁶³ וש״ס דער ענין פון מאכן א שליח [בדיני קידושין⁶⁴, שליח לדבר מצוה⁶⁵, וכיו״ב], און אויך אין הנהגת גדולי ישראל, אז מ׳האט געשיקט איינעם מיט א שליחות מסויימת בעניני תומ״צ.",[["60","60","הל׳ מלכים פ״ח ה״י."],["61","61","שיחת י״ט כסלו תרס״ז (לפני שמונים שנה) — נעתקה בשיחת י״ט כסלו תש״ד (ע׳ 50). וראה שם, שענין זה הוא השייכות די״ט כסלו עם המסופר בפ׳ וישלח ע״ד „ואלה המלכים אשר מלכו וגו׳“ (מלכי ארץ אדום), מלכים דעולם התהו."],["62","62","אגה״ק דהבעש״ט שבהערה 16."],["63","63","להעיר משליחות אליעזר עבד אברהם — ענין כללי וכו׳ (ראה דרושי ד״ה יפה שיחתן — סה״מ תקס״ג כרך ב ע׳ לו. תו״ח חיי שרה קלה, א ואילך. אוה״ת שם קכו, ב ואילך. ועוד)."],["64","64","ראה קידושין מא, א ואילך."],["65","65","ראה קידושין שם. וראה ירושלמי חגיגה פ״א ה״ח. וכהנה רבות."]]],[1300251377,"און דערנאך איז אין דעם צוגעקומען א תוספת הדגשה דורך דעם בעש״ט און דעם מגיד און דעם אלטן רבי״ן און רבותינו נשיאינו ממלאי מקומם — וואס זיי האבן געגעבן יעדער אידן די שלי־חות צו מפיץ זיין די מעינות חוצה.\nאין דעם גופא איז לכאורה צוגעקו־מען א חידוש דורך דעם נשיא פון אונ־זער דור — כ״ק מו״ח אדמו״ר — וואס הוי׳ „גלה סודו אל עבדיו הנביאים“⁶⁶, ועד״ז צו דעם צדיק ונשיא בכל דור ודור, און ער האט דערפון געמאכט א יסוד ודרך בעבודת ה׳ לכאו״א מישראל (כמדובר לעיל בארוכה⁶⁷):\nנשיא דורנו האט אויפגעטאן און אנגעזאגט צו כל אנשי ונשי הדור אז מצות הדור איז אין דעם ענין השלי־חות: אז יעדער איד פון דעם דור האט א מצוה וחיוב צו ווערן א „שליח“ אויף פארשפרייטן „דבר ה׳⁶⁸ זו הלכה“⁶⁹, תורה ויהדות, און הפצת המעינות חוצה, בכל מקום שידו (שידה) מגעת.\nביז אז דאס האט זיך אויסגעדריקט בגלוי ממש דורך דעם וואס ער האט ממנה געווען מענטשן אלס זיינע שלוחים מיוחדים — שליחותו בשלי־חותו של הקב״ה — אויף אוועקפארן אין פארשידענע ערטער און דארט מפיץ זיין תורה ויהדות און מעינות חוצה, בכדי מברר זיין די וועלט, און איר צו־גרייטן צו „והיתה לה׳ המלוכה“ בגאולה העתידה.\nוואס אין דעם דריקט זיך אויס בגלוי (מער ווי ס׳איז געווען אין די דורות שלפנ״ז) הנהגת יעקב אבינו⁷⁰ — „וישלח יעקב מלאכים⁷¹ גו׳ אל עשו גו׳ ארצה שעיר שדה אדום“, בכדי מברר זיין עשו׳ן.\nדער משלח אליין גייט טאקע (לכת־חילה) ניט אין דעם מקום השליחות, נאר „וישלח“ שלוחים — ווייל [נוסף לזה וואס יעקב האט מיט זיך געהאט נשיו ובניו, צאן ובקר וגמלים, „ואת כל רכושו גו׳ אשר רכש בפדן ארם“⁷², און ער האט זיי ניט געקענט אפלאזן און אוועקגיין לעשו בארצה שעיר — איז] „כי אמר אכפרה פניו במנחה ההולכת לפני ואחרי כן אראה פניו אולי ישא פני“, וי״ל הפירוש, ווייל די וועלט קען נאך ניט פארטראגן דעם גילוי פון דעם משלח (יעקב) אליין, און עס דארף דאך זיין א דירה בתחתונים, מצד גדרי התחתונים (ניט דורך ברעכן די גדרי העולם), דעריבער שיקט ער שלוחים (וואס זיי זיינען מער בערך צו דעם מקום הבירור),\nאבער די שלוחים זיינען פון די שטארקסטע און די בעסטע („מלאכים ממש“), און זיי זיינען שלוחו של אדם כמותו ממש⁷³,",[["66","66","עמוס ג, ז."],["67","67","לעיל ע׳ 329 ואילך. וראה גם שיחת ליל שמחת״ת (לפני הקפות) תשמ״ו (נדפסה בלקו״ש חכ״ט ע׳ 358 ואילך)."],["68","68","עמוס ח, יב."],["69","69","שבת קלח, ב."],["70","70","ולהעיר ש„נשיא“ ר״ת ניצוצו של יעקב אבינו (קהלת יעקב (לבעהמ״ס מלא הרועים) מערכת רבי. ונת׳ בלקו״ש ח״ד ע׳ 1051 הערה 18)."],["71","71","ולהעיר מפירוש הראשון במדרש (ב״ר פע״ה, ד) שמלאכים — „אלו שלוחי בשר ודם“. אבל רש״י מביא רק פירוש השני שבמדרש — „מלאכים ממש“. הביאור בזה — ראה לקו״ש ח״ה ע׳ 389 ואילך. ח״י ע׳ 100 בהערות."],["72","72","ויצא לא, יח."],["73","73","וראה לקו״ש ח״י שם ואילך הביאור בתורת הה״מ ב„מלאכים ממש“, ה„ממש“ של המלאכים שלח יעקב לעשו, אבל הרוחניות נשאר עם יעקב — שגם"]]],[1300251378,"און נאכמער: דער משלח איז מבטיח, אז דורך דעם וואס די שלוחים זיינען מקיים שליחותם במקומם הם בבירור העולם (בכח זה וואס זיי זיינען כמותו דהמשלח ממש), גרייטן זיי צו די וועג אויף „ואני אבוא אחריכם“, אז דער משלח אליין (ניט נאר שלוחו כמותו) קומט דארט אן און גייט צוזאמען מיט דעם שליח (ניט ווי בי׳ אנדערע עניני שליחות, וואו ס׳איז ניט מוכרח אז דער משלח אליין זאל אנקומען למקום השליחות), ואדרבה — דעמולט איז דאס באופן נעלה יותר ווי אויב עס וואלט געווען אן די הכנה ובירור פון עבודת השלוחים במקום ההוא,\n[ובנוגע צו כ״ק מו״ח אדמו״ר איז נאכמער בהדגשה ובגלוי דער „אני אבוא אחריכם“ — וואַרום „צדיקא דאתפטר אשתכח בכלהו עלמין יתיר מבחיוהי“⁷⁴, וואַרום ער האט שוין איצ־טער ניט די הגבלות פון א גוף גשמי, אפילו פון זיין גוף, און ניט נאר וואס „שבק חיים לכל חי“⁷⁵, נאר „אני אבוא אחריכם“, ער גייט־מיט מיט יעדן שליח].\nביז אז דאס ווערט א הכנה וכלי אויף „אני אבוא אחריכם“ פון דעם אויבער־שטן (דער משלח הראשון) — עס ווערט א דירה לעצמותו ית׳ בתחתונים.\nז. און בשעת מ׳שטייט אין א שבת ווען מ׳לעבט מיט פ׳ וישלח, און דאס איז אויך ערב י״ט כסלו (ווען עס האט זיך אנגעהויבן דער עיקר ענין פון יפוצו מעינותיך חוצה) — איז ספעציעל אונ־טערשטראכן מצות הדור (דורנו זה) — אז יעדער איד דארף ווערן א „שליח“ אין הפצת התורה והיהדות און הפצת המעינות חוצה.\nובנוגע לפועל — טאפארו דא פלאחו⁷⁶:\nמצות הדור איז — אז יעדער איד פון דעם דור במיוחד, אנשים נשים וטף⁷⁷ — דארף גלייך ווערן א „שליח“ צו פאר־שפרייטן „דבר ה׳ זו הלכה“ בכל מקום שידו מגעת.\nובפשטות ממש: טאמער עס זיינען נאך דא אידן וואס האבן ניט מקיים גע־ווען מצות הדור (אויך די וואס זיינען דאס מקיים, קענען זיי אין דעם אלעמאל מוסיף זיין) — האבן זיי א חיוב ואחריות (און אנדערע דארפן זיי אויף דעם מעורר זיין) צו גלייך ווערן „שלוחים“ צו פארשפרייטן אידישקייט.\nובהדגשה — „גלייך“, דאס ניט אפ־לייגן ועאכו״כ ניט ח״ו אפשטופן וכו׳, נאר דאס מקיים זיין גלייך למטה מעשרה טפחים, בעגלא דידן ובמהרה בימינו — וואַרום אין דעם באשטייט מצות הדור!\nוכמובן ופשוט, אז וויפל „שלוחים“ עס זיינען שוין פארן בעולם — זיינען נאך דא גענוג ערטער אין „חוצה“ וואו צדק ויושר און אידישקייט האבן נאך ניט דערגרייכט, אדער אפילו אין די ער־טער וואו עס האט דערגרייכט — איז",[["","","בבואם לעשו ובהמצאם אצלו (בגופם ובנפשם) לא ניתקו מהתקשרותם ליעקב, עד שכאילו באו לעשו רק בגופם וב„ממש“ שלהם בלבד. עיי״ש (ע׳ 107 ואילך) ההוראה בנוגע לשלוחי רבותינו נשיאינו."],["74","74","זח״ג עא, ב. אגה״ק סי׳ זך וביאורו."],["75","75","אגה״ק שם (קמו, א) בשם מארז״ל. ולע״ע מצאתיו בנוסח גט חליצה וכתובת יבמין — הובא ברמב״ם הל׳ יבום פ״ד ה״ל. שם הל״ב. ריי״ף יבמות ספי״ב."],["76","76","ראה ס׳ השיחות השי״ת ע׳ 105. תש״ב ע׳ 84. תש״ד ע׳ 104. ועוד."],["77","77","כנראה במוחש בהצלחת החינוך דהטף — כששומעים עד״ז מטף."]]],[1300251379,"דאס נאך ניט בתכלית השלימות, אזוי אז דער משלח אליין קען נאך ניט דארט אליין קומען, והראי׳ — אז ער איז דארט נאך ניט געקומען, און די גאולה איז נאך ניט געקומען!\nו„איני מבקש כו׳ אלא לפי כחן“²¹ — וויבאלד אז נשיא דורנו זאגט אן אז דאס איז מצות הדור, האט מען זיכער כחות אויף דעם. ואין הדבר תלוי אלא ברצון.\nח. און דערצו האט מען אויף דעם א לימוד מיוחד ונתינת כח מיוחדת פון היינטיקע פרשה (נוסף אויף די כחות וואס מ׳האט בזה בכל הזמנים) — „וישלח“:\nבאַ יעדער איד דארף זיין „וישלח גו׳ מלאכים אל עשו גו׳ ארצה שעיר שדה אדום“. ולכל לראש — מצוה בו יותר מבשלוחו — דורך אליין ווערן א „שליח“ און זיך אליין „ארויסשיקן“ [נאר דערנאך, ווען ער ווערט נתעלה צו א העכערע דרגא אין שליחות, קען ער דעמולט איבערגעבן א שליח (א צווייטן) די עבודה הקודמת, וכיו״ב], ד.ה. ארויס־גיין פון זיך אליין. וואס הייסט ארויס־גיין פון זיך אליין? גיט חסידות אן איינ־פאכען אויספרואוו: בשעת מ׳הייסט אים טאן א זאך, און אים ווילט זיך עס ניט טאן, והראי׳ אז ער טוט עס ניט, און ער וויל בעסער טאן אן אנדער זאך (שבקדושה) — איז א ראי׳⁷⁸ אז ער דארף טאן דוקא די זאך וואס אים ווילט זיך ניט, והראי׳ — אז דער צד שכנגד שטעלט זיך אזוי אנטקעגן דעם. און דאס הייסט ארויסגיין פון זיך — טאן וואס אים ווילט זיך ניט טאן.\nועוד והוא העיקר — ווערן א „שליח“ דורך „ארויסגיין“ בפשטות (ניט נאר פון זיך, נאר) פון די ד׳ אמות של ביהכנ״ס שלו וביהמ״ד שלו במשך כמה זמן, תורה ותפלה, און אוועקפארן אין אן ארט, אין „חוצה“ — אפילו אויב דאס איז „ארצה שעיר שדה אדום“, עאכו״כ אז רוב ערטער בזמננו פאדערן ניט אזא בירור קשה — און זיך דארט באזעצן מיט די כוונה צו דארט מפיץ זיין צדק ויושר, אידישקייט און הפצת המעינות חוצה.\nט. אין דעם ענין האט מען נאך א לימוד פון הנהגת יעקב בפרשתנו. ובהקדים א דבר תמוה אין דעם ביאור בדרושי חסידות הנ״ל (ס״ד):\nאין די דרושים שטייט אז יעקב האט געשיקט מלאכים צו עשו׳ן, בכדי אים מודיע זיין אז ער האט שוין דורכגעטאן אלע בירורים⁷⁹, און איז שוין גרייט צו די גאולה (רעכענענדיק אז אויך עשו איז שוין לאחרי הבירור), און דורך מברר זיין עשו׳ן (און ממשיך זיין די אורות דתהו של עשו), קען מען גלייך ברענגען די גאולה⁸⁰.",[["78","78","דוגמא בהלכה: אוהב ושונא — שונא קודם, לכוף יצרו (ב״מ לב, סע״ב. רמב״ם הל׳ רוצח ושמירת נפש פי״ג הי״ג)."],["79","79","ועפ״ז מתורץ מה שהדגיש לעשו — ותרי״ג מצות שמרתי."],["80","80","כן משמע בתו״א ותו״ח שבהערות 36-37. וכן מוכח לכאורה מזה שיעקב חשב שעשו כבר נתברר (תו״א שם), כי הגאולה תלוי׳ בשלימות הבירורים (ע״ח שער מ״ן ומ״ד דרוש א ואילך. תניא פל״ז. ועוד). וראה תו״ח שם (מב, סע״ב ואילך) שיעקב „כבר הי׳ שלם בעבודתו כמו שיהי׳ לעתיד לבא ושלח מלאכים אל עשו כמו שהוא למעלה אחר הבירור לגמרי כו׳ שזהו בחינת ומדריגת דעולם הבא כו׳“. ואולי יש לומר היסוד לזה — ע״פ דברי המדרש (ב״ר פע״ה, ו) בדברי יעקב (ע״י המלאכים) לעשו „ויהי לי שור וחמור גו׳“, „חמור זה מלך המשיח כו׳“. וראה לקו״ש ח״א ע׳ 69."]]],[1300251380,"שטעלט זיך די שאלה: ווי האט יעקב געקענט טראכטן אז מ׳איז שוין גרייט צו די גאולה — ווען ער האט געוואוסט א) פון דעם שטר חוב⁸¹ פון „ועבדום וענו אותם ארבע מאות שנה“⁸² (וואס איז נאך ניט מקויים געווארן), און ב) אז עס זיי־נען דא שבעים אומות העולם, וביניהם עובדי עבודה זרה⁸³, ווי יעקב האט גע־זען אויפן וועג פון חרן קיין ארץ ישראל⁸⁴?\nיוד. ויש לומר איינער פון די לימודים בזה בעבודת האדם⁸⁵:\nוויבאלד אז יעקב האט געהאט די שליחות צו ממשיך זיין די אורות דתהו פון עשו׳ן (טראכטנדיק אז עשו איז שוין לאחרי הבירור), און דורך דעם ברענ־גען די גאולה; און דער אויבערשטער האט אים ניט אנגעזאגט אז ער דארף זיך פארנעמען מיט די אנדערע אומות — איז א ראי׳ אז ער קען מקיים זיין שליחותו און ברענגען די גאולה, ניט קוקנדיק אויף דעם וואס עס טוט זיך ארום אים.\nאון דעריבער איז יעקב׳ן ניט געווען נוגע (בקיום שליחותו) וואס עס טוט זיך ארום אים (באַ די שבעים אומות, און בנוגע צו די גזירה פון „ועבדום וענו אותם גו׳“); אים איז נוגע בלויז איין זאך — קיום שליחותו, צו מברר זיין עשו׳ן. וי״ל הטעם — עשו אחיו.\nאון מיט דעם צוגאנג האט ער טאקע מצליח געווען, ווי ס׳איז געווען בפועל,\nאז בשעת יעקב איז געגאנגען מיט א תוקף איז עשו פאר אים בטל געווארן (אפילו בלי לקיחת המנחה ששלח לו יעקב)⁸⁶, און ער האט אין אים אויפגע־טאן דעם בירור, און אפילו עשו׳ס מלאך האט אים ניט געקענט שטערן (נאר מפני סיבות האט זיך גאולה דעמולט פאר־האלטן, כנ״ל ס״ה).\nדערפון, מעשה אבות — סימן לבנים, איז אויך דער לימוד בנוגע צו א שליח איצטער:\nבשעת נשיא דורנו — וואס הוי׳ „גלה סודו אל עבדיו הנשיאים“ — שיקט איינעם א שליחות, ווייסנדיק וועגן דעם חושך כפול ומכופל ארום [און אפילו בנוגע צו א שליחות בימינו אלו (כו״כ שנים לאחרי הסתלקות כ״ק מו״ח אדמו״ר), האט כ״ק מו״ח אדמו״ר משער געווען בזמנו (ווי ס׳איז מוכח פון כמה ענינים) אז היינט וועלן זיין אוה״ע ומנגדים וכו׳] — איז דער־פון גופא א ראי׳ ברורה אז ער קען מקיים זיין שליחותו בשלימותה, ניט קוקנדיק אויף דעם ארום, און קיינע פון די אוה״ע און מלאכים וכו׳ — קענען אים ניט שטערן (ווי ס׳איז געווען באַ יעקב׳ן).\nדערפון איז פארשטאנדיק דער צו־גאנג וואס דארף זיין בײ א שליח: דעם שליח דארף ניט זיין נוגע וואס עס טוט זיך אין דער וועלט ארום אים, ניט אויף „וואל סטריט“ און ניט באַ די שבעים אומות וכיו״ב, אים דארף זיין נוגע נאר איין זאך — אין לו בעולמו אלא שליחותו צוליב וועלכע מ׳האט אים גע־שיקט, און וואו מ׳האט אים געשיקט, און ווער עס האט אים געשיקט, און ווי ער דארף מקיים זיין שליחותו.",[["81","81","ראה פרש״י פרשתנו לו, ז."],["82","82","לך טו, יג."],["83","83","ראה רמב״ם ריש הל׳ ע״ז."],["84","84","מהלך י״ז יום (פדר״א פט״ז)."],["85","85","הביאור בזה ע״ד החסידות — ראה בהמאמר ד״ה וישלח שנאמר בהתוועדות."],["86","86","ראה סד״ה ויקח מן הבא בידו פרש״ת."]]],[1300251381,"ארום אים געפינט זיך טאקע א גאנצע וועלט, מיט שבעים אומות וכו׳ וכו׳, און דאס קען אים אויך זיין נוגע לעבודתו, בכדי וויסן אז „אתה בחרתנו מכל העמים“, וכיו״ב — דאס אלץ איז טאקע גוט און פיין, אבער בשעת דו האסט, באקומסט א ציווי פון „עבדיו הנשיאים“ אז דו דארפסט איצטער גיין טאן א שליחות מסויימת, דארף דיר ניט זיין נוגע די אלע זאכן, מערניט — קיום שליחותך!\nאון ס׳איז א דבר ברור אז דו וועסט אין דעם מצליח זיין.\nדערפון האט מען אן ענטפער אויף כמה שאלות פון שלוחים בנוגע לקיום שליחותם:\nווי קען ער מקיים זיין א שליחות כדבעי, ווען ער זעט אז ארום אים גע־פינען זיך אזוינע וואס האלטן נאך ווייט פון טוב וישר, און שבעים אומות, ובכלל — עוה״ז, וואס איז „מלא קליפות וס״א“⁸⁷, און „כל מעשה עוה״ז קשים ורעים והרשעים גוברים בו“⁸⁸ — איז דאס מבלבל לקיום שליחותו, ווייל אע״פ וואס ער זעט א תועלת פון זיין ארבעט, איז אבער במה נחשב הוא לגבי דעם חושך כפול ומכופל ארום אים?!\nענטפערט מען אים: וויבאלד אז נשיא דורנו האט דיר געשיקט אין די שליחות, און ער האט געוואוסט וועגן דעם חושך כפול ומכופל ארום — ואעפ״כ האט ער געזאגט אז מ׳זאל גיין אין די שליחות, איז א ראי׳ ברורה אז דורך קיום השליחות קענסטו מצליח זיין און אלץ אויפטאן!\nואין הדבר תלוי אלא ברצונו. מ׳דארף נאר וועלן. און נאכמער: מ׳דארף נאר זאגן „רוצה אני“ (אפילו אויב דאס קומט דורך „כופין אותו“)⁸⁹, וואַרום דאס איז פנימיות רצונו שלו (און די כפי׳ איז בלויז צו אראפנעמען דעם „יצרו תקפו“⁸⁹).\nווי מ׳האט געזען בפועל, אז די שלוחים וואס זיינען געגאנגען מיט דעם צוגאנג און זיך געשטעלט מיט דעם גאנצן תוקף אין מקיים זיין שליחותם (און זיך ניט גערעכנט און געטראכט וועגן דעם חושך כפול ומכופל ארום) — האבן טאקע מצליח געווען, ולמעלה מן המשוער, ומתוך שמחה וטוב לבב. און דערפאר איז א לימוד פאר אלע אנדערע מכאן ולהבא — אז די וואס וועלן גיין מיט דעם צוגאנג — וועלן מצליח זיין, ומתוך שמחה וטוב לבב, און קיין דבר שבעולם וועט זיי ניט שטערן.\nביז אז דער שליח וועט דורך דעם ברענגען (בגלוי) דעם משלח ממש צו דעם מקום השליחות („ואני אבוא אחריכם“), ביז אויך דעם אויברשטן באופן של — דירה לו יתברך בתחתונים.\nאון אויב מ׳האט נאך אלץ שאלות — מאנט טאקע תורה און חסידות אז עס דארף זיין הבנה והשגה⁹⁰ — אבער דאס טאר ניט זיין א סתירה און אפילו ניט אן עיכוב צו טאן בפועל; ס׳איז צווי באַ־זונדערע זאכן: לכל לראש איז מצות הדור אז מ׳דארף גיין אויף שליחות, און ליגן נאר אין זיין שליחות פרטית; דערנאך איז דא א צווייטער ענין — אז",[["87","87","תניא פל״ו."],["88","88","שם ספל״ו. פכ״ד (ל, א)."],["89","89","רמב״ם הל׳ גירושין ספ״ב."],["90","90","וראה רמב״ם סוף הל׳ מעילה וסוף הל׳ תמורה."]]],[1300251382,"מ׳דארף זיך משתדל זיין צו פארשטיין בהבנה והשגה עד כמה שאפשר.\nיא. ולסיכום:\nמצות הדור ומצות היום פון יעדער איד פון אונזער דור איז — צו ווערן א „שליח“ אויף פארשפרייטן צדק ויושר, און אידישקייט, און הפצת המעינות חוצה במיוחד.\nאון וויבאלד אז דאס איז מצות הדור, איז ניט שייך תירוצים אויף דעם, אז ער דארף נאך עפעס פארענדיקן, און דארף נאך עפעס אנהויבן וכו׳ וכו׳: מצות הדור איז — ער זאל לכל לראש ווערן א „שליח“!\nובכדי צו וויסן אין וואס בפרט באשטייט זיין שליחות — דארף ער פרעגן בא נשיא דורנו: ובאמת האט ער שוין דאס אויך פארשפארט — וואַרום מ׳קען דאס ארויסנעמען פון די ריבוי שיחות וקונטרסים וואס זיינען אפגעדרוקט. מ׳דארף נאר אפגעבן א פאר סענט און קויפן דעם „קונטרס“, און לערנען וואס דארט שטייט — וועט מען קענען אליין וויסן וואס מ׳דארף טאן.\nאון טאמער מ׳קען אלץ ניט קו־מען צו א מסקנא, אדער מ׳האט א מניעה, אז „גלוי וידוע לפניך שרצוננו לעשות רצונך, ומי מעכב שאור שבעיסה“⁹¹ — האט מען די עצה מפורשת במשנה⁹²: „עשה לך רב“ („עשה“ מלשון כפי׳⁹³), און דערציל אים\nאלע פרטים, און אויך וועגן דעם „שאור“, און פאלג וואס ער וועט דיר הייסן טאן. וועט דאס פארשפארן פרעגן כו״כ שאלות — וואו מ׳זאל פארן, און וואס מ׳זאל טאן, און וואס זאל מען טאן אז מ׳האט א נה״ב וכו׳.\nיב. ויה״ר אז דורך די עבודה פון „וישלח“, ביז דער שלימות בזה — בירור ותיקון העולם, ביז „ויבן לו בית“ („בית חב״ד“) — וועט יעדער שליח במקומו אויפטאן א גאולה פרטית במקומו, ביז ער וועט מגלה זיין דעם „אני אבוא אחריכם“, דער גילוי פון דעם משלח אליין, עצמותו ית׳,\nאון די אלע גאולות פרטיות שטעלן זיך צוזאמען און ברענגען די גאולה כללית, גילוי עצמותו ית׳ בכל העולם כולו — א דירה (בית) לו יתברך בתחתונים.\nאון דעמולט וועט זיין „וישב יעקב“⁹⁴ (ווי מ׳הויבט אן לייענען אלעמאל בתפלת מנחה פון שבת פ׳ וישלח), קיום בקשת יעקב „לישב בשלוה“⁹⁵, ד.ה. ניט נאר באופן של התיישבות (מלשון העכבה), נאר אויך באופן פון „שלוה“,\n„בארץ מגורי אביו בארץ כנען“⁹⁴ — בארץ הקודש, „ארץ אשר גו׳ תמיד עיני ה׳ אלקיך בה מרשית השנה ועד אחרית שנה“⁹⁶, שלימות הארץ, ביז באופן פון „ירחיב ה׳ אלקיך את גבולך“⁹⁷, צוזא־מען מיט שלימות העם, „בנערינו ובזקנינו גו׳ בבנינו ובבנותינו“⁹⁸, וכספם",[["91","91","ברכות יז, א."],["92","92","אבות פ״א מ״ו. שם מט״ז. וראה בארוכה שיחת ש״פ דברים תשמ״ו (נדפסה בלקו״ש חכ״ט ע׳ 247-8). לעיל ע׳ 306 ואילך. ועוד."],["93","93","ראה מאירי — הובא במדרש שמואל לאבות שם מ״ו. וראה מאמרי אדהאמ״צ ויקרא ח״ב ע׳ תשסא. סה״מ תרל״ו ח״ב ע׳ רפט. ועוד."],["94","94","ר״פ וישב (לז, א)."],["95","95","פרש״י שם, ב."],["96","96","עקב יא, יב."],["97","97","ראה יב, כ. שופטים יט, ח."],["98","98","בא י, ט."]]],[1300251383,"וזהבם אתם⁹⁹, כולל — כסף וזהב הרוחניים, אהבה ויראה¹⁰⁰, וואס זיינען מקור ושורש וכולל כל מצות עשה און כל מצות לא תעשה¹⁰¹ — שלימות התורה ומצוותי׳.\nובפרט דורך דעם וואס מ׳טוט די עבודה בשמחה ובטוב לבב, וואס שמחה פורץ גדר¹⁰², אויך דעם גדר פון גלות, און עס ווערט „פרצת עליך פרץ“ (ווי\nעס שטייט בפ׳ וישב¹⁰³. ומעין זה — בפ׳ וישלח¹⁰⁴: „ויפרוץ האיש מאד מאד“, „עלה הפורץ לפניהם“¹⁰⁵, „אלה תולדות פרץ“¹⁰⁶, „שיבוא בן פרץ“¹⁰⁷.\nאון אויך פריצת גדרי הזמן — אז תיכף ומיד ממש קומט די גאולה, באופן פון „כהרף עין“¹⁰⁸, „כהרף עין“ פון איצטער אָן! — עין בעין יראו¹⁰⁹.",[["99","99","ישעי׳ ס, ט."],["100","100","ראה תו״א ר״פ וישב. תו״ח שם נח, א ואילך. לקו״ת בהעלותך לב, ד. ובכ״מ."],["101","101","תניא פ״יד."],["102","102","ראה המשך שמח תשמח תרנ״ז (סה״מ תרנ״ז ע׳ רכג ואילך)."],["103","103","לח, כט."],["104","104","ל, מג."],["105","105","מיכה ב, יג. ב״ר פפ״ה, יד וברש״י שם. אגדת בראשית ספס״ג."],["106","106","רות ד, יח."],["107","107","ב״ר פי״ב, ו."],["108","108","לשון רש״י בא יב, מא (ממכילתא בא שם)."],["109","109","ישעי׳ נב, ח."]]],[1300251384,"א. בקשר מיטן איצטיקן מצב בעולם, אז מלכיות מתגרות אלו באלו¹, ובפרט אין שנים און אין חדשים ושבועות הכי אחרונים — וואס דאס גייט באופן מבהיל, ובמדה ידועה איז דאס אויך אריינגעדרונגען צווישן אידן, ר\"ל\n[אע\"פ אז דער סימן פון מלכיות מתגרות איז איינער פון די סימנים אויף ביאת המשיח¹ — האט מען שוין אבער (לכאורה) יוצא געווען לכל הדיעות אין סימנים אויף ביאת משיח, אפילו אויך אין דעם סימן פון מלכיות מתגרות, ואעפ\"כ — גייט אויך איצטער דער מלכיות מתגרות בכיוון בלתי רצוי]\nובפרט אז בזמנים האחרונים ווערט אויך פארשפרייט באופן מבהיל דער היפך פון אהבת ישראל ושלום ואחדות בין ישראל, נאר מתגרים אלה באלה —\nאיז בהתאם צו דעם נייעם מצב וואס איז צוגעקומען בעולם (וואס איז ביז איצטער ניט געווען²), דארפן אידן צוגעבן בעבודתם — ובמיוחד: א הוספה אין בקשה להקב\"ה, ד.ה. — א הוספה בתפלה (במקום שאין בו איסור הפסק). און אין תפלה גופא — א הוספה וואס איז פארבונדן (א) מיט אהבת ישראל, וואס האט אויך א קשר מיוחד מיט עקבתא דמשיחא און מיט פארענדיקן דעם גלות וואס איז געקומען צוליב דעם היפך פון אהבת ישראל³. און (ב) מיט\nענין המנוחה בכלל [בלשון הרמב\"ם⁴ (בנוגע צו דעם מצב המנוחה דלע\"ל) — „לא מלחמה ולא קנאה ותחרות\"], היפך פון מלכיות מתגרות אלו באלו, און היפך פון העדר האחדות והשלום בין ישראל.\nאון דורך דעם וואס ס'קומט צו, די הוספה בתפלה בדיבורו פון א אידן אין די צוויי ענינים, וועט עס זיכער אויפ־טאן פעולתה — כידוע אז שוין דיבור טוב אליין פון א אידן ועאכו\"כ דיבור בתורה ותפלה, איז „קלין⁵ דאורייתא וצלותא סלקין לעילא⁶ בקעין רקיעין כו'\". ובפרט אז פון דעם מחשבה ודיבור טוב ווערט „מצרפה למעשה\"⁷, און ער פירט זיך אזוי בפועל.\nאין אנדערע ווערטער: בשעת ס'איז דא א בלבול בעולם און מלכיות מתגרות אלו באלו, קען א איד זיכער אויפטאן אין דעם (ניט דורך לייענען די „פייפערס\" בכדי וויסן וואס עס טוט זיך אין וועלט, וואס זיין ידיעה בזה איז סיי־ווי גארניט משנה, נאר די וועג איז — ניט פטר'נדיק צייט ללא כל תועלת כלל אויף ידיעת הפרטים, ואפילו — דעם כלליות המצב) — דורך מוסיף זיין",[["1","1","ב\"ר פמ\"ב, ד. ובמדרש לקח טוב עה\"פ לך יד, א: מלכיות מתגרות זו בזו."],["2","2","ראה סוטה מט, א: בכל יום ויום מרובה קללתו משל חבירו."],["3","3","יומא ט, ב."],["4","4","הל' מלכים פי\"ב ה\"ד."],["5","5","תניא פמ\"ט בהג\"ה הא' (נד, ריש ע\"ב) מזהר ח\"ג קסח, ב. קרא ד\"ה להבין מ\"ש בשער היחודים (קנד, סע\"א)."],["6","6","בתניא שם ליתא תיבות אלו (סלקין לעילא), וכנראה שצ\"ל בתניא (והוא השמטת המעתיק), ובפרט שבב' הציונים שלפנ\"ז בהג\"ה זו מדייק דסליק."],["7","7","קידושין מ, א (בנוגע למחשבה טובה, ומזה מובן במכ\"ש וק\"ו בנוגע לדיבור שבא מהמחשבה))."]]],[1300251385,"בתפלה בתורה וגמ\"ח, וואס דעמולט איז „כאילו פדאני לי ולבני מבין האומות\"⁸, ובמילא פועל'ט עס אויך אז די אומות פירן זיך דעמולט אויף כדבעי, ובלשון הידוע אנשטאט דעם אז דער „לי\" — כולל ניצוץ אלקי שבהם — איז בגלות ושבי' כביכול „בין האומות\", ווערט „פדאני\", ער ווערט נגאל ונפדה, און די אומות זיינען מרגיש בגלוי ווי דער ניצוץ איז ניט „בין האומות\", נאר על האומות, במילא פירן זיי דורך תפקידם — „ועמדו זרים ורעו צאנכם\"⁹.\nב. דערפאר איז מען מציע כנ\"ל — אז בהתאם צו דעם מצב שנשתנה בעולם ובין ישראל, זאלן אויך אפילו די וואס זיינען ניט מתפלל לויט נוסח האריז\"ל, מוסיף זיין בתפלתם (במקום שאין בו איסור הפסק), ניט קוקנדיק אויף זייער הנהגה עד עתה — בתחלת התפלה און בסוף התפלה — אן ענין פארבונדן מיט אהבת ישראל, און מיט כללות ענין המנוחה, און באמת איז דאס ניט קיין הוספת חידוש, ווייל דאס איז שוין דא בתפלה לויט נוסח הרמב\"ם, אחרונים וכו', נוסח האריז\"ל ונוסח אדה\"ז וכו' (כדלקמן):\n(א) בהקדמה לתפלה: פאר „מה טובו\", זאל יעדערער מוסיף זיין, זאגן „הריני מקבל עלי מצות עשה של ואהבת לרעך כמוך\".\nווי עס שטייט אין כתבי האריז\"ל¹⁰\n(וואס מאיזה סיבה איז דאס ניט ביי אלעמען שוין נתקבל געווארן), און דער אלטער רבי האט עס אריינגעשטעלט בסידורו¹¹ השווה לכל נפש¹² אפילו פאר אזא וואס „לא ידע מאי קאמר\" בכל עניני התורה (אע\"פ וואס כמה מכוונות האריז\"ל האט ער ניט אריינגעשטעלט בסידורו)¹³.\n(ב) בסוף התפלה: לאחרי די דריי פסוקים „אל תירא גו'\"¹⁴, „עוצו עצה גו'\"¹⁵, „ועד זקנה גו'\"¹⁶, וואס מ'זאגט נאך „עלינו\"¹⁷ (כברוב סידורים ככולם),\n— וואס די פסוקים זיינען אויך פארבונדן מיט ביטול כל הגזירות, ווי עס שטייט אין מדרש¹⁸ (וואס דאס איז דער מקור אויף אמירת ג' פסוקים אלה בסוף התפלה¹⁷) אז בשעת ס'איז געווען גזירת המן איז „ראה מרדכי שלשה",[["8","8","ברכות ח, א."],["9","9","ישעי' סא, ה. וראה ברכות לה, ב."],["10","10","שער הכוונות בתחלתו. פע\"ח שער עולם העשי' פ\"א (דפוס קארעץ תקמ\"א. דפוס דובראוונא. דפוס חדש — ירושלים, תש\"מ. בדפוס קארעץ תקמ\"ה הוא בשער ג' ספ\"ב). סידור האריז\"ל במקומו. מג\"א או\"ח ר\"ס מו. שו\"ע אדה\"ז שם ס\"א. — וכ\"ה כמה סידורים ובכ\"מ — נסמן במאמרי אדה\"ז — פרשיות ח\"ב ע' תתקמא ואילך."],["11","11","לפני „מה טובו\". פרטי המנהגים בזה — ראה בהנסמן במאמרי אדה\"ז שם."],["12","12","ראה לקו\"ש חכ\"ב ע' 115. ועוד."],["13","13","ראה ס' השיחות ה'ש\"ת ע' 157 שסיפר כ\"ק מו\"ח אדמו\"ר דבעת סעודת הבר מצוה שלו שאל את אביו כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע מדוע אומרים הריני מקבל כו' לפני התפלה דוקא, ואמר לו: ווען א טאטע האט א סך קינדער איז דער עיקר התענוג זיינער ווען ער זעט אז אלע זיינען זיי באחדות און האבן זיך איינער דעם אנדערן ליב. תפלה איז דאך בקשת צרכיו, הן צרכים גשמיים און הן צרכים רוחניים, איז קודם הבקשה דארף מען מאכן א נחת רוח לאבינו שבשמים, און דעריבער האט מען קובע געווען דעם לקבל מצות עשה פון אהבת ישראל קודם התפלה דוקא."],["14","14","משלי ג, כה."],["15","15","ישעי' ח, י."],["16","16","שם מו, ד."],["17","17","ראה שער הכולל פי\"א אות לו."],["18","18","אסת\"ר פ\"ז, יז קרוב לסופו."]]],[1300251386,"תינוקות . . כיון שהגיע מרדכי אצל התינוקות שאל לאחד מהם פסוק לי פסוקיך א\"ל אל תירא מפחד . . פתח השני ואמר . . עוצו עצה . . פתח השלישי ואמר ועד זקנה . . כיון ששמע מרדכי כך שחק והי' שמח שמחה גדולה, אמר לו המן מה היא זאת השמחה . . אמר (מרדכי) על בשורות טובות שבשרוני שלא אפחד מן העצה הרעה שיעצת עלינו\" — מרדכי איז געווען זיכער אז דורך דעם „מפי עוללים ויונ־קים\"¹⁹ איז די גזירה שוין בטל גע־וארן —\nאיז לאחרי די פסוקים זאל מען מוסיף זיין זאגן דעם פסוק²⁰: „אך צדיקים יודו לשמך ישבו ישרים את פניך\" (וואס איז פארבונדן מיט מנוחה והתיישבות ושלום).\nווי עס שטייט אין סדר תפלות כל השנה להרמב\"ם (וואס ער האט אריין־געשטעלט דעם סדר בספרו יד החזקה²¹, „הלכות הלכות\"²² — דאס איז א הלכה), און אין ב\"ח²³ וט\"ז²⁴. און אויך דער אלטער רבי איז דאס מוסיף בסידורו²⁵ (ווי עס שטייט אויך אין סידור האריז\"ל און אין כמה סידורים) בשם פון רש\"ל²⁶ (ר' שלמה לוריא²⁷): „וכתב\nרש\"ל שצ\"ל פסוק זה\" („אך צדיקים גו'\"). און ווי ער זאגט אין „שער הכולל\"²⁸ אז „גם בסידור האריז\"ל זלקווא (סידור האריז\"ל לר' שבתי מרשקוב²⁹) הובא זה בשם הרש\"ל\". און ער איז מסביר: „מה שהודיע לנו מקורו שהוא מהרש\"ל הוא מחמת שבפע\"ח לא נמצא לומר זה הפסוק\". ואע\"פ אז דער אלטער רבי האט געוואוסט אז עס שטייט ניט אין פע\"ח — האט ער דאס אריינגעשטעלט בסידורו השווה לכל נפש.\nאון אזוי שטייט אויך (אז מ'זאל זאגן „אך צדיקים גו'\" בסוף התפלה) אין סידור „סדר עבודת ישראל\"³⁰, שיש בו חכמה, נוסף למלאכה רבה. וידוע אז סידור זה ווערט אנגענומען אלס פוסק אחרון אין דעם חוג אידן יראים ושלמים וועלכע זיינען געגאנגען מיט דער שיטה פון „תורה ודרך ארץ\", זיי האבן אנגע־נומען סידור זהו³¹.\nדער קשר פון דעם פסוק („אך צדיקים יודו לשמך ישבו ישרים את פניך\") מיט",[["19","19","תהלים ח, ג."],["20","20","שם קמ, יד."],["21","21","בסו\"ס אהבה."],["22","22","כמ\"ש בהקדמתו לספר היד."],["23","23","או\"ח סקל\"ב ד\"ה ומ\"ש."],["24","24","או\"ח שם סק\"ב."],["25","25","וכ\"ה בסידור ר' יעקב עמדין. ועוד."],["26","26","שו\"ת מהרש\"ל סימן סד. מטה משה (לתלמיד מהרש\"ל) סרי\"ז."],["27","27","להעיר שיחוס מהרש\"ל הוא משבט יהודה ודוד המלך (ראה שו\"ת מהרש\"ל סכ\"ט (בהערה — מכת\"י שלו) שכ' יחוסו עד ר' יוחנן הסנדלר, ור\"י הסנדלר הוא דור ד' לר\"ג הזקן (שם הגדולים (להחיד\"א) מע' מהרש\"ל) בן ר\"ש בן הלל הזקן שהי' מגזע דוד המלך (ירושלמי תענית פ\"ד ה\"ב. וראה שבת נו, א. ועוד. — הובא בספר יוחסין מאמר א' מע' הלל. ועוד))."],["28","28","שם אות לז."],["29","29","ידוע שר\"ש מרשקוב הי' אצל הבעש\"ט, וסידורו יש בו „יחודים של האלקי קדוש הבעש\"ט\" (לשון שער הסידור)."],["30","30","„מחובר ומסודר כו' ע\"י יצחק בן אר\"י יוסף דוד\" (לשון השער) — רעדלהיים, תרכ\"ח. וכ\"ה בעוד סידורים מסוג זה."],["31","31","אפשר שמפני ש„אך צדיקים\" בסידור זה (סדר עבודת ישראל) נכתב כמה עמודים לאחרי התפלה (ובינתיים — הפסק כר\"כ ענינים) — נשמט מסידורים לאח\"ז המיוסדים על סידור זה."]]],[1300251387,"תפלה, איז מען מסביר³², אז אין מס' ברכות³³ לערנט מען אפ פון דעם פסוק אז „המתפלל צריך לשהות שעה אחת אחר תפלתו\"³⁴, „שנאמר אך צדיקים יודו לשמך — עבודת התפלה — והדר ישבו ישרים את פניך\"³⁵ — א התיישבות און א התבוננות [בדוגמא „וישב יעקב — לישב בשלוה\"³⁶] — א שעה³⁷ — נאך דער תפלה.\nועפ\"ז אפשר לומר אז דער פסוק האט אויך א קשר מיוחד מיטן איצטיקן מצב העולם — אז אנשטאט מלכיות מתגרות אלו באלו און היפך אהבת ישראל צווישן אידן זאל זיין א מצב פון מנוחה והתייש־בות בעולם, ביז מנוחה שלימה (באופן, ווי ס'איז שייך בזמן הגלות), „ישבו ישרים\", אידן זיצן בשלוה, קען בא זיי זיין „אך צדיקים — „ועמך כולם צדיקים\"³⁸ — יודו לשמך\", עבודת התפלה, וועלכע דארף זיין בלא³⁹ מחשבות המבלבלות, עאכו\"כ מחשבות המדאיגות.\nאון דורך דעם וואס מ'איז מוסיף בעבודת התפלה (וואס במקום קרבנות תקנום⁴⁰) — ווערט עס אויך א הכנה\nקרובה צו דער גאולה האמיתית והשלימה. אז מ'זאל מקריב זיין קרבנות ממש און אין אופן פון „מצוות רצוניך\"⁴¹. וואס דעמולט וועט אויך זיין כפשוטו „ישבו ישרים את פניך\" — בעלי' לרגל לביהמ\"ק מדי חודש בחדשו ומדי שבת בשבתו⁴² — „יראה כל זכורך אל פני האדון ה'\"⁴³.\nג. ידוע אז „נהרא נהרא ופשטי'\"⁴⁴, פארשידענע חוגי אידן האבן זייער נוסח התפלה⁴⁵, איז לכאורה מה ענין צו מוסיף זיין בהתפלה, מנוסח אחר?\n[ידועה די הוראה פון כ\"ק מו\"ח אדמו\"ר צו זיינע שלוחים וואס זיינען געפארן צו און צווישן אחינו הספרדים אין מרוקו און טוניס וכיו\"ב לאחרי מצוקות מלחמת העולם השני' אויף דארטן נאכמער מפיץ זיין דעם לערנען תורה בכלל ותורת החסידות במיוחד, אז זיי זאלן העלפן און זיך מתעסק זיין אין הפצת היהדות והפצת התורה והפצת המעינות, אבער מ'זאל ניט אנרירן אין „מנהג אבותינו בידינו\"⁴⁶ אין יענע קהלות קדושות בנוגע זייער נוסח התפלה, מנהגים וכו' (אחוץ די וואס האבן אליין געוואלט דערנאך משנה זיין)],\nוידוע דער פתגם וואס דער חתם סופר האט געזאגט אז „חדש אסור מן",[["32","32","שו\"ת מהרש\"ל שם. מטה משה שם. ב\"ח וט\"ז שם."],["33","33","לב, ב. ירושלמי ברכות פ\"ה ה\"א. וראה שו\"ע אדה\"ז חאו\"ח ר\"ס צג."],["34","34","במקומות שבהערה 32 (ובכ\"מ) שאמירת „אך צדיקים\" מיושב — אבל לא נעתק זה בסידור אדה\"ז. ובשער הכולל לא העיר ע\"ז — משמע דלא נוהגין כן."],["35","35","פרשי' שם ד\"ה יודו."],["36","36","ריש פרשתנו (וישב), פרשי' שם לז, ב."],["37","37","להעיר מפסחים נח, א שתמידים הקרבתן שעה אחת."],["38","38","ישעי' ס, כא."],["39","39","שו\"ע ואדה\"ז או\"ח סצ\"ז וסצ\"ח."],["40","40","ראה ברכות כו, ב. שו\"ע אדה\"ז או\"ח סצ\"ח סי\"ד."],["41","41","תפלת מוסף דשבת וידי\"ט. וראה תו\"ח ויחי צה, א ואילך. המשך וככה פי\"ז ואילך. ועוד."],["42","42","ישעי' סו, כג."],["43","43","משפטים כג, יז."],["44","44","חולין יח, ב. נז, א."],["45","45","ראה פע\"ח בתחלתו. לקו\"א להה\"מ סקל\"ג. הקדמה לשער הכולל."],["46","46","ראה ירושלמי פסחים פ\"ד ה\"א. ביצה ד, סע\"ב. רמב\"ם הל' קידוש החודש פ\"ה ה\"ה. תוד\"ה נפסל — מנחות כ, ב. ועוד."]]],[1300251388,"התורה\", ועפ\"ז פארוואס זאל מען מוסיף זיין אן ענין חדש בתפלה —\nאיז אבער די אמירה בתפלה וועגן אהבת ישראל (בתחלת התפלה) און אמירת „אך צדיקים גו'\" (בסוף התפלה) ניט קיין ענין חדש א) אמירת „אך צדיקים\" שטייט שוין אין רמב\"ם, ב\"ח, ט\"ז, סידור האריז\"ל בשם הרש\"ל, וסידור אדה\"ז, סידור „סדר עבודת ישראל\", ובכמה סידורים (כנ\"ל).\nב) וועגן אהבת ישראל שטייט אין סידורי האריז\"ל וכתבי האריז\"ל, מגן אברהם, סידור אדה\"ז, ועוד.\nד. ועוד י\"ל: בהקדם לשון הרמב\"ם⁴⁷ „מצות עשה להתפלל כו' שואל צרכיו שהוא צריך להם\",\nוואס פון דעם איז מובן, אז ווען עס קומען צו נאך צרכי האדם, נייע צרכי האדם, איז א חיוב צו מוסיף זיין בבקשת צרכיו א בקשה אויף מילוי צרכו החדש.\nה. ויהי\"ר אז מ'זאל אננעמען די הצעה זאגן — בתפלה — ענין דאהבת ישראל און ענין פון מנוחה: אהבת ישראל („הריני מקבל כו'\") בתחלת התפלה — ע\"פ דער „הצעה\" פון אריז\"ל און פון דעם אלטן רבי\"ן, און בסוף התפלה — וועגן ענין המנוחה („אך צדיקים גו' ישבו גו'\") — ע\"פ דער\n„הצעה\" פון רמב\"ם, ב\"ח, ט\"ז וכו', און רש\"ל און דעם אלטן רבי\"ן.\nאון די החלטה בזה בעצמה זאל שוין ברענגען די אלע תוצאות טובות, ווי געפסק'נט אין שו\"ע⁴⁸, אז בשעת מ'איז מחליט צו אננעמען אויף זיך א דבר רצוי, איז דאס אליין ברענגט שוין דעם נצחון וביטול הגזירות אויף וועלכע מ'איז מתפלל, און (ניט נאר) א נצחון ע\"י מלחמה, נאר א נצחון באופן פון „פדה בשלום\"⁴⁹.\nובקרוב ממש זאל מען זוכה זיין אויך צו דעם וואס עס שטייט אין מדרש⁵⁰ „ז' כתות של צדיקים בגן עדן זו למעלה מזו, כת ראשונה⁵¹ אך צדיקים יודו לשמך ישבו ישרים את פניך\" — עולמך תראה בחייך⁵² נשמות בגופים זיצן אין דער את פניך בביהמ\"ק השלישי בגאולה האמיתית והשלימה ובמהרה בימינו ממש.",[["47","47","הל' תפלה פ\"א ה\"א-ב."],["48","48","או\"ח סתקע\"א ס\"ג."],["49","49","תהלים נה, יט. וראה ד\"ה פדה בשלום לאדהאמ\"צ (בשערי תשובה ח\"א) פי\"א."],["50","50","ספרי וילש\"ע עה\"פ דברים א, י."],["51","51","„ראשונה\" מלמטה למעלה. ועיין זח\"א פרשתנו עה\"פ בשיעור חומש דהיום (קצ, סע\"ב): לטורא רברבא כו', ובמפרשיו מפני דכל הגדול מחבירו כו'. — וראה ג\"כ זח\"א נט, סע\"א."],["52","52","ברכות יז, סע\"א. וראה תניא פי\"ד (כ, רע\"א)."]]]]});
